import {
  Box,
  Button,
  FormControl,
  Grid,
  IconButton,
  InputAdornment,
  InputLabel,
  Link,
  MenuItem,
  OutlinedInput,
  Select,
  TextField,
  Typography,
} from "@mui/material";
import { ErrorMessage, Form, Formik } from "formik";
import React, { useState } from "react";
import Images from "../../assets";
import { useAppDispatch, useAppSelector } from "../../assets/hooks";
import { phoneNumberAddition, registerSignin } from "../../services";
import { SignUpProps } from "../../types/types";
import * as Yup from "yup";
import { setPopup } from "../../store/Slices/popupSlice";
import { checkUser } from "../../assets/library";
import { Check, Visibility, VisibilityOff } from "@mui/icons-material";
import {
  countryList,
} from "../../assets/menu";
import ReactPhoneInput from "react-phone-input-2";
import { setSharedInfo } from "src/store/Slices/sharedInfoSlice";
import { secondaryButton } from "../styles/customStyles";

const SignUp = () => {
  const dispatch = useAppDispatch();
  const [showPassword, setShowPassword] = useState(false);
  const [showCPassword, setShowCPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const sharedInfo = useAppSelector((state) => state.sharedInfo);
  const [phone, setPhone] = useState({
    countryCode: sharedInfo?.data?.phone?.countryCode||"",
    number: sharedInfo?.data?.phone?.number||"",
  });
  const togglePasswordVisibility = () => {
    setShowPassword(!showPassword);
  };
  const toggleCPasswordVisibility = () => {
    setShowCPassword(!showCPassword);
  };

  const initValues = {
    firstName: "",
    lastName: "",
    email: "",
    password: "",
    cPassword: "",
    country: [] as string[],
    // language:"",
    phone: {
      number: "",
      countryCode: ""
    },
  };

  const signInSchema: Yup.ObjectSchema<SignUpProps> = Yup.object().shape({
    firstName: Yup.string()
      .required("Required")
      .matches(/^[a-zA-Z\s]*$/, "Name should only contain letters and spaces"),
    lastName: Yup.string()
      .required("Required")
      .matches(/^[a-zA-Z\s]*$/, "Name should only contain letters "),
    password: Yup.string()
      .min(3, "Too Short!")
      .max(25, "Too Long!")
      .required("Password is required")
      .matches(
        /^(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,}$/,
        "Password must have 1 uppercase, 1 number, 1 special character, and be at least 8 characters long"
      ),
    cPassword: Yup.string()
      .oneOf([Yup.ref("password")], "Password must match!")
      .required("Confirm password is required!"),
    email: Yup.string()
      .matches(
        /([a-z0-9]+)([{1}])?([a-zA-Z0-9]+)([a-zA-Z0-9]+)([a-z]+)/g,
        "Enter Email Id"
      )
      .required("Enter Email ID")
      .max(40, "Email ID must be at most 40 characters"),
    country: Yup.array()
      .of(Yup.string())
      .min(1, "At least one country is required"),
    // language: Yup.string().required("Please select a preferred language"),
    phone: Yup.object().shape({
      countryCode: Yup.string()
        .required("Country code is required"),
      // .matches(/^\+\d+$/, "Invalid country code"),
      number: Yup.string()
        .required("Phone number is required")
        .matches(/^\d+$/, "Phone number must be numeric"),
    }),
  });

  // const handlePhoneChange = (value: any, data: any, setFieldValue: any) => {
  //   const code = value?.split(data?.dialCode);
  //   setPhone({
  //     countryCode: data?.dialCode,
  //     number: code[1],
  //   });
  //   setFieldValue('phone.countryCode', data?.dialCode);
  //   setFieldValue('phone.number', code[1]);
  // };
  const handlePhoneChange = (value: string, data: any,setFieldValue:any) => {
    const dialCode = data?.dialCode || ""; 
    const enteredCountryCode = dialCode.trim(); 
    if (value.startsWith(enteredCountryCode)) {
        setPhone({
            countryCode: "+"+enteredCountryCode,
            number: value.slice(enteredCountryCode.length).trim() 
        });
     setFieldValue('phone.countryCode', "+"+enteredCountryCode);
    setFieldValue('phone.number', value.slice(enteredCountryCode.length).trim());

    } else {
        const codeSplit = "+"+value.split(dialCode);
        const enteredPhoneNumber = codeSplit.length > 1 ? codeSplit[1].trim() : ""; 
        setPhone({
            countryCode: enteredCountryCode,
            number: enteredPhoneNumber
        });
        setFieldValue('phone.countryCode', "+"+enteredCountryCode);
    setFieldValue('phone.number', enteredPhoneNumber);
    }
};
  const onSubmit = async (values: any) => {
    let countryCode = values.countryCode;
    if (!countryCode.startsWith("+")) {
      countryCode = `+${countryCode}`;
    }
    const formattedValues = {
      // ...values,
      phone: {
        ...values,
        countryCode: countryCode,
      },
    };
    setLoading(true)
    try {
      const response = await phoneNumberAddition(formattedValues);
      if (response) {
        const sharedInfoData = sharedInfo.data;
        dispatch(
          setSharedInfo({
            ...sharedInfoData,
            phone: formattedValues.phone,
          })
        );
        dispatch(
          setPopup({
            show: true,
            data: {
              container: {
                name: "phoneverification",
                data: response.data.message,
                dimensions: {
                  width: "400px",
                  close: "none",
                  show:"none"
                },
              },
              type: "custom",
            },
          })
        );
        setLoading(false)
      } else {
        setLoading(false);
      }
    } catch (err) {
      setLoading(false);
      if (err === "Otp not sent") {
        dispatch(
          setPopup({
            show: true,
            data: {
              container: {
                name: "error",
                data: "Please provide a valid number",
                dimensions: {
                  width: "30%",
                  height: "40%",

                },
              },
              type: "custom",
            },
          })
        );
      } else {
        dispatch(
          setPopup({
            show: true,
            data: {
              container: {
                name: "error",
                data: err,
                dimensions: {
                  width: "30%",
                  height: "40%",
                },
              },
              type: "custom",
            },
          })
        );
      }
      setTimeout(() => {
        dispatch(
          setPopup({
            show: true,
            data: {
              container: {
                name: "phonenumber",
                dimensions: {
                  width: "400px",
                  height: "35%",
                  close: "none",
                  show:"none"
                },
              },
              type: "custom",
            },
          })
        );
      }, 1000);
    }
  };

  const onSubmitForm = async (values: SignUpProps) => {
    setLoading(true)
    let data = {
      firstName: values.firstName,
      lastName: values.lastName,
      email: values.email,
      password: values.password,
      // cPassword: values.,
      country: values.country,
      // language:values.language,
    }
    // console.log(values)
    const response = await registerSignin(data);
    if (response.data.success) {
      localStorage.setItem("_auth", response?.data?.data?.AccessToken);
      localStorage.setItem("register", "registered");
      checkUser();
      onSubmit(phone);
      // dispatch(
      //   setPopup({
      //     show: true,
      //     data: {
      //       container: {
      //         name: "phonenumber",
      //         dimensions: {
      //           width: "500px",
      //         },
      //       },
      //       type: "custom",
      //     },
      //   })
      // );
      setLoading(false)
    } else {
      // console.log("error");
      setLoading(false)

    }
  };

  return (
    <Box sx={{ height: "100%" }}>
      <Grid container sx={{ height: "100%" }}>
        <Grid item xs={0} sm={12} md={5.5}sx={{ background: "#FFBEB5",display: {sm:"flex",xs:"none"}, gap: "5px", justifyContent: "center", flexDirection: "column", alignItems: "center", position: "relative" }}>
          <img src={Images.loginImg} alt="loginImg" style={{ width: "200px" }} />
          <Typography fontSize="1.35rem" color="#fff" sx={{ mt: 1 }}>We make studying abroad easier</Typography>
          <Typography color="#FFFFFF80" fontSize="0.9rem">Over 8000+ Universities and 70000+ Courses</Typography>
          <p style={{
            position: 'absolute',
            left: '10%',
            top: '12%', background: "#FF9081", width: "1rem", height: "1rem", margin: 0, borderBottomLeftRadius: "20px", transform: "rotate(-130deg)"
          }}></p>
          <p style={{
            position: 'absolute',
            right: '0',
            top: '20%', background: "rgb(255 144 129 / 32%)", width: "1.2rem", height: "2rem", margin: 0, borderRadius: "100PX 0 0 100px"
          }}></p>
        </Grid>
        <Grid item xs={12} md={6.5} sx={{ display: "flex", flexDirection: "column", justifyContent: "center", alignItems: "center" }}>
          <Box sx={{ px: { xs: 2, sm: 4 }, width: "80%" }}>
            <Box sx={{ mb: 1.5, display: "flex", justifyContent: "center", position: "relative" }}>
              <Box component="img" src={Images.oneWindow} alt="logo" sx={{ width: { xs: "120px", lg: "180px" } }} />
              <img src={Images.flightRight} alt="flight" style={{ width: "3.5rem", height: "3.5rem", position: "absolute", left: "-40px" }} />
              <img src={Images.passport} alt="flight" style={{ width: "35px", height: "35px", position: "absolute", right: "-25px", top: "-25px" }} />

            </Box>
            <Formik
              initialValues={initValues}
              validationSchema={signInSchema}
              onSubmit={(values: SignUpProps) => onSubmitForm(values)}
              enableReinitialize={true}
            >
              {({ errors, values, handleChange, touched, setFieldValue }) => {
                // console.log(errors)

                return (
                  <Form>
                    <Grid container spacing={2} sx={{ mt: 2,height:{md:"380px"},overflow:"auto" }} >
                      <Grid item xs={12} md={6}>
                        <TextField
                          id="firstName"
                          name="firstName"
                          type="text"
                          size="small"
                          placeholder="First name *"
                          value={values.firstName}
                          onChange={handleChange}
                          fullWidth
                          label="First name *"
                          error={touched.firstName && Boolean(errors.firstName)}
                        />
                        <div style={{ color: "#d32f2f", fontSize: "12px" }}>
                          <ErrorMessage name="firstName" component="div" />
                        </div>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <TextField
                          id="lastName"
                          name="lastName"
                          type="text"
                          size="small"
                          label="Last name *"

                          placeholder="Last name *"
                          value={values.lastName}
                          onChange={handleChange}
                          fullWidth
                          error={touched.lastName && Boolean(errors.lastName)}
                        />
                        <div style={{ color: "#d32f2f", fontSize: "12px" }}>
                          <ErrorMessage name="lastName" component="div" />
                        </div>
                      </Grid>
                      <Grid item xs={12}>
                        <TextField
                          id="email"
                          name="email"
                          type="email"
                          placeholder="Email *"
                          label="Email *"

                          value={values.email}
                          onChange={handleChange}
                          fullWidth
                          error={touched.email && Boolean(errors.email)}
                          size="small"
                        />
                        <div style={{ color: "#d32f2f", fontSize: "12px" }}>
                          <ErrorMessage name="email" component="div" />
                        </div>
                      </Grid>
                      <Grid item xs={12}>
                        <TextField
                          id="password"
                          name="password"
                          size="small"
                          label="Password *"

                          type={showPassword ? "text" : "password"}
                          placeholder="Password *"
                          value={values.password}
                          onChange={handleChange}
                          error={touched.password && Boolean(errors.password)}
                          // helperText={touched.password && errors.password}
                          sx={{
                            "&::placeholder": {
                              color: "#000 !important"
                            },
                            '& .MuiOutlinedInput-root .Mui-error': {
                              '& fieldset': {
                                borderColor: 'red',
                              },
                            },
                          }}
                          fullWidth
                          InputProps={{
                            endAdornment: (
                              <InputAdornment position="end">
                                <IconButton
                                  edge="end"
                                  onClick={togglePasswordVisibility}
                                  sx={{
                                    position: "absolute",
                                    right: "20px",
                                    zIndex: 1,
                                    background: "#fff",
                                    "& .MuiSvgIcon-root ": {
                                      fontSize: "1.3rem"
                                    }
                                  }}
                                >
                                  {showPassword ? <Visibility /> : <VisibilityOff />}
                                </IconButton>
                              </InputAdornment>
                            ),
                          }}
                        />
                        <div style={{ color: "#d32f2f", fontSize: "12px" }}>
                          <ErrorMessage name="password" component="div" />
                        </div>
                      </Grid>
                      <Grid item xs={12}>
                        <TextField
                          id="cPassword"
                          name="cPassword"
                          size="small"
                          label="Confirm password  *"

                          type={showCPassword ? "text" : "password"}
                          placeholder="Confirm password *"
                          value={values.cPassword}
                          onChange={handleChange}
                          fullWidth
                          error={touched.cPassword && Boolean(errors.cPassword)}
                          // helperText={touched.cPassword && errors.cPassword}
                          InputProps={{
                            endAdornment: (
                              <InputAdornment position="end">
                                <IconButton
                                  edge="end"
                                  onClick={toggleCPasswordVisibility}
                                  sx={{
                                    position: "absolute",
                                    right: "20px",
                                    zIndex: 1,
                                    background: "#fff",
                                    "& .MuiSvgIcon-root ": {
                                      fontSize: "1.3rem"
                                    }
                                  }}
                                >
                                  {showCPassword ? <Visibility /> : <VisibilityOff />}
                                </IconButton>
                              </InputAdornment>
                            ),
                          }}
                        />
                        <div style={{ color: "#d32f2f", fontSize: "12px" }}>
                          <ErrorMessage name="cPassword" component="div" />
                        </div>

                      </Grid>
                      <Grid item xs={12}>
                      <FormControl sx={{ width: "100%" }}>
  <InputLabel id="country-label">Desired study destinations *</InputLabel>
  <Select
    id="Country"
    size="small"
    name="country"
    value={values.country}
    onChange={handleChange}
    fullWidth
    multiple
    labelId="country-label"  // Connect the label to the select
    input={<OutlinedInput label="Desired study destinations *" />}  // Attach label to OutlinedInput
    error={touched.country && Boolean(errors.country)}
    renderValue={(selected: unknown) => {
      const selectedArray = selected as string[];
      return selectedArray.join(", "); // Show selected countries
    }}
  >
    {countryList.map((name: string) => (
      <MenuItem
        key={name}
        value={name}
        sx={{
          "& .MuiTypography-root": {
            fontSize: "14px !important",
          },
          "& .MuiSvgIcon-root": {
            fontSize: "1rem",
          },
          whiteSpace: "normal",
        }}
      >
        {name}
        {values.country?.includes(name) && (
          <Check sx={{ marginLeft: "auto", fontSize: "1rem" }} />
        )}
      </MenuItem>
    ))}
  </Select>
</FormControl>

                        <div style={{ color: "#d32f2f", fontSize: "12px" }}>
                          <ErrorMessage name="country" component="div" />
                        </div>
                      </Grid>
                      {/* <Grid item xs={12}>
                  <Select
                    id="language"
                    size="small"
                    name="language"
                    displayEmpty
                    defaultValue=""
                    value={values.language}
                    onChange={handleChange}
                    fullWidth
                    // IconComponent={ExpandMoreIcon}
                    error={touched.language && Boolean(errors.language)}
                    // helperText={touched.language && errors.language}
                  >
                    <MenuItem
                      disabled
                      value=""
                      sx={{
                        "& .MuiTypography-root": {
                          fontSize: "14px !important",
                        },
                      }}
                    >
                      Preferred Language *
                    </MenuItem>

                    {["English","Hindi","Telugu"].map((name) => (
                      <MenuItem
                        key={name}
                        value={name}
                        sx={{
                          "& .MuiTypography-root": {
                            fontSize: "14px !important",
                          },
                          "& .MuiSvgIcon-root ": {
                            fontSize: "1rem",
                          },
                          whiteSpace: "normal",
                        }}
                      >
                        {name}
                      </MenuItem>
                    ))}
                  </Select>
                  <div style={{ color: "#d32f2f", fontSize: "12px" }}>
                    <ErrorMessage name="language" component="div" />
                  </div>
                </Grid> */}
                      <Grid item xs={12}>
                        <ReactPhoneInput
                          value={`${phone.countryCode} ${phone.number}`}
                          onChange={(value, data) => handlePhoneChange(value, data, setFieldValue)}
                          country="in"
                        />
                        {touched.phone?.countryCode && errors.phone?.countryCode && (
                          <Typography variant="caption" color="error" sx={{ mr: 2 }}>
                            {errors.phone.countryCode}
                          </Typography>
                        )}
                        {touched.phone?.number && errors.phone?.number && (
                          <Typography variant="caption" color="error">
                            {errors.phone.number}
                          </Typography>
                        )}
                      </Grid>
                      
                    </Grid>
                    <Grid container spacing={2}> 
                    <Grid item xs={12} sx={{ display: "flex", justifyContent: "center", mt: 1 }}>
                        <Button
                          sx={[secondaryButton, { width: "200px" }]}
                          type="submit"
                        >
                          {loading ? (
                            <img
                              src={Images.standardLoader}
                              alt="load"
                              style={{
                                width: "20px",
                                height: "20px",
                                padding: "5px",
                              }}
                            />
                          ) : (
                            "Register"
                          )}

                        </Button>
                      </Grid>
                      <Grid item xs={12} sx={{ display: "flex", justifyContent: "center" }}>
                        <Typography
                          sx={{
                            color: "#30336380",
                            fontSize: "1rem",
                            fontWeight: 500,
                            display: "flex",
                            flexDirection: { xs: "column", sm: "row" }
                          }}
                        >
                          {" "}
                          Already have an account ? &nbsp;
                          <Link
                            sx={{
                              textDecoration: "none",
                              color: "#3B3F76",
                              fontWeight: 600,
                              cursor: "pointer",
                            }}
                            onClick={() =>
                              dispatch(
                                setPopup({
                                  show: true,
                                  data: {
                                    container: {
                                      name: "login",
                                      dimensions: {
                                        width: "800px",
                                        height: "70%",
                                        show: "none"

                                      },
                                    },
                                    type: "custom",
                                  },
                                })
                              )
                            }
                          >
                            Login
                          </Link>
                        </Typography>
                      </Grid>
                    </Grid>
                  </Form>
                )
              }

              }
            </Formik>
          </Box>
        </Grid>
      </Grid>
    </Box>
  );
};

export default SignUp;
