import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { Box, Button, Typography, Grid,} from "@mui/material";
import { testReadyStyles } from "src/components/styles/customStyles";
import Images from "src/assets";

interface Status {
  id: number;
  name: string;
  color: string;
  bgcolor: string;
}

const STATUS_OPTIONS: Status[] = [
  { id: 1, name: "Completed Studying", color: "#70A6B2", bgcolor: "#70A6B2" },
  { id: 2, name: "Currently Studying", color: "#FF9784", bgcolor: "#FF9784" },
];

const SelectionCard: React.FC<{ status: Status; selected: boolean; onSelect: () => void }> = ({
  status,
  selected,
  onSelect,
}) => {
  return (
    <Grid  item xs={12} sm={6} md={4} lg={3} sx={{ display: "flex", justifyContent: "center" }}>
      <Typography
        role="button"
        aria-label={status.name}
        sx={{
          position: "relative",
          ...testReadyStyles.card2,
          borderLeft: `10px solid ${status.bgcolor}`,
          width: { xs: "70%", sm: "300px", md: "350px" }, // Responsive width
          textAlign: "center",
          padding: "15px",
          cursor: "pointer",
          backgroundColor: selected ? "#F4F4FF" : "#fff",
          transition: "0.3s ease-in-out",
            "&:hover": { boxShadow: `0px 8px 15px ${status.color}` },
        }}
        onClick={onSelect}
      >
        {selected && (
          <Box
            component="img"
            src={Images.select}
            alt="Selected"
            sx={{ position: "absolute", top: 8, right: 8, width: 20, height: 20 }}
          />
        )}
        <Typography  variant="body1" fontSize={18} color="#495052">
          {status.name}
        </Typography>
      </Typography>
    </Grid>
  );
};

const AcademicsStatus: React.FC = () => {
  const [selectedStatus, setSelectedStatus] = useState<Status | null>(null);
  const navigate = useNavigate();

  const handleSelect = (status: Status): void => {
    setSelectedStatus(status);

    // Define title dynamically
    const newTitle =
      status.id === 1
        ? "What is your final score ?"
        : "Enter your current Academic details";
    
    updateLocalStorage(status.id === 1);
    navigate("/academicscore", { state: { selectedStatus: status, title: newTitle } });
  };
  const updateLocalStorage = (isCompleted: boolean) => {
    let currentValue = localStorage.getItem("user-profile");
    let currentValueObj = currentValue ? JSON.parse(currentValue) : {};
  
    // ✅ Store completedStudies as a root-level key, not inside `education`
    localStorage.setItem(
      "user-profile",
      JSON.stringify({
        ...currentValueObj,
        completedStudies: isCompleted, // ✅ Directly storing at root level
      })
    );
  };
  
  return (
    <Box
      sx={{
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        height: "100vh",
        textAlign: "center",
        position: "relative", // Ensures back button stays at bottom
      }}
    >
      {/* Title */}
      <Typography
        variant="h3"
        sx={{
          fontWeight: 500,
          textAlign: "center",
          maxWidth: "90%",
          fontSize: { xs: "1.5rem", lg: "2rem" },
          mb: { xs: 20, lg: 6 }, // Responsive spacing
        }}
      >
        What is your <span style={{ color: "#F87171" }}>current academic</span> status?
      </Typography>

      {/* Status Cards */}
      <Grid marginBottom={18} container spacing={3} justifyContent="center">
        {STATUS_OPTIONS.map((status) => (
          <SelectionCard

            key={status.id}
            status={status}
            selected={selectedStatus?.id === status.id}
            onSelect={() => handleSelect(status)}
          />
        ))}
      </Grid>

      {/* Back Button - Fixed at Bottom */}
      <Box
        sx={{
          position: "absolute",
          bottom: 30, // Fixed 20px from bottom
          width: "100%",
          display: "flex",
          justifyContent: "center",
          mt: -3, // Moves it slightly up
        }}
      >
        <Button variant="text" sx={{ color: "#495052", fontSize: { xs: "14px", sm: "16px" } }} onClick={() => navigate(-1)}>
          ← Back
        </Button>
      </Box>
    </Box>
  );
};

export default AcademicsStatus;
