import { createSlice, PayloadAction } from '@reduxjs/toolkit';

interface RecommendEditState {
  bachelorsScore: string;
  gradeScale: string;
  backlogs: string;
  englishTestType: string;
  englishTestScore: string;
  academicTestType: string;
  academicTestScore: string;
  country: string;
  subCategory: Array<{ label: string; value: string }>;
  studyLevel: string;
}

const initialState: RecommendEditState = {
  bachelorsScore: '',
  gradeScale: '',
  backlogs: '',
  englishTestType: '',
  englishTestScore: '',
  academicTestType: '',
  academicTestScore: '',
  country: '',
  subCategory: [],
  studyLevel: '', 
};

const recommendEditSlice = createSlice({
  name: 'recommendEdit',
  initialState,
  reducers: {
    setRecommendEditData: (state, action: PayloadAction<Partial<RecommendEditState>>) => {
      return { ...state, ...action.payload };
    },
    clearRecommendEditData: (state) => {
      return initialState;
    },
  },
});

export const { setRecommendEditData, clearRecommendEditData } = recommendEditSlice.actions;
export default recommendEditSlice.reducer; 