import React, { useEffect, useRef, useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import { Box, Button, Typography, Grid, CardContent, TextField, FormControlLabel, Checkbox } from "@mui/material";
import { testReadyStyles } from "src/components/styles/customStyles";


interface TestOption {
  id: number;
  text: string;
  fullform:string,
  icon: JSX.Element;
  color: string;
  bgcolor: string;
}
interface TestComponentProps {
  title: JSX.Element;
  navigatePath: string;
  showCheckbox:Boolean;
  testOptions: TestOption[];
  
}

// const testOptions: TestOption[] = [
//   { id: 1, text: "Taken", icon: <SchoolIcon />, color: "#22D3EE", bgcolor: "#D1D3F9" },
//   { id: 2, text: "Planning to take", icon: <WorkIcon />, color: "#F87171", bgcolor: "#75ECE5" },
//   { id: 3, text: "Not planning to take", icon: <PublicIcon />, color: "#FBBF24", bgcolor: "#FFA89C" },
// ];

const EnglishTest: React.FC<TestComponentProps> = ({ title, navigatePath,showCheckbox=false,testOptions}) => {
  const [selectedTest, setSelectedTest] = useState<TestOption | null>(null);
  const [testValue, setTestValue] = useState<string>("");
  const navigate = useNavigate();
  const location = useLocation();
  console.log("Navigation State:", location.state);  // Log the navigation state
  
  const { name } = location.state || {};  
  console.log("Selected Name:", name); 
  const [btnPop, setBtnPop] = useState(true);
  const [isChecked, setIsChecked] = useState(true); 
  const inputRef = useRef<HTMLInputElement>(null);
  const [error, setError] = useState("");

  const handleSelect = (test: TestOption): void => {
   console.log(test)
    setSelectedTest(test);
    setTestValue("");
    setBtnPop(true)   
    setTimeout(() => {
        inputRef.current?.focus();
      }, 100);
  };

  // {
  //   name:  String,[Graduate Record Examination,Graduate Management Admission Test,Test of English as a Foreign Language,International English Language Testing System,Duolingo English Test,Pearson Test of English,American College Testing]
  //   scores: [{
  //       description: { type: String, enum: ["Total","Verbal Reasoning","Quantitative Reasoning","Analytical Writing Assessment","Reading Comprehension", "Listening Comprehension","Speaking", "Writing", "Integrated Reasoning","Quantitative Section", "Verbal Section", "Listening","Reading", "Literacy", "Conversation", "Comprehension","Production","English", "Math","Science"]},
  //       count: { type: Number, },
  //   }

  const setTest=(collectedData:{name:string,totalScore:number|string})=>{
    console.log("Masters Data",collectedData);
    let currentValue=localStorage.getItem("user-profile");
    let currentValueObj=currentValue?JSON.parse(currentValue):{}
    if(currentValueObj)
    {
      let collectedTestData={
        name:collectedData.name,
        scores:[{
          description:"Total",
          count:collectedData.totalScore,
        }],
      };
      console.log("Test data",collectedTestData);
      let testData=[...(currentValueObj.tests?currentValueObj.tests.filter((item:any)=>item.name!==collectedData.name):[]),collectedTestData];
      localStorage.setItem("user-profile",JSON.stringify({...currentValueObj,tests:testData}));	
    }
  }


  const handleInputChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    let value = event.target.value;

    // Allow empty input for user editing
    if (value === "") {
        setTestValue(value);
        setBtnPop(true); // Disable conftinue button
        setError("");
        return;
    }

    // Ensure only numbers are entered
    // if (!/^\d+$/.test(value)) return;

    const numValue = parseFloat(value);
    if (isNaN(numValue)) return;

    let validationError = "";

    if (selectedTest?.text === "GRE") {
        if (numValue < 260 || numValue > 340 || numValue % 1 !== 0) {
            validationError = "GRE score must be between 260 and 340 ";
        }
    } else if (selectedTest?.text === "GMAT") {
        if (numValue < 200 || numValue > 800 || numValue % 5 !== 0) {
            validationError = "GMAT score must be between 200 and 800 ";
        }
    } else if (selectedTest?.text === "SAT") {
        if (numValue < 200 || numValue > 1600 || numValue % 1 !== 0) {
            validationError = "SAT score must be between 200 and 1600 ";
        }
    } else if (selectedTest?.text === "ACT") {
        if (numValue < 1 || numValue > 36 || numValue % 1 !== 0) {
            validationError = "ACT score must be between 1 and 36 ";
        }
    } else if (selectedTest?.text === "IELTS") {
      const isHalfStep = Math.abs(numValue * 10) % 5 === 0;

    if (numValue < 0 || numValue > 9 || !isHalfStep) {
      validationError = "IELTS score must be between 0 and 9 ";
    }
    } else if (selectedTest?.text === "TOEFL") {
        if (numValue < 0 || numValue > 120 || numValue % 1 !== 0) {
            validationError = "TOEFL score must be between 0 and 120 ";
        }
    } else if (selectedTest?.text === "Duolingo") {
        if (numValue < 0 || numValue > 160 || numValue % 1 !== 0) {
            validationError = "Duolingo score must be between 0 and 160 ";
        }
    } else if (selectedTest?.text === "PET") {
        if (numValue < 0 || numValue > 90 || numValue % 1 !== 0) {
            validationError = "PET score must be between 0 and 90 ";
        }
    }

    // Update state before setting validation errors
    setTestValue(value);
    setError(validationError);
    // Disable continue button if there is an error
    setBtnPop(!!validationError);
};

useEffect(() => {
  const savedData = localStorage.getItem("user-profile");
  if (savedData) {
    const userProfile = JSON.parse(savedData);
    const savedTest = userProfile?.tests?.[0]; // Assuming we have saved data in the tests array
    if (savedTest) {
      setSelectedTest(savedTest); 
      setTestValue(savedTest.scores[0]?.count.toString() || "");
    }
  }
}, []);
  const handleContinue = (): void => {
    if (selectedTest && testValue.trim()) {
      let currentTest=testOptions.find((item)=>item.text===selectedTest.text)
      if(currentTest)
      {
        setTest({name:currentTest?.fullform,totalScore:testValue})
          const selectedData = { id: selectedTest.id, text: selectedTest.text, score: testValue };
          navigate(navigatePath, { state: { selectedData } });
      }
     
    }
  };
  return (
    <Box
      sx={{
        marginTop:{xs:2,lg:-5},
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        height: "100vh",
        textAlign: "center",
        px: { xs: 2, md: 4 },
        
      }}
    >
      <Typography
        variant="h3"
        sx={{
          fontWeight: 500,
          textAlign: "center",
          maxWidth: "90%",
          fontSize: { xs: "1.5rem", lg: "2rem" },
          mb: { xs: 6, lg: 6 },
        }}
      >
        {selectedTest?.text === 'Taken'
          ? `What was your score in ${selectedTest.fullform}?`
          : selectedTest?.text === 'Planning to take'
            ? `When are you planning to take ${selectedTest.fullform}?`
            : typeof title === 'string'
              ? title
              : title}
      </Typography>

      <Grid  container spacing={3} justifyContent="center">
        {testOptions.map((test) => (
          <Grid item xs={12} sm={6} md={4} lg={3} sx={{ display: "flex", justifyContent: "center" }} key={test.id}>
            <Typography
              role="button"
              aria-label={test.text}
              sx={{
                position: "relative",
                ...testReadyStyles.card2,
                borderLeft: `10px solid ${test.bgcolor}`,
                width: { xs: "90%", sm: "300px", md: "350px" },
                height: { xs: 40, lg: 80 }, // Fixed height for alignment
                display: "flex",
                cursor: "pointer",
                background: selectedTest?.id === test.id
                  ? `linear-gradient(145deg, ${test.bgcolor}, #ffffff)`
                  : "transparent",
                transition: "0.4s ease-in-out",
                "&:hover": {
                  boxShadow: `0px 8px 18px ${test.bgcolor}`,
                },
              }}
              onClick={() => handleSelect(test)}
            >
              <CardContent sx={{  display: "flex",justifyContent:'center', flexDirection: {xs:'row',md:'column',lg:'column'}, alignItems: "center", gap: 1,textAlign: 'center', }}>
                <Box sx={{ color: test.color, display: 'flex', justifyContent: 'center', alignItems: 'center' }}>{test.icon}</Box>
                <Typography  variant="body1" fontSize={{xs:12,lg:20}} color="black">
                  {test.text}
                </Typography>
              </CardContent>
            </Typography>
          </Grid>
        ))}
      </Grid>
       {selectedTest && (
            <Box marginTop={{xs:3,lg:4}} >
              <Typography variant="h6" mb={1} fontSize={18}>
                {name}
              </Typography>
              <TextField
                type="number"
                value={testValue}
                onChange={handleInputChange}
                placeholder={selectedTest ? `Enter ${selectedTest.text} score` : "Enter score"}
                inputRef={inputRef}
                InputProps={{
                  inputProps: {
                    style: {
                      MozAppearance: 'textfield',
                    },
                  },
                }}
                sx={{
                    "& .MuiOutlinedInput-root": {
                      height: "55px",
                      width:'230px',
                      borderRadius: "12px",
                      // "& fieldset": { borderLeft: "10px solid #D1D3F9" },
                    },
                   // Hide number input arrows for all browsers
                   '& input[type=number]': {
                     MozAppearance: 'textfield',
                   },
                   '& input[type=number]::-webkit-outer-spin-button, & input[type=number]::-webkit-inner-spin-button': {
                     WebkitAppearance: 'none',
                     margin: 0,
                   },
                  }}
              />
             {error && (
                <Typography color="error" fontSize={14} mt={1} textAlign="left">
                  {error}
                </Typography>
              )}
            </Box>
          )}
     {showCheckbox && (
        <FormControlLabel 
          control={<Checkbox sx={{marginBottom:'3px'}} checked={isChecked} onChange={(e) => setIsChecked(e.target.checked)} />}
          label="I would like to join One Window's Exclusive Test Prep group"
          sx={{  marginTop:{xs:3,lg:14}, color:'lightblack',bottom:0 ,}}
        />
      )}
      <Box
        sx={{
          position: "absolute",
          bottom:{xs:-25,lg:30},
          width: "100%",
          display: "flex",
          justifyContent: "center",
          mt: -2,
          py:3
        }}
      >
        <Button variant="text" sx={{ color: "#888", fontSize: { xs: "14px", sm: "16px",lg:'16px' } }} onClick={() => navigate(-1)}>
          ← Back
        </Button>
        {
          !btnPop && (
             <Button variant="contained" sx={{marginTop:0.7, px: 4, py: 1, borderRadius: "20px",height:'40px',background:"#F48438", "&:hover": {
      backgroundColor: "#d96f2e", // slightly darker shade for hover
    }, }} onClick={handleContinue}>
            Continue
          </Button>
          )
        }
       
      </Box>
    </Box>
  );
};

export default EnglishTest;
