import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { Box, Button, Typography, Grid, CardContent } from "@mui/material";
import { testReadyStyles } from "src/components/styles/customStyles";
import Images from "src/assets";

// Define TypeScript interface for research types
interface ResearchOption {
  id: number;
  text: string;
  icon: string;
  color: string;
  bgcolor: string;
}

// List of research types
const RESEARCH_OPTIONS: ResearchOption[] = [
  { id: 1, text: "National", icon:Images.NationalTeal, color: "#70A6B2", bgcolor: "#70A6B2" },
  { id: 2, text: "International", icon:Images.InternationalPeach, color: "#FF9784", bgcolor: "#FF9784" },
];

// Reusable SelectionCard Component
const SelectionCard: React.FC<{ option: ResearchOption; selected: boolean; onSelect: () => void }> = ({
  option,
  selected,
  onSelect,
}) => {
  return (
    <Grid item xs={12} sm={6} md={4} lg={3} sx={{ display: "flex", justifyContent: "center" }}>
      <Typography
        role="button"
        aria-label={option.text}
        sx={{
          position: "relative",
          ...testReadyStyles.card2,
          borderLeft: `10px solid ${option.bgcolor}`,
          width: { xs: "70%", sm: "300px", md: "350px" },
          textAlign: "center",
          padding: "15px",
          cursor: "pointer",
          background: selected ? `linear-gradient(145deg, ${option.bgcolor}, #ffffff)`
                   
                    : "transparent",
                  transition: "0.4s ease-in-out",
                  "&:hover": {
                    boxShadow: `0px 8px 18px ${option.bgcolor}`,
                  },
        }}
        onClick={onSelect}
      >
        {/* {selected && (
          <Box
            component="img"
            src={Images.select}
            alt="Selected"
            sx={{ position: "absolute", top: 8, right: 8, width: 20, height: 20 }}
          />
        )} */}
        <CardContent sx={{ display: "flex", flexDirection:{xs:'row',md:'column',lg:'column'}, alignItems: "center", gap: 1 }}>
          <Box>
          <img src={option.icon} alt="icon" style={{ width: 36, height: 36 }} />
          </Box>
          <Typography variant="body1" fontSize={18} color="black">
            {option.text}
          </Typography>
        </CardContent>
      </Typography>
    </Grid>
  );
};

const ResearchType: React.FC = () => {
  const [selectedOptions, setSelectedOptions] = useState<ResearchOption[]>([]);
  const navigate = useNavigate();


  const updateLocalStorage = (selectedOptions: ResearchOption[]) => {
    let currentValue = localStorage.getItem("user-profile");
    let currentValueObj = currentValue ? JSON.parse(currentValue) : {};

    // Convert selected options into an array of strings
    const publicationsLevel = selectedOptions.map((option) => option.text); // ["National", "International"]

    localStorage.setItem(
      "user-profile",
      JSON.stringify({
        ...currentValueObj,
        preference: {
          ...currentValueObj.preference,
          publicationsLevel, // ✅ Store as an array of strings
        },
      })
    );
  };
  
  // Handle selection
  const handleSelect = (option: ResearchOption): void => {
    setSelectedOptions((prevSelected) => {
      const isSelected = prevSelected.some((item) => item.id === option.id);
      const newSelection = isSelected
        ? prevSelected.filter((item) => item.id !== option.id) // Remove if already selected
        : [...prevSelected, option]; // Add if not selected
      return newSelection;
    });
  };
  


  // Handle continue navigation
  const handleContinue = (): void => {
    if (selectedOptions.length === 0) {
      console.warn("No options selected!"); // Prevents storing an empty array
      return;
    }

    console.log("Before storing, selectedOptions:", selectedOptions); // Debugging

    updateLocalStorage(selectedOptions); 

  
    navigate("/workexperience");
  };

  return (
    <Box
      sx={{
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        height: "100vh",
        textAlign: "center",
        position: "relative",
      }}
    >
      {/* Title */}
      <Typography
        variant="h3"
        sx={{
          fontWeight: 500,
          textAlign: "center",
          maxWidth: "90%",
          fontSize: { xs: "1.5rem", lg: "2rem" },
          mb: { xs: 20, lg: 6 },
          color:"#495052"
        }}
      >
        What type of <span style={{ color: "#F48438" }}>research paper</span> have you published?
      </Typography>

      {/* Research Options Grid */}
      <Grid marginBottom={20} container spacing={3} justifyContent="center">
        {RESEARCH_OPTIONS.map((option) => (
          <SelectionCard key={option.id} option={option} selected={selectedOptions.some((item) => item.id === option.id)} onSelect={() => handleSelect(option)} />
        ))}
      </Grid>

      {/* Navigation Buttons */}
      <Box
        sx={{
          position: "absolute",
          bottom: 30,
          width: "100%",
          display: "flex",
          justifyContent: "center",
          mt: -3,
        }}
      >
        <Button variant="text" sx={{ color: "#888", fontSize: { xs: "14px", sm: "16px" } }} onClick={() => navigate(-1)}>
          ← Back
        </Button>
        {selectedOptions.length > 0 && (
          <Button variant="contained" sx={{ px: 4, py: 1.5, borderRadius: "20px", ml: 3,background:"#F48438", "&:hover": {
      backgroundColor: "#d96f2e", // slightly darker shade for hover
    }, }} onClick={handleContinue}>
            Continue
          </Button>
        )}
      </Box>
    </Box>
  );
};

export default ResearchType;
