import { Box, Button, Typography, TextField } from "@mui/material";
import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { testReadyStyles } from "src/components/styles/customStyles";

const Personal = () => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    name: "",
    email_id: "",
    phone_number: "",
  });

  const [errors] = useState({
    name: "",
    email_id: "",
    phone_number: "",
  });

  const handleChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setFormData({ ...formData, [event.target.name]: event.target.value });
  };

  const handleSave = () => {
    navigate("/congratulations");
  };

  return (
    <Box
      sx={{
        ...testReadyStyles.container1,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        height: "100vh",
        textAlign: "center",
        position: "relative",
        px: { xs: 2, md: 4 },
        py:0 // Responsive padding
      }}
    >
      {/* Title */}
      <Typography
        variant="h3"
        sx={{
          fontWeight: 500,
          textAlign: "center",
          maxWidth: "90%",
          fontSize: { xs: "1.5rem", lg: "2rem" },
          mb: { xs: 6, lg: 4 },
        }}
      >
        Could you provide <span style={{ color: "#F87171" }}>your details?</span>
      </Typography>

      {/* Input Fields */}
      <Box
        sx={{
          width: { xs: "100%", sm: "80%", md: "50%", lg: "40%" },
          display: "flex",
          flexDirection: "column",
          gap: 2,
        }}
      >
       {[
          { label: "Name", name: "name", type: "text" },
          { label: "Email ID", name: "email_id", type: "text" },
          { label: "Phone Number", name: "phone_number", type: "tel" },
        ].map((field, index) => (
          <TextField
            key={index}
            fullWidth
            name={field.name}
            label={field.label}
            variant="outlined"
            type={field.type}
            value={formData[field.name as keyof typeof formData]}
            onChange={handleChange}
            error={!!errors[field.name as keyof typeof errors]}
            helperText={errors[field.name as keyof typeof errors]}
            sx={{
              "& .MuiOutlinedInput-root": {
                borderRadius: "12px",
                "& fieldset": {
                  borderLeft: `10px solid ${index === 2 ? "#75ECE5" : "#D1D3F9"}`,
                },
              },
            }}
          />
        ))}
      </Box>

      {/* Navigation Buttons */}
      <Box
        sx={{
          position: "absolute",
          bottom: 30,
          width: "100%",
          display: "flex",
          justifyContent: "center",
          gap: 2,
        }}
      >
        <Button variant="text" sx={{ color: "#888", fontSize: { xs: "14px", sm: "16px" } }} onClick={() => navigate(-1)}>
          ← Back
        </Button>
        <Button
          variant="contained"
          sx={{
            px: 4,
            py: 1.5,
            borderRadius: "20px",
            fontSize: { xs: "14px", sm: "16px" },
          }}
          onClick={handleSave}
        >
          Save
        </Button>
      </Box>
    </Box>
  );
};

export default Personal;
