import React, { useState, useEffect } from "react";
import Button from "@mui/material/Button";
import { Grid, Card, Box, MenuItem, FormControl, InputLabel, Select, } from "@mui/material";
import Calendar from "react-calendar";
import "react-calendar/dist/Calendar.css";
import CircularProgress from "@mui/material/CircularProgress";
import { getCounsellorSlots, modifyBooking } from "../../../../services/index";
// import { CustomButton } from "../../../../genericComponents/customButton";
import { useAppDispatch } from "../../../../assets/hooks";
import { updatemeetings } from "../../../../store/Slices/meetings";
import { Event } from "../../../../types/types";
import { secondaryButton } from "../../../../components/styles/customStyles";
import Images from "src/assets";

const Reschedule = ({ data }: any) => {
  const isLoggedIn = localStorage.getItem("_auth");
  const dispatch = useAppDispatch();
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());
  const [availableSlots, setAvailableSlots] = useState<any[]>([]);
  const [selectedSlot, setSelectedSlot] = useState<any>(null);
  const [ApiResponse, SetApiResponse] = useState<any>();
  const [loader, setLoader] = useState<boolean>(false);
  const [loading, setLoading] = useState<boolean>(false);

  useEffect(() => {
    if (isLoggedIn) {
      counsellorSlots(selectedDate);
    }
    // eslint-disable-next-line
  }, []);

  const currentTime = new Date();
  currentTime.setMinutes(currentTime.getMinutes() + 30);

  const counsellorSlots = async (date: Date) => {
    setLoader(true);
    if (ApiResponse && ApiResponse.length > 0) {
      const matchingDate = ApiResponse.find(
        (slot: any) =>
          new Date(slot.date).toDateString() === date.toDateString()
      );

      if (matchingDate && matchingDate.availableSlots) {
        setAvailableSlots(matchingDate.availableSlots);
      } else {
        setAvailableSlots([]);
      }

      setLoader(false);
      return;
    }
    try {
      const response = await getCounsellorSlots(data?.member?._id);

      if (response && response.data !== undefined) {
        setLoader(false);
        SetApiResponse(response?.data?.data);

        const matchingDate = response?.data?.data?.find(
          (slot: any) =>
            new Date(slot.date).toDateString() === date.toDateString()
        );

        if (matchingDate && matchingDate?.availableSlots) {
          setAvailableSlots(matchingDate?.availableSlots);
        } else {
          setAvailableSlots([]);
        }
      } else {
      }
    } catch (error) {
      setLoader(false);
    }
  };

  const isWeekend = (date: Date): boolean => {
    const day = date.getDay();
    return day === 0 || day === 6;
  };

  const eventHandler = async (event: Event) => {
    switch (event.name) {
      case "DateChange":
        const date = event.data instanceof Date ? event.data : null;
        if (date && !isWeekend(date)) {
          setSelectedDate(date);
          counsellorSlots(date);
        }
        break;
      case "counsellorSlotBooking":
        setLoading(true);
        const values = {
          meetingId: data._id, //  => _id of meeting object, not id in meeting.data  
          option: "rescheduleEvent",
          startTime: `${selectedSlot.startTime}`,
          endTime: `${selectedSlot.endTime}`,
          timeZone: "Asia/Kolkata",
        };
        try {
          const response = await modifyBooking(values);
          if (response && response.data !== undefined) {
            dispatch(updatemeetings(response.data));
            setTimeout(() => { }, 2000);
            setLoading(false);
          } else {
            setLoading(false);
          }
        } catch (error) { 
          setLoading(false);

        }
        break;
      default:
        break;
    }
  };

  const filteredSlots = availableSlots?.filter((slot: any) => new Date(slot.startTime) >= currentTime);
  return (
    <React.Fragment>
      {loader ? (
        <div
          style={{
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            height: "300px",
          }}
        >
          <CircularProgress />
        </div>
      ) : (
        <>
          <Grid container spacing={2} sx={{height:"400px"}}>
            <Grid
              sx={{
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                justifyContent: "center",
              }}
              item
              xs={12}
            >
              <Card sx={{mt:2}}>
                <Calendar
                  value={selectedDate}
                  onChange={(e) =>
                    eventHandler({ name: "DateChange", data: e })
                  }
                  minDate={new Date()}
                  maxDate={new Date(Date.now() + 30 * 24 * 60 * 60 * 1000)}
                  tileDisabled={({ date }) => isWeekend(date)}
                />
              </Card>
            </Grid>
            <Grid item xs={12} sx={{ mb: 1,mt:2,display:"flex",flexDirection:"column",justifyContent:"center",alignItems:"center" }}>
              <p style={{ fontSize: "16px" }}>
                Available Slots for {selectedDate?.toLocaleDateString()}
              </p>
              <Box sx={{mt:1}}>
                <FormControl
                  variant="outlined"
                  sx={{
                    width: "300px",
                    marginBottom: "1rem",
                    "& .MuiInputLabel-root": { fontSize: "0.875rem" },
                    "& .MuiSelect-root": { fontSize: "0.875rem" },
                  }}
                >
                  <InputLabel>Select Slot</InputLabel>
                  <Select
                    value={selectedSlot?.startTime}
                    onChange={(e) => {
                      const selectedTime = e.target.value;
                      const slot = availableSlots?.find(
                        (s) =>
                          new Date(s.startTime).toLocaleTimeString([], {
                            hour: "2-digit",
                            minute: "2-digit",
                          }) === selectedTime
                      );
                      setSelectedSlot(slot);
                    }}
                    label="Select Slot"
                    sx={{
                      fontSize: "0.875rem",
                      "& .MuiSelect-select": {
                        border: "none",
                      },
                      "& .MuiOutlinedInput-notchedOutline": {
                        boxShadow: "11px 12px 50px rgb(14 12 4 / 12%)",
                        border: 0,
                      },
                    }}
                    MenuProps={{
                      PaperProps: {
                        sx: {
                          maxHeight: 200,
                          maxWidth: 300,
                          "&.MuiPaper-root": {
                            boxShadow: 3,
                          },
                        },
                      },
                      autoFocus: false,
                    }}
                  >
                    {filteredSlots?.length > 0 ? (
                      filteredSlots.map((slot: any, index: number) => (
                        <MenuItem
                          key={index}
                          value={new Date(slot.startTime).toLocaleTimeString([], {
                            hour: "2-digit",
                            minute: "2-digit",
                          })}
                          sx={{ fontSize: "0.875rem" }}
                        >
                          {new Date(slot.startTime).toLocaleTimeString([], {
                            hour: "2-digit",
                            minute: "2-digit",
                          })}{" "}
                          -{" "}
                          {new Date(slot.endTime).toLocaleTimeString([], {
                            hour: "2-digit",
                            minute: "2-digit",
                          })}
                        </MenuItem>
                      ))
                    ) : (
                      <MenuItem disabled sx={{ fontSize: "0.875rem" }}>
                        No slots available
                      </MenuItem>
                    )}
                  </Select>
                </FormControl>
              </Box>
              <Box sx={{ display: "flex", justifyContent: "center", alignItems: "center", mt: 5 }}>
            {
              <Button sx={secondaryButton} disabled={!selectedSlot}
                onClick={() => eventHandler({ name: "counsellorSlotBooking", data: "" })}
              >
                {loading ?
                  <img src={Images.standardLoader} alt="loader" style={{ width: "20px", height: "20px", padding: "5px" }} />
                  : "Reschedule"}
              </Button>
            }
          </Box>
            </Grid>
          </Grid>
        </>
      )}
    </React.Fragment>
  );
};

export default Reschedule;
