const fetchChats = async () => {
  let allchats = [];
  try {
    const response = await fetchAllChats();

    if (response) {
      allchats = response.data.data.map((chat: ChatType) => ({
        ...chat,
        participants: chat.participants.map((participant) => ({
          ...participant,
          activity: "offline",
        })),
      }));
      dispatch(
        initChats({
          requestStatus: "initiated",
          responseStatus: "recieved",
          haveAnIssue: false,
          issue: "",
          data: allchats,
        })
      );
    }
    return allchats;
  } catch (error) {}
};

const triggerRoot=(triggerObj:TriggerObject)=>{
  // console.log(JSON.stringify(triggerObj,null,2))
  switch(triggerObj.action){
      case "activityList":
          dispatch(updateParticipantsActivity(triggerObj.data))
          break
      case "ping":
          dispatch(updateParticipantActivity({...triggerObj.sender,role:"",activity:triggerObj.data.status}))
          break;

      case "typing":
          dispatch(updateParticipantActivity({...triggerObj.sender,role:"",activity:triggerObj.data==="start"?"typing":"inchat"}))
          break;
      
      case "send":
          console.log("chat send trigger",triggerObj.data.chat)
          dispatch(updateChat(triggerObj.data.chat))
          break;

      case "seen":
          dispatch(updateChat(triggerObj.data));
          break;
  }
}


export const getFriends = (chats: ChatType[], currentUserId: string) => {
  let participants: Participant[] = [];
  let allusers: Participant[] = chats.reduce(
    (accumulator, currentValue) => [
      ...accumulator,
      ...currentValue.participants,
    ],
    participants
  );
  return Array.from(new Set(allusers.map((a) => a._id)))
    .map((_id) => {
      return allusers.find((a) => a._id === _id);
    })
    .filter((user) => user?._id !== currentUserId);
};

export const checkUser = async () => {
  token = localStorage.getItem("_auth");
  
  // Validate token exists and is not empty
  const isValidToken = token && token.trim() !== "";
  
  dispatch(
    setUserAuthStatus({
      isAuthorized: isValidToken ? true : false,
      isRegistered: isValidToken ? true : false,
      role: isValidToken ? "student" : "guest",
    })
  );
  
  if (isValidToken) {
    try {
      // Start session management
      sessionManager.startSession();
      
      getDashboardDetails();
      Socket.removeListener("trigger", triggerRoot);
      Socket.on("trigger", triggerRoot)
      getProfileDetails().then((currentuser: any) => {
        Socket.emit("join", currentuser);
        fetchChats().then((allchats) => {
          if (currentuser) {
            let friends: any = getFriends(allchats, currentuser._id);
            let triggerObj: TriggerObject = {
              action: "ping",
              sender: currentuser,
              recievers: friends,
              data: { respond: false, status: "online" },
            };
            Socket.emit("trigger", triggerObj);
          }
        });
      });
    } catch (error) {
      console.error("Error in checkUser:", error);
      // If there's an error, clear the invalid token
      localStorage.removeItem("_auth");
      sessionManager.stopSession();
      dispatch(
        setUserAuthStatus({
          isAuthorized: false,
          isRegistered: false,
          role: "guest",
        })
      );
    }
  } else {
    // Clear any invalid token
    localStorage.removeItem("_auth");
    sessionManager.stopSession();
  }
};

export const normalizeType = (type: string | undefined | null): string => {
  if (!type) return "";
  const words = type.replace(/([a-z])([A-Z])/g, "$1 $2").split(" ");
  return words
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(" ");
};

export const getChatType = (chat: Chat) => {
  return chat.participants.find(
    (participant) => participant.userType === "member"
  )
    ? "advisors"
    : "community";
};

export const setWordCase = (word: string | undefined) => {
  if (word && word.length !== 0) {
    let lowercase = word.toLowerCase();
    return lowercase[0].toUpperCase() + lowercase.substring(1);
  } else {
    return "";
  }
};

