export const setUrl = (baseUrl:string,queryParams:{label:string,data:any}[]) =>{
  return queryParams.reduce((url,current,i)=>(current.data!==undefined || current.data!=null)?(i===queryParams.length-1?(url+current.label+"="+encodeURIComponent(JSON.stringify(current.data))):(url+current.label+"="+encodeURIComponent(JSON.stringify(current.data))+"&")):url,baseUrl)
}

export const getComponent = (id: string) => {
  let index = COMPONENTS.findIndex((item) => item.name === id);
  return COMPONENTS[index].component;
};

