export const getExploreUrl=(type:string,data:any)=>{
  const encodedUrl = window.location.search.slice(1); 
  let decodedUrl = "";
  try {
    decodedUrl = window.atob(encodedUrl);
  } catch (error) {
    console.error("Error decoding URL", error);
    decodedUrl = ""; 
  }
  const searchParams = new URLSearchParams(decodedUrl);
  let filterUrl=searchParams.get("FilterData");
  let activeUrl=searchParams.get("activeTab")
  let FilterData= (filterUrl!==undefined && filterUrl!==null)? JSON.parse(filterUrl) : [];
  let activeTab=activeUrl?JSON.parse(activeUrl):"courses"
  console.log("URLLLLLL",activeTab,FilterData);
  let url=`activeTab=${(type==="activeTab"?JSON.stringify(data):JSON.stringify(activeTab))}&FilterData=${type==="filterData"?(encodeURIComponent(JSON.stringify(data))):encodeURIComponent(JSON.stringify(FilterData))}`
  const subDisciUrl = (`/explore?${window.btoa(url)}`);
  return subDisciUrl
}

