export const FilterHandler=(data: {
  data: ListItem;
  filterInfo: FilterInfo;
  filter: FilterSelected;
}) => {
  let currenFilterdata = data.filter;
  let filterdata: FilterSelected = { ...data.filter };
  if (data.filterInfo?.selectedType === "single") {
    if (currenFilterdata?.data.length ===0) {
      filterdata.data.push(data.data);
    } else {
      if(currenFilterdata?.data[0].name===data.data.name)
      {
        filterdata.data = []
      }
      else
      {
        filterdata.data = [data.data]
      }
    }
  }
  if (data.filterInfo?.selectedType === "multi") {
    currenFilterdata = data.filter
    if (currenFilterdata?.data.find((item) => item.name === data.data.name)) {

      filterdata.data = filterdata.data.filter((item) => item.name !== data.data.name);
    } else {
      filterdata.data = [...filterdata.data, data.data];
    }
  }
  return filterdata;
};

export const FiltersHandler=(data: FilterSelected,appliedFilters:FilterSelected[]) => {
  let filterdata: FilterSelected = data;
  let filterindex = appliedFilters.findIndex(
    (filter) => filter.type === data.type
  );
  if (filterdata.data.length !== 0) {
    if (filterindex === -1) {
      appliedFilters = [...appliedFilters, filterdata];
    } else {
      let temp = [...appliedFilters];
      temp.splice(filterindex, 1, filterdata);
      appliedFilters= temp;
    }
  } else {
    appliedFilters = [
      ...appliedFilters.filter((filter) => filter.type !== data.type),
    ];
    
  }
  return appliedFilters;
};

export const  formatDate = (dateString: string, day: boolean): string =>{
  const options: Intl.DateTimeFormatOptions = day
    ? { year: "numeric", month: "long" }
    : { year: "numeric", month: "long", day: "numeric" };
  return new Date(dateString).toLocaleDateString(undefined, options);
}
