import React, { useContext, useState } from 'react';
import { useCallback } from 'react';
import useRazorpay from 'react-razorpay';
import Images from '../../../../assets';
import axios from 'axios';
import { checkOutRoute, fetchorderRoute, recheckOutRoute, updateCart } from '../../../../services';
import { useAppDispatch, useAppSelector } from '../../../../assets/hooks';
import { closePopup, setPopup } from 'src/store/Slices/popupSlice';
import Context from 'src/assets/constants/context';
import { setCart } from 'src/store/Slices/cartSlice';
import { addorders, updateorders } from 'src/store/Slices/orderSlice';
import { Button } from '@mui/material';
import { secondaryButton } from 'src/components/styles/customStyles';
import { addApplication } from 'src/store/Slices/applicationsSlice';
import ConfirmDialog from 'src/genericComponents/modalPopup/confirmDialog';
// import { removeCart } from '../../../../store/Slices/cartSlice';

export default function Razor(props: any) {
  const [Razorpay] = useRazorpay();
  const { selectedPackage } = useContext(Context);
  const { courses } = useContext(Context);
  const [open,setOpen] = useState(false)
  const profile = useAppSelector(store => store.sharedInfo)
  const dispatch = useAppDispatch();
  const handlePayment = useCallback(async () => {
    try {
      let response;
      if (props.type === "reorder") {
        response = await recheckOutRoute(props.data);
      } else {
        response = await checkOutRoute({
          packageId: selectedPackage,
          products: props.data
        });
      }
      if (response) {
        if (props.type !== "reorder") {
          for (const product of courses) {
            const values = {
              action: "remove",
              category: product.category,
              courseId: product.course._id,
              intake: product.intake,
              itemId: product._id,
            };

            const removeResponse = await updateCart(values);
            if (removeResponse.data.success) {
              dispatch(setCart(removeResponse.data.data));
              dispatch(closePopup())
            } else {
            }
          }
          dispatch(addorders(response.data.data.order))
        }
        interface RazorpayOptions {
          key: string;
          amount: string;
          currency: string;
          name: string;
          description: string;
          image: string;
          order_id: string;
          callback_url?: string;
          redirect?: boolean;
          handler: (response: {
            razorpay_payment_id: string;
            razorpay_order_id: string;
            razorpay_signature: string;
          }) => void;
          prefill: {
            name: string | undefined;
            email: string | undefined;
            contact: number | undefined;
          };
          notes: {
            address: string;
          };
          theme: {
            color: string;
          };
        }
        if(response?.data.data.razorPay !== null){
          const options: RazorpayOptions = {
            key: 'rzp_live_K7hVMliRmR7G9j', 
            amount: response?.data.data.order?.paymentDetails?.amount,
            currency: response?.data.data.order?.paymentDetails?.currency,
            name: 'ONE WINDOW OVERSEAS EDUCATION PRIVATE LIMITED',
            description:JSON.stringify(response?.data?.data?.order?.paymentDetails?.misc?.notes),
            image: Images.oneWindow,
            order_id: response?.data.data.order?.paymentDetails?.razorpay_order_id,
            handler: async function (response) {
              // console.log(response)
              try {
                const result = await axios.post('https://campusroot.com/api/v1/student/payment-verification', response,
                  {
                    headers: {
                      "Content-Type": "application/json",
                    }
                  },);
                const response1 = await fetchorderRoute(result.data.data.reference);
  
                if (response1) {
                    dispatch(updateorders(response1.data.data));
                    dispatch(addApplication(response1.data.data?.products?.map((item:any)=>item)));
                }
                dispatch(
                  setPopup({
                    show: true,
                    data: {
                      container: {
                        name: "success",
                        data: result.data.message,
                        dimensions: {
                          width: "30%",
                          height:"40%",
                          show:"none"
  
                        },
                      },
                      type: "custom",
                    },
                  })
                )
              } catch (error) {
                // console.error('Error during payment success handling', error);
                dispatch(
                  setPopup({
                    show: true,
                    data: {
                      container: {
                        name: "error",
                        data: "Error during payment success handling.Try refresh, if problem persists",
                        dimensions: {
                          width: "400px",
                          show:"none"
                        },
                      },
                      type: "custom",
                    },
                  })
                )
              }
            },
            prefill: {
              name: profile?.data?.firstName,
              email: profile?.data?.email,
              contact: profile?.data?.phone?.number,
            },
            notes: {
              address: 'One Window',
            },
            theme: {
              color: '#61dafb',
            },
          };
          const rzp = new Razorpay(options)
          rzp.open();
          // console.log(options)
        }else{
          dispatch(
            setPopup({
              show: true,
              data: {
                container: {
                  name: "error",
                  data: "Error during payment success handling.Try refresh, if problem persists",
                  dimensions: {
                    width: "400px",
                    show:"none"
                  },
                },
                type: "custom",
              },
            })
          )
        }
      }

    } catch (error) {
      console.error('Error creating order', error);
      dispatch(
        setPopup({
          show: true,
          data: {
            container: {
              name: "error",
              data: "Error during payment success handling.Try refresh, if problem persists",
              dimensions: {
                width: "400px",
                show:"none"
              },
            },
            type: "custom",
          },
        })
      )
    }
    // eslint-disable-next-line
  }, [Razorpay]);
  return (
    <div >
      <header >
        <Button sx={[secondaryButton,{width:"200px"}]} onClick={()=>setOpen(true)}>
         {props.total === "0"  ? "Apply for free" :"Proceed to pay" } 
        </Button>
      </header>
      <ConfirmDialog
        open={open}
        handleClose={() => setOpen(false)}
        additionalData={{
          onSubmit: () => handlePayment(),
          title: "Are you sure you want to proceed ?",
          content:
            "",
        }}
      />
    </div>
  );
}
