import { Box, Button, TextField } from '@mui/material'
import React, { useState } from 'react'
import { useAppDispatch } from 'src/assets/hooks'
import { secondaryButton } from 'src/components/styles/customStyles'
import { closePopup } from 'src/store/Slices/popupSlice'

const CustomField = (data: any) => {
  const dispatch = useAppDispatch();
  const [value, setValue] = useState(data.data.fieldName); 
  const handleSave = () => {
    data.data.setFieldName(value); 
    dispatch(closePopup());
  };

  return (
    <div style={{ padding: "2rem 3rem" }}>
      <TextField
        value={value}
        onChange={(e) => setValue(e.target.value)}
        placeholder={data.data.placeholder}
        variant="outlined"
        name={data.data.name}
        size="small"
        autoComplete="off"
        fullWidth
      />
      <Box sx={{ display: "flex", justifyContent: "end" }}>
        <Button
          sx={[secondaryButton, { mt: 2, width: "80px" }]}
          onClick={handleSave} 
        >
          Save
        </Button>
      </Box>
    </div>
  );
};


export default CustomField
