import { Box, Button,  Typography } from "@mui/material";
import React from "react";
import { useNavigate } from "react-router-dom";
import { useAppDispatch } from "src/assets/hooks";
import { closePopup } from "src/store/Slices/popupSlice";
// import EastIcon from "@mui/icons-material/East";
import {secondaryButton } from "src/components/styles/customStyles";
import Images from "src/assets";

const  Success = ({ data, link }: any) => {
  const capitalizedText = data?.charAt(0)?.toUpperCase() + data?.slice(1);
  const navigate = useNavigate();
  const dispatch = useAppDispatch();

  return (
<Box sx={{ position: "relative", minHeight: "100px", display: "flex", flexDirection: "column", justifyContent: "center",p:2,alignItems:"center" }}>
  <img src={Images.successMsg} alt="error" style={{height:"6rem"}}/>
  <Typography color="#2C2F5C" sx={{fontSize:"2rem"}}>Success!</Typography>
  <Typography color="#2C2F5C80" sx={{textAlign:"center",width:{xs:"90%",lg:"80%"}}}>{capitalizedText}</Typography>

  <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center", mt: 3,gap:"20px" }}>
    <Box>
    {link && (
      <Button
      sx={[secondaryButton, { width: "150px", p: 0,fontWeight:"400" }]}
        onClick={() => {
          dispatch(closePopup());
          navigate(`${link}`);
        }}
      >
        Go to cart
      </Button>
    )}
    </Box>
    <Button
      sx={[secondaryButton, { width: "100px", p: 0,fontWeight:"400" }]}
      onClick={() => {
        dispatch(closePopup());
      }}
    >
      Okay
    </Button>
  </Box>
</Box>

  );
};

export default  Success;
