import React from "react";
import DatePicker from "react-datepicker";
import "react-datepicker/dist/react-datepicker.css";

interface DatePickerComponentProps {
  selectedDate: any;
  onChange: (date: Date | null) => void;
  minDate?: Date;
  maxDate?: Date;
  placeholderText: string;
}

const DatePickerComponent: React.FC<DatePickerComponentProps> = ({
  selectedDate,
  onChange,
  minDate,
  maxDate,
  placeholderText,
}) => {
  return (
    <DatePicker
  selected={selectedDate ? new Date(selectedDate.slice(0, 10)) : null}
  onChange={onChange}
  minDate={minDate}
  maxDate={maxDate}
  dateFormat="dd-MM-yyyy"
  placeholderText={placeholderText}
  showMonthDropdown
  showYearDropdown
  dropdownMode="select"
  showPopperArrow={false}
  yearDropdownItemNumber={10}
  className="date-picker"
  popperClassName="custom-popper"
  popperContainer={({ children }) => <div className="modal">{children}</div>} // Render popper within a custom container
  portalId="root" // Use React Portals to render inside a specific DOM element
/>
  );
};

export default DatePickerComponent;
