import { PayloadAction, createSlice } from "@reduxjs/toolkit";
import { checklist, StoreItem } from "../../types/types";

let initialState:StoreItem<checklist[]>={
    requestStatus:"not_initiated",
    responseStatus:"not_recieved",
    haveAnIssue:false,
    issue:"",
    data:[]
}

export const checklistSlice=createSlice({
    name:'checklist',
    initialState:initialState,
    reducers:{
        initchecklist:(state,action:PayloadAction<StoreItem<checklist[]>>)=>({...action.payload}),
        addchecklist:(state,action:PayloadAction<checklist>)=>{state.data.push(action.payload)},
        // updatechecklist:(state,action:PayloadAction<checklist>)=>{
        //     let index=state.data.findIndex((item)=>item._id===action.payload._id);
        //     state.data[index]=action.payload;
        // },
        // removechecklist:(state,action:PayloadAction<string>)=>{state.data=state.data.filter((item)=>item._id!==action.payload)},
        resetchecklist:(state,action:PayloadAction)=>({...initialState})

    }
})

export const {initchecklist,addchecklist,resetchecklist}=checklistSlice.actions;
export default checklistSlice.reducer;