import { Box, Grid, Typography } from '@mui/material';
import React, { useEffect, useState } from 'react';
// import Images from 'src/assets';
import { Form, Formik, ErrorMessage } from "formik";
import * as Yup from "yup";
import { CustomButton } from "../../genericComponents/customButton";
import { verifyEmailPhone, verifyEmailPhoneOtp } from "../../services";
import ReactPhoneInput from "react-phone-input-2";
import "react-phone-input-2/lib/style.css";
import { useAppDispatch, useAppSelector } from "../../assets/hooks";
// import { secondaryButton } from 'src/components/styles/customStyles';
import OTPInput from 'src/components/authentication/otpInput';
import KeyboardBackspaceIcon from '@mui/icons-material/KeyboardBackspace';
import { closePopup } from 'src/store/Slices/popupSlice';
import { setPhoneVerificationStatus } from 'src/store/Slices/verificationSlice';
import { setUserAuthStatus } from 'src/store/Slices/userAuthSlice';
import parsePhoneNumberFromString from 'libphonenumber-js';

const PhoneNumber = () => {
    const [active, setActive] = useState<"phone" | "verify">("phone");
    const [loading, setLoading] = useState(false);
    const [timer, setTimer] = useState(60);
    const [canRetry, setCanRetry] = useState(false);

    const dispatch = useAppDispatch();
    const sharedInfo = useAppSelector((state) => state.sharedInfo);

    const [phone, setPhone] = useState({
        countryCode: sharedInfo?.data?.phone?.countryCode || "",
        phoneNumber: sharedInfo?.data?.phone?.number || "",
    });

    const validationSchema = Yup.object().shape({
        phone: Yup.object().shape({
            countryCode: Yup.string().required("Country code is required"),
            phoneNumber: Yup.string()
                .required("Phone number is required")
                .test("is-valid-phone", "Invalid phone number", function (value) {
                    const { countryCode } = this.parent;
                    if (!countryCode || !value) return false; // Ensure both countryCode and number are provided

                    try {
                        const phoneNumber = parsePhoneNumberFromString(`${countryCode}${value}`, countryCode);
                        return phoneNumber?.isValid();
                    } catch (error) {
                        return false;
                    }
                }),
        }),
    });

    const handlePhoneChange = (value: string, data: any) => {
        const dialCode = data?.dialCode || "";
        if (value.startsWith(dialCode)) {
            setPhone({
                countryCode: "+" + dialCode,
                phoneNumber: value.slice(dialCode.length).trim(),
            });
        }
    };
    const otpSchema = Yup.object().shape({
        otp: Yup.string().required("Required").matches(/^[0-9]+$/, "Must be only digits").min(6, "Must be exactly 6 digits").max(6, "Must be exactly 6 digits"),
    });

    useEffect(() => {
        if (timer > 0 && active === "verify") {
            const countdown = setInterval(() => setTimer((prevTime) => prevTime - 1), 1000);
            return () => clearInterval(countdown);
        } else if (timer === 0) setCanRetry(true);
    }, [timer, active]);

    const handleRetry = () => {
        setTimer(180);
        setCanRetry(false);
        onSubmitForm(phone);
    };

    const formatTime = (seconds: number) => {
        const minutes = Math.floor(seconds / 60);
        const remainingSeconds = seconds % 60;
        return `${minutes}:${remainingSeconds < 10 ? '0' : ''}${remainingSeconds}`;
    };

    const onSubmitForm = async (values: any) => {
        setLoading(true);
        try {
            const response = await verifyEmailPhone(values);
            if (response) {
                setActive("verify")
            } else {
                // console.log(response)
            }
            setLoading(false);
        } catch (err) {
            setLoading(false);
        }
    };

    const verifyCodeSubmit = async (values: any) => {
        setLoading(true);
        try {
            const response = await verifyEmailPhoneOtp(values);

            if (response?.data?.success) {
                // Set phone verification status
                dispatch(setPhoneVerificationStatus(response.data?.data?.phoneLoginOtp.verified))
                
                // Set user authentication status to authorized
                dispatch(setUserAuthStatus({
                    isAuthorized: true,
                    isRegistered: true,
                    role: "student"
                }))

                dispatch(closePopup())
            }
        } catch (error) { }
        setLoading(false);
    };


    return (
        <div style={{ height: "100%", margin: "1rem 0" }}>
            <Grid container spacing={2} sx={{ height: "100%" }}>

                <Grid item xs={12} sx={{ display: "flex", justifyContent: "center", alignItems: "center", flexDirection: "column" }}>
                    {active === "phone" ? (
                        <Box sx={{ mt: 2, width: "90%" }}>
                            <Typography sx={{ fontSize: { xs: "18px" }, fontWeight: 700 }} gutterBottom>
                                Enter your contact number
                            </Typography>
                            <Typography sx={{ color: "#807E7E", fontSize: "16px" }}>
                                We will send you an OTP on this contact number
                            </Typography>
                            <Formik initialValues={phone} validationSchema={validationSchema} onSubmit={onSubmitForm} enableReinitialize={true}>
                                {({ errors, touched }) => (
                                    <Form>
                                        <Grid container spacing={1.25}>
                                            <Grid item xs={12}>
                                                <ReactPhoneInput value={`${phone.countryCode} ${phone.phoneNumber}`} onChange={handlePhoneChange} country="in" inputProps={{
                                                    name: "phone",
                                                    required: true,
                                                }}
                                                    inputStyle={{
                                                        width: '100%',
                                                        height: '40px',
                                                        border: touched.phoneNumber && errors.phoneNumber
                                                            ? '1px solid red'
                                                            : '1px solid #ced4da',
                                                        backgroundColor: "#fff",
                                                    }} />
                                                <Typography variant="caption" color="error">{touched.countryCode && errors.countryCode}</Typography>
                                                <Typography variant="caption" color="error">{touched.phoneNumber && errors.phoneNumber}</Typography>
                                            </Grid>
                                            <Grid item xs={12} sx={{ display: "flex", justifyContent: "center", mt: 2, gap: "1rem" }}>
                                                <CustomButton width="100px" handleSubmit={() => onSubmitForm(phone)}>{loading ? "Loading..." : "Continue"}</CustomButton>
                                            </Grid>
                                        </Grid>
                                    </Form>
                                )}
                            </Formik>
                        </Box>
                    ) : (
                        <Box sx={{ height: "400px" }}>
                            <KeyboardBackspaceIcon sx={{ color: "grey", cursor: "pointer", mb: 1.5 }} onClick={() => {
                                setTimer(60)
                                setActive("phone")}} />
                            <Typography sx={{ fontSize: { xs: "20px" }, fontWeight: 600 }}>OTP verification</Typography>
                            <Typography sx={{ fontSize: "16px", fontWeight: 500 }}>{`Please enter the OTP sent to ${phone.phoneNumber}`}</Typography>
                            <Formik initialValues={{ otp: "", type: "phone" }} validationSchema={otpSchema} onSubmit={verifyCodeSubmit}>
                                {({ values, handleChange }) => (
                                    <Form style={{ marginTop: "1rem", display: "flex", flexDirection: "column", justifyContent: "center" }}>
                                        <OTPInput
                                            length={6}
                                            style={{
                                                display: "flex",
                                                justifyContent: "space-evenly",
                                                marginBottom: "20px",
                                            }}
                                            name="otp"
                                            isNumberInput
                                            autoFocus
                                            inputClassName="otpinput"
                                            value={values.otp}
                                            onChangeOTP={(otp: any) => (values.otp = otp)}
                                        />
                                        <Typography variant="caption" color="error"><ErrorMessage name="otp" /></Typography>
                                        <Box sx={{ textAlign: "center", my: 2 }}>
                                            {canRetry ? <span onClick={handleRetry} style={{ color: "#03a9f4", cursor: "pointer" }}>Retry</span> : `Retry in ${formatTime(timer)} minutes.`}
                                        </Box>
                                        <Box sx={{ my: 1, display: "flex", justifyContent: "center" }}>
                                            <CustomButton handleSubmit={() => console.log("")} width="100px">{loading ? "Loading..." : "Verify"}</CustomButton>
                                        </Box>
                                    </Form>
                                )}
                            </Formik>
                        </Box>
                    )}
                </Grid>
            </Grid>
        </div>
    );
};

export default PhoneNumber;
