import React from "react";
import { useNavigate } from "react-router-dom";
import { Box, Button, Typography, Grid, CardContent } from "@mui/material";
import { testReadyStyles } from "src/components/styles/customStyles";
import Images from "src/assets";

// Define TypeScript interface for options
interface EducationLoanOption {
  id: number;
  text: string;
  icon: string;
  color: string;
  bgcolor: string;
}

// Loan options
const loanOptions: EducationLoanOption[] = [
  { id: 1, text: "Yes", icon:Images.CheckboxRightTeal, color: "#70A6B2", bgcolor:"#70A6B2"},
  { id: 2, text: "No", icon:Images.CheckboxWrongRed, color: "#FF9784", bgcolor:"#FF9784"},
];

const EducationLoan: React.FC = () => {
  const navigate = useNavigate();



  const updateLocalStorage = (selectedOption: EducationLoanOption) => {
    let currentValue = localStorage.getItem("user-profile");
    let currentValueObj = currentValue ? JSON.parse(currentValue) : {};

    localStorage.setItem(
      "user-profile",
      JSON.stringify({
        ...currentValueObj,
        educationLoan: selectedOption.id === 1, // ✅ true if "Yes", false if "No"
       
      })
    );
  };
  // Handle selection
  const handleSelect = (option:EducationLoanOption): void => {
    updateLocalStorage(option)
    navigate("/financialassistance");
   
  };

  return (
    <Box
      sx={{
        ...testReadyStyles.container1,
        marginTop:{xs:'100px',lg:'120px'},
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        height: "100vh",
        textAlign: "center",
        px: { xs: 3, lg: 5 },
      }}
    >
      {/* Title */}
      <Typography
        variant="h4"
        fontWeight="bold"
        mb={5}
        sx={{
          fontSize: { xs: "1.5rem", lg: "2rem" },
          maxWidth: "90%",
          color:"#495052"
        }}
      >
        Do you need an <span style={{ color: "#F48438" }}>Education Loan?</span>
      </Typography>

      {/* Options Grid */}
      <Grid container spacing={3} justifyContent="center" sx={{ maxWidth: { xs: "350px", lg: "700px" }, mx: "auto" }}>
        {loanOptions.map((option) => (
          <Grid item xs={12} sm={6} key={option.id}>
            <Typography
              role="button"
              aria-label={option.text}
              sx={{
                position: "relative",
                ...testReadyStyles.card2,
                width: { xs: "100%", sm: "250px" },
                height: { xs: "50px", lg: "80px" },
                borderLeftColor: option.bgcolor,
                boxShadow: `0px 4px 12px rgba(0, 0, 0, 0.2)`,
                cursor: "pointer",
                transition: "0.3s ease-in-out",
                "&:hover": { boxShadow: `0px 8px 15px ${option.color}` },
              }}
              onClick={()=>handleSelect(option)}
            >
              <CardContent sx={{ display: "flex", flexDirection: {xs:'row',md:'column',lg:'column'}, alignItems: "center", gap: 1 }}>
                {/* Icon */}
                <Box>
                <img src={option.icon} alt="icon" style={{ width: 36, height: 36 }} />
                </Box>
                {/* Text */}
                <Typography variant="body1" sx={{ fontSize: "16px", fontWeight: "bold" }}>
                  {option.text}
                </Typography>
              </CardContent>
            </Typography>
          </Grid>
        ))}
      </Grid>

      {/* Navigation Buttons */}
      <Box sx={{ mt: {xs:16,md:18,lg:22}, display: "flex", justifyContent: "center", gap: 2 }}>
        <Button variant="text" sx={{ color: "#888" }} onClick={() => navigate(-1)}>
          ← Back
        </Button>
      </Box>
    </Box>
  );
};

export default EducationLoan;
