import React, { useState, useEffect } from "react";
import {
  Box,
  Button,
  Divider,
  FormControl,
  InputLabel,
  MenuItem,
  Select,
  Stack,
  Typography,
} from "@mui/material";
import { useAppDispatch, useAppSelector } from "../../assets/hooks";
import { updateCart } from "../../services";
import { setPopup } from "../../store/Slices/popupSlice";
import { setCart } from "../../store/Slices/cartSlice";
import Images from "../../assets";
import { secondaryButton } from "src/components/styles/customStyles";

const ApplyNow = ({ data, setTabComponent, tabComponent }: any) => {

  const dispatch = useAppDispatch();
  const applyData = data;
  const startDate = applyData?.startDate;
  const [loading, setLoading] = useState(false);
  const orders = useAppSelector((state: any) => state.orders);
  const [selectedIntakeValues, setSelectedIntakeValues] = useState<string | null>(null);
  const [currentYearIndex, setCurrentYearIndex] = useState<number | null>(null); // Set to null initially
  const [intakeMonth, setIntakeMonth] = useState<number | undefined>();
  const [isIntakeSelected, setIsIntakeSelected] = useState<boolean>(false);
  const [courseStartingYear, setCourseStartingYear] = useState<number>();
  const [courseStartingMonths, setCourseStartingMonths] = useState<any[]>([]);
const [error,setError] = useState(false)
  useEffect(() => {
    const months = Array.from(new Set(startDate.map((item: any) => item.courseStartingMonth)));
    setCourseStartingMonths(months);

    const currentYear = new Date().getFullYear();
    const currentMonth = new Date().getMonth();
    let startingYear: number | undefined;

    startDate?.forEach((item: any) => {
      const deadlineMonth = item?.deadlines?.find((deadline: any) => deadline?.deadlineLabel === "International")?.deadlineMonth
        || item?.deadlines?.[0]?.deadlineMonth;
      const courseStartingMonth = item.courseStartingMonth;
      const deadlineMonthYear = deadlineMonth < currentMonth ? currentYear + 1 : currentYear;
      startingYear = courseStartingMonth < deadlineMonth || deadlineMonthYear > currentYear
        ? currentYear + 1
        : currentYear;
    });

    setCourseStartingYear(startingYear);
  }, [startDate]);

  useEffect(() => {
    if (intakeMonth !== undefined && currentYearIndex !== null) {
      const paddedMonth = intakeMonth.toString().padStart(2, "0"); 
      const selectedDate = `${years[currentYearIndex]}-${paddedMonth}-01`; 
      setSelectedIntakeValues(selectedDate); 
      setIsIntakeSelected(false);
    }
    // eslint-disable-next-line
  }, [intakeMonth, currentYearIndex]);

  const endYear = courseStartingYear! + 10;
  const years: number[] = [];
  for (let year = courseStartingYear!; year <= endYear; year++) {
    years.push(year);
  }

  const monthNames: string[] = [
    "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sept", "Oct", "Nov", "Dec",
  ];
  const isSameMonthAndYear = (date1: string, date2: string) => {
    const d1 = new Date(date1);
    const d2 = new Date(date2);
    return (
      d1.getUTCFullYear() === d2.getUTCFullYear() &&
      d1.getUTCMonth() === d2.getUTCMonth()
    );
  };

  const eventHandler = async (event: any) => {
    switch (event.name) {
      case "applynow":
        setLoading(true);
        try {
          if (!selectedIntakeValues) {
            setIsIntakeSelected(true);
            return;
          }

          const alreadyApplied = orders?.data?.some((order: any) =>
            order.products?.some((product: any) =>
              product?.course?._id === applyData?._id &&
              isSameMonthAndYear(product?.intake, selectedIntakeValues)
            )
          );

          if (alreadyApplied) {
            setError(true)
            setTimeout(() => {
            setError(false)
            }, 2000); 
            // dispatch(
            //   setPopup({
            //     show: true,
            //     data: {
            //       container: {
            //         name: "error",
            //         data: "This course has already been selected for this intake.",
            //         link: null,
            //         dimensions: { width: "35%", height: "40%", show: "none" },
            //       },
            //       type: "custom",
            //     },
            //   })
            // );
            return;
          }

          const values = {
            action: "add",
            category: applyData?.featured ? "premium application" : "elite application",
            courseId: applyData?._id,
            intake: selectedIntakeValues,
          };

          const response = await updateCart(values);
          if (response.data.success) {
            dispatch(setCart(response.data.data));
            if (tabComponent === "apply") {
              setTabComponent("tabs");
              dispatch(
                setPopup({
                  show: true,
                  data: {
                    container: {
                      name: "success",
                      data: response.data.message,
                      link: "profile/cart",
                      dimensions: { width: "35%", height: "40%", show: "none" },
                    },
                    type: "custom",
                  },
                })
              );
            } else {
              dispatch(
                setPopup({
                  show: true,
                  data: {
                    container: {
                      name: "success",
                      data: response.data.message,
                      link: "profile/cart",
                      dimensions: { width: "35%", height: "40%", show: "none" },
                    },
                    type: "custom",
                  },
                })
              );
            }
          }
        } catch (error) {
          handlePopupError(error);
        } finally {
          setLoading(false);
        }
        break;

      case "intakeYear":
        setCurrentYearIndex(event.data);
        break;

      case "intakeMonth":
        setIntakeMonth(event.data);
        break;
    }
  };


  const filteredMonths = (year: number) => {
    const currentYear = new Date().getFullYear();
    const currentMonth = new Date().getMonth();
    if (year === currentYear) {
      return courseStartingMonths.filter((month) => month >= currentMonth);
    }
    return courseStartingMonths;
  };

  const handlePopupError = (error: any) => {
    dispatch(
      setPopup({
        show: true,
        data: {
          container: {
            name: "error",
            data: error,
            dimensions: { width: "50%", height: "40%", show: "none" },
          },
          type: "custom",
        },
      })
    );
  };

  return (
    <Box>
      <Box sx={{ p: 3.5, background: "#D1D3F9"}}>
        <Typography sx={{ position: "relative", width: "1rem", height: "1rem", borderRadius: "50%", background: "#9CFFF9" }}>
          <Typography sx={{ position: "absolute", top: "-6px", left: "9px", width: "200px" }} fontWeight="600" fontSize="1rem">
            Please select start date 
          </Typography>
        </Typography>
      </Box>
      <Box sx={{ display: "flex", gap: "0.5rem", alignItems: "center", m: 1, justifyContent: "space-between",flexDirection:'column' }}>
        <Box sx={{ display: "flex", gap: "0.5rem", alignItems: "center", boxShadow: "11px 12px 50px rgb(14 12 4 / 12%)", padding: "4px 8px", width: "fit-content", margin: "10px", borderRadius: "10px" }}>
          <img src={Images.calender} alt="/calendar" style={{ width: "1.5rem" }} />
          <FormControl variant="standard" sx={{ m: 1, minWidth: 120 }}>
            <InputLabel sx={{ top: "-5px", fontSize: "14px", color: "#000" }}>Select Year</InputLabel>
            <Select
              value={currentYearIndex ?? ""}
              onChange={(e: any) => eventHandler({ name: "intakeYear", data: e.target.value })}
              disableUnderline
              sx={{
                "& .MuiSelect-select": {
                  border: "none",
                },
                "& .MuiSvgIcon-root": {
                  top: "calc(36% - .5em)"
                }
              }}
              MenuProps={{
                PaperProps: {
                  sx: {
                    maxHeight: 200,
                    maxWidth: 300,
                    "&.MuiPaper-root": {
                      boxShadow: 3,
                    },
                  },
                },
                autoFocus: false,
              }}
            >
              {years.map((year, i) => (
                <MenuItem key={i} value={i}>{year}</MenuItem>
              ))}
            </Select>
          </FormControl>
        </Box>
        {/* <Divider orientation="vertical" variant="middle" flexItem sx={{ marginX: 1, alignSelf: "center", height: "50px" }} /> */}
        <Box sx={{ display: "flex", gap: "0.5rem", alignItems: "center", boxShadow: "11px 12px 50px rgb(14 12 4 / 12%)", padding: "4px 8px", width: "fit-content", margin: "10px", borderRadius: "10px" }}>
          <img src={Images.calender} alt="/calendar" style={{ width: "1.5rem" }} />
          <FormControl variant="standard" sx={{ m: 1, minWidth: 120 }}>
            <InputLabel sx={{ top: "-5px", fontSize: "14px", color: "#000" }}>Select Month</InputLabel>
            <Select
              value={intakeMonth}
              onChange={(e: any) => eventHandler({ name: "intakeMonth", data: e.target.value + 1 })}
              disableUnderline
              sx={{
                "& .MuiSelect-select": {
                  border: "none",
                },
                "& .MuiSvgIcon-root": {
                  top: "calc(36% - .5em)"
                }
              }}
              MenuProps={{
                PaperProps: {
                  sx: {
                    maxHeight: 200,
                    maxWidth: 300,
                    "&.MuiPaper-root": {
                      boxShadow: 3,
                    },
                  },
                },
                autoFocus: false,
              }}
            >
              {/* {filteredMonths(years[currentYearIndex!])?.map((month, i) => (
                <MenuItem key={i} value={month}>{monthNames[month]}</MenuItem>
              ))} */}
              {filteredMonths(years[currentYearIndex!])?.map((item, i) => <MenuItem value={item}>{monthNames[item]}</MenuItem>
              )}
            </Select>
          </FormControl>
        </Box>
      </Box>
      {isIntakeSelected && <div className="error-message" style={{ color: "red", marginLeft: "1rem" }}>Start month and year is required</div>}
      {error && <div className="error-message" style={{ color: "red", marginLeft: "1rem" }}>This course has already been selected for this intake</div>}
      
      <Stack direction="row" justifyContent="center" sx={{ my: 3, alignItems: "center" }}>
        <Button
          onClick={() => eventHandler({ name: "applynow", data: "" })}
          disabled={loading}
          sx={[secondaryButton]}
        >
          {loading ? <img src={Images.standardLoader} alt="loading" style={{ width: "20px", height: "20px", padding: "5px" }} /> : "Continue"}
        </Button>
      </Stack>
    </Box>
  );
};

export default ApplyNow;
