/**
 * Format number with appropriate separators based on currency
 * @param amount - The amount to format
 * @param currencyCode - The currency code (e.g., 'INR', 'USD', 'EUR')
 * @returns Formatted string with appropriate separators
 */
export const formatCurrencyAmount = (amount: number | undefined, currencyCode: string): string => {
  if (!amount || isNaN(amount)) {
    return '0';
  }

  const formattingSystem = NUMBER_FORMATTING_SYSTEMS[currencyCode] || 'western';

  switch (formattingSystem) {
    case 'indian':
      return formatIndianNumber(amount);
    case 'chinese':
      return formatChineseNumber(amount);
    case 'japanese':
      return formatJapaneseNumber(amount);
    case 'thai':
      return formatThaiNumber(amount);
    case 'arabic':
      return formatArabicNumber(amount);
    case 'western':
    default:
      return formatWesternNumber(amount);
  }
};

/**
 * Format number using Indian number system (lakhs, crores)
 * @param amount - The amount to format
 * @returns Formatted string with Indian separators
 */
const formatIndianNumber = (amount: number): string => {
  const numStr = Math.abs(amount || 0).toString();
  
  // Handle numbers less than 1000
  if (numStr.length <= 3) {
    return numStr;
  }

  // Handle numbers with decimal places
  const parts = numStr.split('.');
  const wholePart = parts[0];
  const decimalPart = parts[1] || '';

  // Add commas for Indian number system
  let formatted = '';
  const len = wholePart.length;
  
  // Add comma after first 3 digits from right, then every 2 digits
  for (let i = 0; i < len; i++) {
    if (i > 0 && (len - i) % 2 === 1 && i !== len - 1) {
      formatted += ',';
    }
    formatted += wholePart[i];
  }

  // Add decimal part if exists
  if (decimalPart) {
    formatted += '.' + decimalPart;
  }

  return formatted;
};

/**
 * Format number using Chinese number system
 * @param amount - The amount to format
 * @returns Formatted string with Chinese separators
 */
const formatChineseNumber = (amount: number): string => {
  const numStr = Math.abs(amount || 0).toString();
  
  // Handle numbers less than 10000
  if (numStr.length <= 4) {
    return numStr;
  }

  // Handle numbers with decimal places
  const parts = numStr.split('.');
  const wholePart = parts[0];
  const decimalPart = parts[1] || '';

  // Add commas for Chinese number system (every 4 digits)
  let formatted = '';
  const len = wholePart.length;
  
  for (let i = 0; i < len; i++) {
    if (i > 0 && (len - i) % 4 === 0) {
      formatted += ',';
    }
    formatted += wholePart[i];
  }

  // Add decimal part if exists
  if (decimalPart) {
    formatted += '.' + decimalPart;
  }

  return formatted;
};

