/**
 * Format number using Western number system (standard international)
 * @param amount - The amount to format
 * @returns Formatted string with Western separators
 */
const formatWesternNumber = (amount: number): string => {
  return (amount || 0).toLocaleString('en-US');
};

/**
 * Format currency with symbol and amount
 * @param amount - The amount to format
 * @param currency - Currency object with code and symbol
 * @returns Formatted currency string
 */
export const formatCurrency = (amount: number | undefined, currency: CurrencyInfo): string => {
  if (!amount || isNaN(amount)) {
    return `${currency.symbol}0`;
  }

  const formattedAmount = formatCurrencyAmount(amount, currency.code);
  return `${currency.symbol}${formattedAmount}`;
};

/**
 * Format currency range (min - max)
 * @param minAmount - Minimum amount
 * @param maxAmount - Maximum amount
 * @param currency - Currency object with code and symbol
 * @returns Formatted currency range string
 */
export const formatCurrencyRange = (
  minAmount: number | undefined, 
  maxAmount: number | undefined, 
  currency: CurrencyInfo
): string => {
  const formattedMin = formatCurrencyAmount(minAmount || 0, currency.code);
  const formattedMax = formatCurrencyAmount(maxAmount || 0, currency.code);
  return `${currency.symbol}${formattedMin} - ${currency.symbol}${formattedMax}`;
};

/**
 * Parse currency code from currency string (e.g., "Indian Rupee-INR" -> "INR")
 * @param currencyString - Currency string from the currency symbols array
 * @returns Currency code
 */
export const parseCurrencyCode = (currencyString: string): string => {
  const parts = currencyString.split('-');
  return parts[parts.length - 1] || 'INR';
};

