import React, { useState, useEffect, useRef } from "react";
import { Grid, Card, TextField, Box, FormControl, InputLabel, Select, MenuItem, Button, Typography } from "@mui/material";
import Calendar from "react-calendar";
import "react-calendar/dist/Calendar.css";
import { toast } from "react-toastify";
import CircularProgress from "@mui/material/CircularProgress";
import { slotBooking, getCounsellorSlots } from "../../../../services/index";
import { useAppDispatch } from "../../../../assets/hooks";
import { addmeetings } from "../../../../store/Slices/meetings";
import { Event } from "../../../../types/types";
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import DeleteOutlineIcon from '@mui/icons-material/DeleteOutline';
import { secondaryButton } from "src/components/styles/customStyles";
import Images from "src/assets";
import KeyboardDoubleArrowDownOutlinedIcon from '@mui/icons-material/KeyboardDoubleArrowDownOutlined';
import KeyboardDoubleArrowUpOutlinedIcon from '@mui/icons-material/KeyboardDoubleArrowUpOutlined';
import { setPopup } from "src/store/Slices/popupSlice";

const Slot = ({ data }: any) => {
  const isLoggedIn = localStorage.getItem("_auth");
  const dispatch = useAppDispatch();
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toDateString());
  const [availableSlots, setAvailableSlots] = useState<any[]>([]);
  const [selectedSlot, setSelectedSlot] = useState<any>(null);
  const [error, setError] = useState<boolean>(false);
  const [ApiResponse, SetApiResponse] = useState<any>();
  // const [next, setNext] = useState<boolean>(false);
  const [notes, setNotes] = useState<string>("");
  const [email, setEmail] = useState<string[]>([""]);
  const [loader, setLoader] = useState<boolean>(false);
  const [loading, setLoading] = useState<boolean>(false);
  const [showScrollDown, setShowScrollDown] = useState(false);
  const [showScrollUp, setShowScrollUp] = useState(false);
  const scrollRef = useRef<any>(null);

  const handleBooking = () => {
    if (!selectedSlot) {
      setError(true);
      toast.error("Please select a time slot");
      return;
    }
    if (notes.trim() === "") {
      setError(true);
      toast.error("Please enter the purpose of the meeting");
      return;
    }
    setError(false);
    eventHandler({ name: "counsellorSlotBooking", data: "" });
  };

  useEffect(() => {
    if (isLoggedIn) {
      counsellorSlots(new Date(selectedDate));
    }
    // eslint-disable-next-line
  }, []);

  const isFirstInputFilled = email[0].trim() !== "";

  const currentTime = new Date();
  currentTime.setMinutes(currentTime.getMinutes() + 30);
  const filteredSlots = availableSlots?.filter((slot: any) => new Date(slot.startTime) >= currentTime);

  const counsellorSlots = async (date: Date) => {
    setLoader(true);
    if (ApiResponse && ApiResponse.length > 0) {
      const matchingDate = ApiResponse.find(
        (slot: any) =>
          new Date(slot.date).toDateString() === date.toDateString()
      );

      if (matchingDate && matchingDate.availableSlots) {
        setAvailableSlots(matchingDate.availableSlots);
      } else {
        setAvailableSlots([]);
      }
      setLoader(false);
      return;
    }
    try {
      const response = await getCounsellorSlots(data);
      if (response && response.data !== undefined) {
        setLoader(false);
        SetApiResponse(response?.data?.data);
        const matchingDate = response?.data?.data?.find(
          (slot: any) =>
            new Date(slot.date).toDateString() === date.toDateString()
        );
        if (matchingDate && matchingDate?.availableSlots) {
          setAvailableSlots(matchingDate?.availableSlots);
        } else {
          setAvailableSlots([]);
        }
      }
    } catch (error) {
      setLoader(false);
      toast.error("Failed to fetch available slots. Please try again.");
    }
  };

  const isWeekend = (date: Date): boolean => {
    const day = date.getDay();
    return day === 0;
  };

  const eventHandler = async (event: Event) => {
    switch (event.name) {
      case "DateChange":
        const date = event.data.target.value;
        if (date && !isWeekend(new Date(date))) {
          setSelectedDate(date);
          counsellorSlots(new Date(date));
        }
        break;
      case "AddEmail":
        const newEmails = [...email, ""];
        setEmail(newEmails);
        break;
      case "RemoveEmail":
        const newEmail = [...email];
        newEmail.splice(event.data, 1);
        setEmail(newEmail);
        break;
      case "EmailChange":
        const newmails = [...email];
        newmails[event.data.index] = event.data.e.target.value;
        setEmail(newmails);
        break;
      case "counsellorSlotBooking":
        if (email[0].trim() === "") {
          const values = {
            startTime: `${selectedSlot.startTime}`,
            endTime: `${selectedSlot.endTime}`,
            timeZone: "Asia/Kolkata",
            notes: notes,
          };
          setLoading(true);
          try {
            const response = await slotBooking(data, values);
            if (response) {
              dispatch(addmeetings(response.data));
              toast.success("Slot booked successfully!");
              setTimeout(() => { }, 2000);
              setLoading(false);
            } else {
              setLoading(false);
              toast.error("Failed to book slot. Please try again.");
            }
          } catch (error) {
            setLoading(false);
            toast.error("An error occurred while booking the slot.");
          }
        } else {
          setLoading(true);
          const values = {
            startTime: `${selectedSlot.startTime}`,
            endTime: `${selectedSlot.endTime}`,
            attendees: email,
            timeZone: "Asia/Kolkata",
            notes: notes,
          };

          try {
            const response = await slotBooking(data, values);
            if (response) {
              dispatch(addmeetings(response.data));
              toast.success("Slot booked successfully!");
              setTimeout(() => { }, 2000);
              setLoading(false);
            } else {
              toast.error("Failed to book slot. Please try again.");
              setLoading(false);
            }
          } catch (error) {
            setLoading(false);
            toast.error("An error occurred while booking the slot.");
          }
        }
        break;
      default:
        break;
    }
  }

  const handleScroll = () => {
    const scrollContainer = scrollRef.current;
    if (scrollContainer) {
      const isAtBottom = scrollContainer.scrollHeight - scrollContainer.scrollTop <= scrollContainer.clientHeight + 5;
      setShowScrollDown(scrollContainer.scrollHeight > scrollContainer.clientHeight);
      setShowScrollUp(!isAtBottom);
    }
  };

  useEffect(() => {
    const scrollContainer = scrollRef.current;
    if (scrollContainer) {
      scrollContainer.addEventListener("scroll", handleScroll);
      handleScroll(); 

      return () => {
        scrollContainer.removeEventListener("scroll", handleScroll);
      };
    }
  }, [email]);

  const scrollToBottom = () => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({
        top: scrollRef.current.scrollHeight,
        behavior: "smooth",
      });
    }
  };

  const scrollToTop = () => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({
        top: 0,
        behavior: "smooth",
      });
    }
  };

  return (
    <React.Fragment>
      {loader ? (
        <Box
          sx={{
            display: "flex",
            flexDirection: "column",
            flex: 1,
            justifyContent: "center",
            alignItems: "center",
            height: "300px",
          }}
        >
          <CircularProgress />
        </Box>
      ) : (
        <Box sx={{
          display: "flex",
          flexDirection: "column",
          flex: 1,
          padding: { xs: "1rem", md: "2rem" },
          gap: 2,
          minHeight: "100vh",
          position: "relative"
        }}>
          <Box ref={scrollRef} 
            sx={{
              display: "flex",
              flexDirection: "column",
              flex: 1,
              gap: 2,
              overflowY: "auto",
              pb: 8,
              "&::-webkit-scrollbar": {
                width: "0px",
                position: "relative",
              },
              "&::-webkit-scrollbar-thumb": {
                backgroundColor: "#fff",
                borderRadius: "8px",
              },
              "&::-webkit-scrollbar-track": {
                backgroundColor: "#fff",
              },
              pr: { xs: 0, md: 2 }
            }}
          >
            {showScrollUp && (scrollRef.current && scrollRef?.current?.scrollHeight) > 510 && (
              <KeyboardDoubleArrowDownOutlinedIcon 
                onClick={scrollToBottom} 
                sx={{
                  position: "fixed",
                  bottom: 50,
                  right: 50,
                  zIndex: 1000,
                  display: { lg: "block", xs: "none" },
                  cursor: "pointer",
                  color: "#3B3F76",
                  "&:hover": {
                    color: "#303363"
                  }
                }} 
              />
            )}

            {showScrollDown && !showScrollUp && (
              <KeyboardDoubleArrowUpOutlinedIcon 
                onClick={scrollToTop} 
                sx={{
                  position: "fixed",
                  bottom: 50,
                  right: 50,
                  zIndex: 1000,
                  display: { lg: "block", xs: "none" },
                  cursor: "pointer",
                  color: "#3B3F76",
                  "&:hover": {
                    color: "#303363"
                  }
                }} 
              />
            )}

            <Box>
              <Typography variant="h6" sx={{ 
                color: "#3B3F76", 
                fontWeight: 600,
                mb: 1
              }}>
                Purpose of the meeting
              </Typography>
              <TextField
                size="small"
                variant="outlined"
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
                fullWidth
                required
                placeholder="Ex: Academic advice, shortlisting"
                InputLabelProps={{ shrink: true }}
                autoFocus={true}
                error={error && !notes}
                helperText={error && !notes ? "Please enter the purpose of the meeting" : ""}
                sx={{
                  "& .MuiOutlinedInput-root": {
                    height: "40px",
                    borderRadius: "8px",
                    "&:hover .MuiOutlinedInput-notchedOutline": {
                      borderColor: "#3B3F76",
                    },
                    "&.Mui-focused .MuiOutlinedInput-notchedOutline": {
                      borderColor: "#3B3F76",
                      borderWidth: "2px"
                    }
                  },
                  "& .MuiOutlinedInput-notchedOutline": {
                    borderColor: "#0000004D",
                  }
                }}
                inputProps={{
                  sx: {
                    "&::placeholder": {
                      fontSize: "14px",
                      color: "#0000004D"
                    },
                  }
                }}
              />
            </Box>

            <Box>
              <Typography variant="h6" sx={{ 
                color: "#3B3F76", 
                fontWeight: 600,
                mb: 1
              }}>
                Additional participants
              </Typography>
              {email?.map((email, index) => (
                <Box
                  key={index}
                  sx={{
                    display: "flex",
                    alignItems: "center",
                    gap: 1,
                    mb: 1
                  }}
                >
                  <TextField
                    size="small"
                    variant="outlined"
                    value={email}
                    type="email"
                    InputLabelProps={{ shrink: true }}
                    onChange={(e) => eventHandler({ name: "EmailChange", data: { index, e } })}
                    fullWidth
                    placeholder="Add email addresses of other participants"
                    sx={{
                      "& .MuiOutlinedInput-root": {
                        height: "40px",
                        borderRadius: "8px",
                        "&:hover .MuiOutlinedInput-notchedOutline": {
                          borderColor: "#3B3F76",
                        },
                        "&.Mui-focused .MuiOutlinedInput-notchedOutline": {
                          borderColor: "#3B3F76",
                          borderWidth: "2px"
                        }
                      },
                      "& .MuiOutlinedInput-notchedOutline": {
                        borderColor: "#0000004D",
                      }
                    }}
                    inputProps={{
                      sx: {
                        "&::placeholder": {
                          fontSize: "14px",
                          color: "#0000004D"
                        },
                      }
                    }}
                  />
                  <Box sx={{ display: "flex", gap: 1 }}>
                    {isFirstInputFilled && index === 0 && (
                      <AddCircleOutlineIcon 
                        onClick={() => eventHandler({ name: "AddEmail", data: "" })}
                        sx={{ 
                          color: "#3B3F76",
                          cursor: "pointer",
                          "&:hover": {
                            color: "#303363"
                          }
                        }}
                      />
                    )}
                    {index > 0 && (
                      <DeleteOutlineIcon 
                        sx={{ 
                          color: "#F87171",
                          cursor: "pointer",
                          "&:hover": {
                            color: "#EF4444"
                          }
                        }}
                        onClick={() => eventHandler({ name: "RemoveEmail", data: index })}
                      />
                    )}
                  </Box>
                </Box>
              ))}
            </Box>

            <Box>
              <Typography variant="h6" sx={{ 
                color: "#3B3F76", 
                fontWeight: 600,
                mb: 1
              }}>
                Select Date and Time
              </Typography>
              <Box sx={{ 
                display: "flex", 
                flexDirection: { xs: "column", md: "row" },
                gap: 2,
                alignItems: { xs: "stretch", md: "center" }
              }}>
                <Box sx={{ 
                  flex: { xs: 1, md: 0.4 },
                  position: "relative"
                }}>
                  <input  
                    min={new Date().toISOString().split('T')[0]}
                    max={new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]}
                    onChange={(e) => eventHandler({ name: "DateChange", data: e })} 
                    value={(() => {
                      const d = new Date(selectedDate);
                      if (!isNaN(d.getTime())) {
                        return d.toISOString().split('T')[0];
                      }
                      return '';
                    })()}
                    type="date"
                    style={{
                      width: "100%",
                      height: "40px",
                      padding: "8px 12px",
                      borderRadius: "8px",
                      border: error && !selectedSlot ? "1px solid #F87171" : "1px solid #0000004D",
                      outline: "none",
                      fontSize: "14px",
                      appearance: "none",
                      WebkitAppearance: "none",
                      MozAppearance: "none",
                      color: "#3B3F76",
                      backgroundColor: "#fff",
                      cursor: "pointer"
                    }}
                  />
                </Box>

                <FormControl 
                  sx={{ 
                    flex: { xs: 1, md: 0.6 },
                    "& .MuiOutlinedInput-root": {
                      height: "40px",
                      borderRadius: "8px",
                      "&:hover .MuiOutlinedInput-notchedOutline": {
                        borderColor: "#3B3F76",
                      },
                      "&.Mui-focused .MuiOutlinedInput-notchedOutline": {
                        borderColor: "#3B3F76",
                        borderWidth: "2px"
                      }
                    }
                  }}
                >
                  <Select
                    value={selectedSlot?.startTime}
                    onChange={(e) => {
                      const selectedTime = e.target.value;
                      const slot = availableSlots?.find(
                        (s) =>
                          new Date(s.startTime).toLocaleTimeString([], {
                            hour: "2-digit",
                            minute: "2-digit",
                          }) === selectedTime
                      );
                      setSelectedSlot(slot);
                    }}
                    displayEmpty
                    error={error && !selectedSlot}
                    sx={{
                      "& .MuiSelect-select": {
                        padding: "8px 12px",
                        fontSize: "14px"
                      }
                    }}
                    MenuProps={{
                      PaperProps: {
                        sx: {
                          maxHeight: 300,
                          borderRadius: "8px",
                          boxShadow: "0px 4px 20px rgba(0, 0, 0, 0.1)",
                          "& .MuiMenuItem-root": {
                            padding: "8px 12px",
                            fontSize: "14px"
                          }
                        }
                      }
                    }}
                  >
                    <MenuItem value="" disabled>
                      Select a time slot
                    </MenuItem>
                    {filteredSlots?.length > 0 ? (
                      filteredSlots.map((slot: any, index: number) => (
                        <MenuItem
                          key={index}
                          value={new Date(slot.startTime).toLocaleTimeString([], {
                            hour: "2-digit",
                            minute: "2-digit",
                          })}
                        >
                          {new Date(slot.startTime).toLocaleTimeString([], {
                            hour: "2-digit",
                            minute: "2-digit",
                          })}{" "}
                          -{" "}
                          {new Date(slot.endTime).toLocaleTimeString([], {
                            hour: "2-digit",
                            minute: "2-digit",
                          })}
                        </MenuItem>
                      ))
                    ) : (
                      <MenuItem disabled>
                        No slots available
                      </MenuItem>
                    )}
                  </Select>
                  {error && !selectedSlot && (
                    <Typography sx={{ color: "#F87171", fontSize: "12px", mt: 1 }}>
                      Please select a time slot
                    </Typography>
                  )}
                </FormControl>
              </Box>
            </Box>
          </Box>

          <Box sx={{ 
            position: {xs:'relative',lg:'fixed'},
            bottom: {xs:'20px',lg:'10px'},
            left: 0,
            right: 0,
            display: "flex", 
            justifyContent: "center",
            alignItems: "center",
            p: 2,
            backgroundColor: "transparent",
            zIndex: 1000,
            marginBottom:{xs:'250px',lg:'150px'},
            marginLeft:{xs:'60px',lg:'420px'},
            marginRight:{xs:'50px',lg:'0px'}
          }}>
            <Button 
              sx={{
                ...secondaryButton,
                minWidth: "200px",
                height: "40px",
                fontSize: "14px",
              
                fontWeight: 600,
                transition: "all 0.3s ease",
                transform: "translateY(0)",
                "&:hover": {
                  backgroundColor: "#303363",
                  color:'white',
                  transform: "translateY(-2px)",
                  boxShadow: "0px 4px 12px rgba(59, 63, 118, 0.2)"
                },
                "&:active": {
                  transform: "translateY(0)",
                  boxShadow: "none"
                },
                "&:disabled": {
                  backgroundColor: "#E5E7EB",
                  color: "#9CA3AF",
                  transform: "none",
                  boxShadow: "none"
                }
              }} 
              disabled={!selectedSlot || notes === ""}
              onClick={handleBooking}
            >
              {loading ? (
                <img 
                  src={Images.standardLoader} 
                  alt="loader" 
                  style={{ width: "20px", height: "20px" }} 
                />
              ) : (
                "Book a slot"
              )}
            </Button>
          </Box>
        </Box>
      )}
    </React.Fragment>
  );
};

export default Slot;
