import axios from "axios";
import { getSessionConfig } from "../config/sessionConfig";

const config = getSessionConfig();

const api = axios.create({
  baseURL: process.env.REACT_APP_API_URL || "https://campusroot.com/",
  timeout: config.API_TIMEOUT, // Configurable timeout
});

// Request interceptor to add auth token
api.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem("_auth");
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

// Response interceptor to handle token refresh
api.interceptors.response.use(
  (response) => {
    // If the response contains a new access token, update it
    if (response.data?.AccessToken) {
      localStorage.setItem("_auth", response.data.AccessToken);
    }
    return response;
  },
  async (error) => {
    const originalRequest = error.config;

    // If the error is 401 and we haven't already tried to refresh
    if (error.response?.status === 401 && !originalRequest._retry) {
      originalRequest._retry = true;

      try {
        // Try to refresh the token by calling a refresh endpoint
        // You may need to implement this endpoint on your backend
        const refreshResponse = await axios.post(
          `${process.env.REACT_APP_API_URL || "https://campusroot.com/"}/api/v1/auth/refresh`,
          {},
          {
            headers: {
              "Content-Type": "application/json",
            },
          }
        );

        if (refreshResponse.data?.AccessToken) {
          localStorage.setItem("_auth", refreshResponse.data.AccessToken);
          originalRequest.headers.Authorization = `Bearer ${refreshResponse.data.AccessToken}`;
          return api(originalRequest);
        }
      } catch (refreshError) {
        // If refresh fails, logout the user
        localStorage.removeItem("_auth");
        window.location.href = "/";
        return Promise.reject(refreshError);
      }
    }

    return Promise.reject(error);
  }
);

export default api;