import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { Box, Button, Typography, Grid, CardContent } from "@mui/material";
import { testReadyStyles } from "src/components/styles/customStyles";
import Images from "src/assets"; 
import { STUDY_LEVELS } from "./StudyLevel";
// Define TypeScript interface for goal objects
interface Goal {
  id: number;
  text: string;
  icon: JSX.Element|string;
  color: string;
  bgcolor: string;
}

// List of goals
const goals: Goal[] = [
  { id: 1, text: "University Selection", icon:Images.universitytil, color: "#70A6B2", bgcolor: "#70A6B2" },
  { id: 2, text: "Application Assistance", icon:Images.applicationAssitance, color: "#AAAEFE", bgcolor: "#AAAEFE" },
  { id: 3, text: "Education Loan", icon:Images.educatioloanOrange, color: "#FF9784", bgcolor: "#FF9784" },
  { id: 4, text: "Scholarship Guidance", icon: Images.scholorshipOrange, color: "#AAAEFE", bgcolor: "#AAAEFE" },
  { id: 5, text: "SOP & Essay Guidance", icon:Images.soppurple, color: "#FF9784", bgcolor: "#FF9784" },
  { id: 6, text: "Visa Support", icon:Images.VisaTeal, color: "#70A6B2", bgcolor: "#70A6B2"},
  { id: 7, text: "Accommodation", icon:Images.AccomidationTeal, color: "#70A6B2", bgcolor: "#70A6B2" },
  { id: 8, text: "Pre-Departure Orientation", icon:Images.flightRed, color: "#AAAEFE", bgcolor: "#AAAEFE" },
  { id: 9, text: "Internship & Job Placement", icon:Images.SuitcaseOrange, color: "#FF9784", bgcolor: "#FF9784" }
];

const CareerGoals: React.FC = () => {
  const [selectedGoals, setSelectedGoals] = useState<Goal[]>([]);
  const navigate = useNavigate();


  const updateLocalStorage = (updatedGoals: Goal[]) => {
    let currentValue = localStorage.getItem("user-profile");
    let currentValueObj = currentValue ? JSON.parse(currentValue) : {};

    // Store selected services as an array in local storage
    localStorage.setItem(
      "user-profile",
      JSON.stringify({
        ...currentValueObj,
        services: updatedGoals.map(goal => goal.text), // Store selected goals as an array
      })
    );
  };

 
  // Handle goal selection (toggle selection)
  const handleSelect = (goal: Goal): void => {
    const updatedGoals = selectedGoals.some(item => item.id === goal.id)
      ? selectedGoals.filter(item => item.id !== goal.id)
      : [...selectedGoals, goal];

    setSelectedGoals(updatedGoals);
    updateLocalStorage(updatedGoals);
    
  }

  // Navigate to the next page with selected goals
  const handleContinue = (): void => {
    if (selectedGoals.length > 0) {
      const selectedData = selectedGoals.map(({ id, text, color }) => ({ id, text, color }));
      // Get study level from localStorage
      let currentValue = localStorage.getItem("user-profile");
      let currentValueObj = currentValue ? JSON.parse(currentValue) : {};
      let degreeName = currentValueObj?.preference?.degree;
      let studyLevel = STUDY_LEVELS.find((level: { id: number; name: string }) => level.name === degreeName);
      
      if (studyLevel && studyLevel.id !== 1) {
        navigate("/personalDetails", { state: { goals: selectedData } });
      } else {
        navigate("/congratulations", { state: { goals: selectedData } });
      }
    }
  };

  return (
    <Box
      sx={{
        ...testReadyStyles.container1,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        height: "100vh",
        textAlign: "center",
        px: { xs: 2, md: 5 },
        py:3
      }}
    >
      {/* Title */}
      <Typography
        variant="h4"
        fontWeight="bold"
        sx={{
          textAlign: "center",
          maxWidth: "90%",
          fontSize: { xs: "1.5rem", md: "2rem" },
          mb: 3,
          py:{xs:2,md:3,lg:5},
          color:"#495052"
        }}
      >
        What kind of <span style={{ color: "#F48438" }}>support</span> do you need?
      </Typography>

      {/* Goals Grid */}
      <Box
        sx={{
          maxWidth: "880px",
          mx: "auto",
          px: { xs: 2, md: 0 },
          maxHeight: { xs: "60vh", md: "80vh" },
          overflowY: "auto",
        }}
      >
        <Grid container spacing={2} justifyContent="center">
          {goals.map((goal) => {
            const isSelected = selectedGoals.some((item) => item.id === goal.id);
            return (
              <Grid py={2} item xs={12} sm={6} md={4} key={goal.id}>
                <Box
                  component="div"
                  role="button"
                  aria-label={goal.text}
                  onClick={() => handleSelect(goal)}
                  sx={{
                    ...testReadyStyles.card2,
                    width: { xs: "90%", sm: "250px", lg: "200px" },
                    height: { xs: "50px", md: "90px" },
                    marginTop:1,
                    marginLeft:1,
                    borderLeftColor: goal.bgcolor,
                    borderRadius: "15px",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    boxShadow: "0px 4px 12px rgba(0, 0, 0, 0.2)",
                    background: isSelected
                      ? `linear-gradient(145deg, ${goal.bgcolor}, #ffffff)`
                      : "transparent",
                    transition: "0.4s ease-in-out",
                    cursor: "pointer",
                    "&:hover": {
                      boxShadow: `0px 8px 18px ${goal.bgcolor}`,
                      transform: "scale(1.05)",
                    },
                  }}
                >
                  <CardContent
                    sx={{
                      display: "flex",
                      flexDirection:{xs:'row',md:'column',lg:'column'},
                      alignItems: "center",
                      gap: 1,
                      textAlign: "center",
                    }}
                  >
                    {/* Icon */}
                   {typeof goal.icon === "string" ? (
                     <Box
                       component="img"
                       src={goal.icon}
                       sx={{ width: 30, height: 30, mr: 2 }}
                     />
                   ) : (
                     <Box sx={{ color: goal.color, fontSize: "30px", mr: 2 }}>
                       {goal.icon}
                     </Box>
                   )}

                    {/* Goal Text */}
                    <Typography variant="body1" sx={{ fontSize: { xs: "14px", md: "16px" } }}>
                      {goal.text}
                    </Typography>
                  </CardContent>
                </Box>
              </Grid>
            );
          })}
        </Grid>
        <Box
        sx={{
          mt: 4,
          display: "flex",
          justifyContent: "space-between",
          flexDirection: { xs: "column", sm: "row" },
          gap: 2,
          width: "100%",
          maxWidth: "500px",
        }}
      >
       
      </Box>
      </Box >
       {/* Back Button */}
       <Box display={"flex"} marginBottom={2} >
       <Button
          variant="text"
          sx={{
            color: "#888",
            width: { xs: "100%", sm: "auto" },
            mt:{xs:5.5,md:2,lg:5.5},
            mr:{xs:1,md:2,lg:3}
            
          }}
          onClick={() => navigate(-1)}
        >
          ← Back
        </Button>

        {/* Continue Button (Visible Only If a Goal is Selected) */}
        {selectedGoals.length > 0 && (
          <Button
            variant="contained"
            sx={{
              px: 4,
              py: 2.5,
              borderRadius: "20px",
              height:{xs:'20px',lg:'35px'},
              fontSize: { xs: "14px", sm: "16px" },
              width: { xs: "50%", sm: "auto" },
              marginTop:{xs:'50px',lg:'42px'},
              background:"#F48438",
              "&:hover": {
              backgroundColor: "#d96f2e", // slightly darker shade for hover
              },
              }}
            onClick={handleContinue}
          >
            Continue
          </Button>
        )}
       </Box>
      
    </Box>
  );
};

export default CareerGoals;
