import { PayloadAction, createSlice } from "@reduxjs/toolkit";
import { Cart, StoreItem } from "../../types/types";

let initialState:StoreItem<Cart[]>={
    requestStatus:"not_initiated",
    responseStatus:"not_recieved",
    haveAnIssue:false,
    issue:"",
    data:[]
}

export const CartSlice=createSlice({
    name:'Cart',
    initialState:initialState,
    reducers:{
        initCart:(state,action:PayloadAction<StoreItem<Cart[]>>)=>({...action.payload}),
        addCart:(state,action:PayloadAction<Cart>)=>{state.data.push(action.payload)},
        setCart:(state,action:PayloadAction<Cart[]>)=>{state.data=action.payload},
        // updateCart:(state,action:PayloadAction<Cart>)=>{
        //     let index=state.data.findIndex((item)=>item._id===action.payload._id);
        //     state.data[index]=action.payload;
        // },
         removeCart:(state,action:PayloadAction<string>)=>{state.data=state.data.filter((item)=>item._id!==action.payload)},
        resetCart:(state,action:PayloadAction)=>({...initialState})

    }
})

export const {initCart,addCart,resetCart,setCart,removeCart}=CartSlice.actions;
export default CartSlice.reducer;