import { store } from "../store/store";
import { setUserAuthStatus } from "../store/Slices/userAuthSlice";
import { setPopup } from "../store/Slices/popupSlice";
import { logout } from "./library";
import { getSessionConfig } from "../config/sessionConfig";

class SessionManager {
  private refreshInterval: NodeJS.Timeout | null = null;
  private activityTimeout: NodeJS.Timeout | null = null;
  private readonly config = getSessionConfig();

  constructor() {
    this.setupActivityListeners();
  }

  private setupActivityListeners() {
    // Reset activity timeout on user interaction
    const events = ['mousedown', 'mousemove', 'keypress', 'scroll', 'touchstart', 'click'];
    
    events.forEach(event => {
      document.addEventListener(event, () => {
        this.resetActivityTimeout();
      }, true);
    });

    // Handle visibility change (tab switching)
    document.addEventListener('visibilitychange', () => {
      if (!document.hidden) {
        this.resetActivityTimeout();
      }
    });
  }

  private resetActivityTimeout() {
    if (this.activityTimeout) {
      clearTimeout(this.activityTimeout);
    }

    this.activityTimeout = setTimeout(() => {
      this.showSessionWarning();
    }, this.config.WARNING_TIMEOUT);

    // Set the main activity timeout
    setTimeout(() => {
      this.handleSessionTimeout();
    }, this.config.ACTIVITY_TIMEOUT);
  }

  private showSessionWarning() {
    // Show a warning modal to the user that their session will expire soon
    store.dispatch(
      setPopup({
        show: true,
        data: {
          container: {
            name: "sessionWarning",
            dimensions: { width: "400px", height: "auto", show: "none" },
          },
          type: "custom",
        },
      })
    );
  }

  private handleSessionTimeout() {
    // Session has timed out due to inactivity
    logout();
    store.dispatch(
      setUserAuthStatus({
        isAuthorized: false,
        isRegistered: false,
        role: "guest",
      })
    );
  }

  private async refreshToken() {
    try {
      const token = localStorage.getItem("_auth");
      if (!token) {
        return;
      }

      // Call your refresh token endpoint
      const response = await fetch(`${process.env.REACT_APP_API_URL || "https://campusroot.com/"}${this.config.REFRESH_ENDPOINT}`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        }
      });

      if (response.ok) {
        const data = await response.json();
        if (data.AccessToken) {
          localStorage.setItem("_auth", data.AccessToken);
          console.log("Token refreshed successfully");
        }
      } else {
        // If refresh fails, logout the user
        logout();
      }
    } catch (error) {
      console.error("Token refresh failed:", error);
      logout();
    }
  }

  public startSession() {
    // Start the refresh interval
    this.refreshInterval = setInterval(() => {
      this.refreshToken();
    }, this.config.REFRESH_INTERVAL);

    // Start activity monitoring
    this.resetActivityTimeout();
  }

  public stopSession() {
    if (this.refreshInterval) {
      clearInterval(this.refreshInterval);
      this.refreshInterval = null;
    }

    if (this.activityTimeout) {
      clearTimeout(this.activityTimeout);
      this.activityTimeout = null;
    }
  }

  public extendSession() {
    this.resetActivityTimeout();
    this.refreshToken();
  }

  public handleExtendSession() {
    this.resetActivityTimeout();
    this.refreshToken();
  }
}

// Create a singleton instance
const sessionManager = new SessionManager();

export default sessionManager;
