import React, { ReactNode, useState } from 'react';
import Box from '@mui/material/Box';
import Tabs from '@mui/material/Tabs';
import Tab from '@mui/material/Tab';
import PropTypes from 'prop-types';

interface TabData {
  label: string;
  Component: ReactNode;
}

interface CustomTabsProps {
  tabs: TabData[];
  initialValue?:number|undefined;
  handler?:Function|undefined
}

function TabPanel(props: { children?: ReactNode; index: number; value: number; }) {
  const { children, value, index } = props;

  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`simple-tabpanel-${index}`}
      aria-labelledby={`simple-tab-${index}`}
    >
      {value === index && (
        <Box>
          <Box>{children}</Box>
        </Box>
      )}
    </div>
  );
}

TabPanel.propTypes = {
  children: PropTypes.node,
  index: PropTypes.number.isRequired,
  value: PropTypes.number.isRequired,
};

const CustomTabs: React.FC<CustomTabsProps> = ({ tabs, initialValue, handler }) => {
  const [value, setValue] = useState(initialValue !== undefined ? initialValue : 0);
  const handleChange = (event: React.ChangeEvent<{}>, newValue: number) => {
    setValue(newValue);
    if (handler !== undefined) {
      handler({ name: "tabSelected", data: tabs[newValue].label });
    }
  };

  return (
    <Box sx={{height:"100%",width:"100%"}}>
      <Tabs
        value={value}
        onChange={handleChange}
        aria-label="basic tabs example"
        style={{width:"100%",}}
        sx={{
          '& .MuiTabs-flexContainer': {
            paddingLeft:"10px",
            gridTemplateColumns: `repeat(${tabs.length}, 1fr)`,
            justifyContent:"flex-start" 
          },
          "& .MuiTabs-root": {
            display: "inline-block !important"
          },
          "& .MuiTab-root.Mui-selected": {
            borderBottom: "2px solid #495052  !important",
            color: "#495052 !important"
          },
          "& .MuiTabs-scroller": {
            overflowX: "scroll !important",
            "&::-webkit-scrollbar": {
              width: "12px",
            },
            "&::-webkit-scrollbar-thumb": {
              backgroundColor: "#fff",
              borderRadius: "8px",
            },
            "& .MuiTabs-indicator ": {
              backgroundColor: "transparent",
            },
            "& .MuiTab-root": {
              color: "#8E9091",
              fontWeight: 600
            }
          }
        }}
      >
        {tabs.map(({ label }, i) => (
          <Tab
            label={label}
            key={i}
            sx={{
              textTransform: 'none',
              fontSize: { sm: '16px', xs: "14px" },
              mb: 2,
            }}
          />
        ))}
      </Tabs>
      {tabs.map(({ Component }, i) => (
        <TabPanel value={value} index={i} key={i} >
          {Component}
        </TabPanel>
      ))}
    </Box>
  );
}


export default CustomTabs;
