export const StateFilter = (props: {
  data: FilterInfo;
  onSelection: any;
  normalizeType: any;
  appliedFilter: FilterSelected;
  appliedFilters: FilterSelected[] | undefined;
} | any) => {
  const navigate = useNavigate();
  const destination: any = destinationList;

  const stateList = (country: string) => {
    return destination[country] ? Object.keys(destination[country]) : [];
  };

  const countrieslist = props?.appliedFilters?.find(
    (item: FilterSelected) => item.type === "country"
  );

  const statesByCountry = countrieslist?.data?.flatMap((country: any) => {
    return country?.value ? stateList(country.value) : [];
  }) || [];

  const [searchQuery, setSearchQuery] = useState("");
  const [selectedValue, setSelectedValue] = useState("");

  const onSelection = (val: any) => {
    const filterData = FilterHandler({
      data: val,
      filterInfo: props.data,
      filter: props.appliedFilter,
    });

    const encodedUrl = location.search.slice(1);
    let decodedUrl = "";
    try {
      decodedUrl = window.atob(encodedUrl);
    } catch (error) {
      console.error("Error decoding URL", error);
      decodedUrl = "";
    }

    const urlParams = new URLSearchParams(decodedUrl);
    let FilterUrl = urlParams.get("FilterData");
    const allFilters = FiltersHandler(
      filterData,
      FilterUrl ? JSON.parse(FilterUrl) : []
    );

    navigate(getExploreUrl("filterData", allFilters));
    setSelectedValue(val.value);
  };

  useEffect(() => {
    if (!countrieslist || statesByCountry.length === 0) {
      setSelectedValue("");
    }
  }, [countrieslist, statesByCountry]);

  const containsText = (text: string, searchText: string) =>
    (text || "").toLowerCase().includes((searchText || "").toLowerCase());

  const displayedOptions = useMemo(
    () =>
      statesByCountry.filter((option: any) => containsText(option, searchQuery)),
    [searchQuery, statesByCountry]
  );

  return (
    <Box>
      <FormControl fullWidth>
        <Select
          value=""
          onChange={(e) =>
            onSelection({ name: e?.target?.value, value: e?.target?.value })
          }
          onClose={() => setSearchQuery("")}
          renderValue={(selected: any) => {
            if (!selected) {
              return (
                <Typography
                  sx={{ textTransform: "capitalize", fontSize: "14px", display: "flex", alignItems: "center", gap: "0.5rem", fontWeight: "500" }}
                >
                  <img src={props.data.icon} alt="icon" style={{ width: "15px" }} />
                  State
                </Typography>
              )
            }
            return selected;
          }}
          size="small"
          fullWidth
          displayEmpty
          sx={{
            "&.MuiInputBase-root": {
              borderRadius: "0px !important",
            },
            "& .MuiOutlinedInput-notchedOutline": {
              borderBottom: "1px solid #00000033 !important",
              border: 0
            },
          }}
          defaultValue=""
          MenuProps={{
            PaperProps: {
              sx: {
                maxHeight: 300,
                maxWidth: 300,
                "&.MuiPaper-root": {
                  boxShadow: 3,
                  borderRadius: "15px !important",
                },
              },
            },
            autoFocus: false,
          }}
          IconComponent={ExpandMoreIcon}
        >

          {countrieslist && (
            <ListSubheader>
              <TextField
                size="small"
                // autoFocus
                placeholder="Type to search..."
                fullWidth
                autoFocus={true}
                InputProps={{
                  startAdornment: (
                    <InputAdornment position="start">
                      <SearchIcon />
                    </InputAdornment>
                  ),
                }}
                onChange={(e) => setSearchQuery(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key !== "Escape") {
                    e.stopPropagation();
                  }
                }}
              />
            </ListSubheader>
          )}

          {countrieslist ? (
            displayedOptions.length > 0 ? (
              displayedOptions.map((option: any, i: number) => (
                <MenuItem
                  key={i}
                  value={option}
                  sx={{
                    "& .MuiTypography-root": {
                      fontSize: "14px !important",
                    },
                    "& .MuiSvgIcon-root ": {
                      fontSize: "1rem",
                    },
                    whiteSpace: "normal",
                  }}
                >
                  <Box
                    sx={{
                      display: "flex",
                      justifyContent: "space-between",
                      width: "100%",
                      alignItems: "center",
                    }}
                  >
                    <Typography fontWeight="300"> {option}</Typography>
                    {props.appliedFilter?.data.find(
                      (data: any) => data.value === option
                    ) ? (
                      <CheckCircleIcon fontSize="small" />
                    ) : (
                      ""
                    )}
                  </Box>
                </MenuItem>
              ))
            ) : (
              <MenuItem disabled>No options available</MenuItem>
            )
          ) : (
            <MenuItem disabled>Please select country</MenuItem>
          )}
        </Select>
      </FormControl>
    </Box>
  );

}
