export const Budget = (
  props:
    | {
      data: FilterInfo;
      onSelection: any;
      normalizeType: any;
      appliedFilter: FilterSelected;
      appliedFilters: FilterSelected[] | undefined;
    }
    | any
) => {
  const [minBudget, setMinBudget] = useState<number>(0);
  const [maxBudget, setMaxBudget] = useState<number>(5000000);
  const navigate = useNavigate();

  const handleSliderChange = (_event: Event, newValue: number | number[]) => {
    if (Array.isArray(newValue)) {
      setMinBudget(newValue[0]);
      setMaxBudget(newValue[1]);
    }
  };
  const onSelection = (val: any) => {
    const filterData = { type: "budget", data: [{ name: `${minBudget}`, value: minBudget }, { name: `${maxBudget}`, value: maxBudget }] }
    const encodedUrl = location.search.slice(1);
    let decodedUrl = "";
    try {
      decodedUrl = window.atob(encodedUrl);
    } catch (error) {
      console.error("Error decoding URL", error);
      decodedUrl = "";
    }

    const urlParams = new URLSearchParams(decodedUrl);
    let FilterUrl = urlParams.get("FilterData");
    const allFilters = FiltersHandler(
      filterData,
      FilterUrl ? JSON.parse(FilterUrl) : []
    );
    navigate(getExploreUrl("filterData", allFilters));
  };
  const handleSliderChangeCommitted = (
    event: React.ChangeEvent<{}>,
    value: number | number[]
  ) => {
    if (Array.isArray(value)) {
      onSelection(value);
    }
  };
  return (
    <div style={{padding:"1rem"}}>
      <Typography
        sx={{ textTransform: "capitalize", fontSize: "14px", display: "flex", alignItems: "center", gap: "0.5rem", fontWeight: "500",ml:2 }}
      >
        <img src={Images.budget} alt="icon" style={{ width: "15px" }} />
        Budget
      </Typography>
      <Stack direction="row" spacing={1} sx={{ mt: 1 }}>
        <TextField
          name="minBudget"
          label="Min"
          type="number"
          disabled
          size="small"
          value={minBudget}
          sx={{
            "& .MuiInputBase-input ":{
              padding:"8px"
            }
          }}
          onChange={(e: any) => setMinBudget(e.target.value)}
        />
        <TextField
          name="maxBudget"
          label="Max"
          disabled
          type="number"
          size="small"
          value={maxBudget}
          sx={{
            "& .MuiInputBase-input ":{
              padding:"8px"
            }
          }}
          onChange={(e: any) => setMaxBudget(e.target.value)}
        />
      </Stack>
      <Slider
        getAriaLabel={() => "budget range"}
        min={1}
        max={5000000}
        value={[minBudget, maxBudget]}
        onChange={handleSliderChange}
        onChangeCommitted={(event, value) =>
          handleSliderChangeCommitted(event as React.ChangeEvent<{}>, value)
        }
        step={1}
        sx={{
          mt: 2,
          mx: 3,
          width: { xs: "80%", md: "70%" },
          color: "#979a9d",
          height: "2px",
          "& .MuiSlider-thumb ": {
            backgroundColor: "#b5b5f1"
          }, "& .MuiSlider-track": {
            backgroundColor: "#FFDAA1"
          }
        }}
      />
    </div>
  );
};
