import { Box, Button, Stack, Typography } from "@mui/material";
import React, { useState } from "react";
import FormGroup from "@mui/material/FormGroup";
import { useNavigate } from "react-router-dom";
import DisabledByDefaultOutlinedIcon from "@mui/icons-material/DisabledByDefaultOutlined";
import { getRecommendations } from "../services";
import { useAppDispatch, useAppSelector } from "../assets/hooks";
import Images from "../assets";
import { Event } from "../types/types";
import { closePopup } from "../store/Slices/popupSlice";
import { CustomButton } from "../genericComponents/customButton";
import { setRecommended } from "../store/Slices/recommendations";

const ChecklistPopupforAi = () => {
  const preference = useAppSelector((state) => state.preferences);
  const education = useAppSelector((state) => state.educationhistory);
  const testscores = useAppSelector((state) => state.testscores);
  const navigate = useNavigate();
  const dispatch = useAppDispatch();
  // eslint-disable-next-line
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const gpaChecked = education.data.underGraduation?.totalScore !== undefined;
  
  const courseChecked = (preference?.data?.courses?.length ?? 0) > 0;

  const grechecked =
    testscores?.data?.find(
      (test) => test.name === "Graduate Record Examination"
    );

  const handleChecklist = async () => {
    if (gpaChecked && courseChecked && grechecked) {
      setLoading(true);
      try {
        const response = await getRecommendations({});
        if (response) {
          dispatch(setRecommended(response.data.data));
          dispatch(closePopup());
        } else {
        }
      } catch (error) {
      } finally {
        setLoading(false);
      }
    }
  };

  const eventHandler = (event: Event) => {
    switch (event.name) {
      case "gre":
        navigate("/profile/personal");
        dispatch(closePopup());
    }
  };

  return (
    <div>
      <Box>
        <Box sx={{ textAlign: "center" }}>
          <Typography fontSize="24px" fontWeight="500">
            Your AI recommended Checklist
          </Typography>
          <Typography>
            Please submit the following scores and course preferences for AI
            recommendations
          </Typography>
        </Box>
        <Box
          sx={{
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
          }}
        >
          <FormGroup>
            <Box
              sx={{
                mb: 2,
                mt: 2,
                display: "flex",
                justifyContent: "space-between",
              }}
            >
              <Stack direction="row" spacing={2}>
                {gpaChecked ? (
                  <img
                    src={Images.checklist}
                    alt="checklist"
                    style={{ height: "25px" }}
                  />
                ) : (
                  <DisabledByDefaultOutlinedIcon sx={{ color: "#EB5757" }} />
                )}
                <Typography>UG GPA</Typography>
              </Stack>
              {!gpaChecked ? (
                <Button
                  sx={[{ ml: 3,textTransform:"none" }]}
                  onClick={() => eventHandler({ name: "gre", data: "" })}
                >
                  Add GPA{" "}
                </Button>
              ) : (
                ""
              )}
            </Box>
            <Box
              sx={{ mb: 2, display: "flex", justifyContent: "space-between" }}
            >
              <Stack direction="row" spacing={2}>
                {grechecked ? (
                  <img
                    src={Images.checklist}
                    alt="checklist"
                    style={{ height: "25px" }}
                  />
                ) : (
                  <DisabledByDefaultOutlinedIcon sx={{ color: "#EB5757" }} />
                )}
                <Typography>GRE</Typography>
              </Stack>
              {!grechecked ? (
                <Button
                  sx={[{ ml: 3 ,textTransform:"none" }]}
                  onClick={() => eventHandler({ name: "gre", data: "" })}

                >
                  Add GRE{" "}
                </Button>
              ) : (
                ""
              )}
            </Box>
            <Box
              sx={{ mb: 2, display: "flex", justifyContent: "space-between" }}
            >
              <Stack direction="row" spacing={2}>
                {courseChecked ? (
                  <img
                    src={Images.checklist}
                    alt="checklist"
                    style={{ height: "25px" }}
                  />
                ) : (
                  <DisabledByDefaultOutlinedIcon sx={{ color: "#EB5757" }} />
                )}
                <Typography>Course preferences</Typography>
              </Stack>
              {!courseChecked ? (
                <Button
                  sx={[{ ml: 3,textTransform:"none"  }]}
                  onClick={() => eventHandler({ name: "gre", data: "" })}

                >
                  Add Courses{" "}
                </Button>
              ) : (
                ""
              )}
            </Box>
          </FormGroup>
        </Box>
        <Box sx={{ display: "flex", justifyContent: "center", mt: 2 }}>
          <CustomButton
           width="100px"
            handleSubmit={handleChecklist}
          >
            {loading ? (
              <Box
                component="img"
                src={Images.standardLoader}
                alt="standardLoader"
                sx={{ width: "1rem", height: "1rem" }}
              />
            ) : (
              "Continue"
            )}
          </CustomButton>
        </Box>
      </Box>
    </div>
  );
};

export default ChecklistPopupforAi;
