import { PayloadAction, createSlice } from "@reduxjs/toolkit";
import { Advisor, StoreItem,} from "../../types/types";

let initialState:StoreItem<Advisor[]>={
    requestStatus:"not_initiated",
    responseStatus:"not_recieved",
    haveAnIssue:false,
    issue:"",
    data:[]
}
export const advisorsSlice=createSlice({
    name:'advisors',
    initialState:initialState,
    reducers:{
        initAdvisorInfo:(state,action:PayloadAction<StoreItem<Advisor[]>>)=>({...action.payload}),
        addAdvisorInfo:(state,action:PayloadAction<Advisor>)=>{state.data.push(action.payload)},
        updateAdvisorInfo:(state,action:PayloadAction<Advisor>)=>{
            let index=state.data.findIndex((item)=>item._id===action.payload._id);
            state.data[index]=action.payload;
        },
        removeAdvisorInfo:(state,action:PayloadAction<string>)=>{state.data=state.data.filter((item)=>item?._id!==action?.payload)},
        setAdvisorInfo:(state,action:PayloadAction<Advisor[]>)=>{state.data=action.payload},
        resetAdvisor:(state,action:PayloadAction)=>({...initialState})

    }
});

export const {initAdvisorInfo,setAdvisorInfo,resetAdvisor,addAdvisorInfo,updateAdvisorInfo}=advisorsSlice.actions;
export default advisorsSlice.reducer;