import { PayloadAction, createSlice } from "@reduxjs/toolkit";
import { SuggestedPackage, StoreItem } from "../../types/types";

let initialState:StoreItem<SuggestedPackage[]>={
    requestStatus:"not_initiated",
    responseStatus:"not_recieved",
    haveAnIssue:false,
    issue:"",
    data:[]
}

export const PurchasedPackageSlice=createSlice({
    name:'PurchasedPackage',
    initialState:initialState,
    reducers:{
        initPurchasedPackage:(state,action:PayloadAction<StoreItem<SuggestedPackage[]>>)=>({...action.payload}),
        addPurchasedPackage:(state,action:PayloadAction<SuggestedPackage>)=>{state.data.push(action.payload)},
        setPurchasedPackage:(state,action:PayloadAction<SuggestedPackage[]>)=>{state.data=action.payload},
        // updatePurchasedPackage:(state,action:PayloadAction<PurchasedPackage>)=>{
        //     let index=state.data.findIndex((item)=>item._id===action.payload._id);
        //     state.data[index]=action.payload;
        // },
        //  removePurchasedPackage:(state,action:PayloadAction<string>)=>{state.data=state.data.filter((item)=>item._id!==action.payload)},
        resetPurchasedPackage:(state,action:PayloadAction)=>({...initialState})

    }
})

export const {initPurchasedPackage,addPurchasedPackage,resetPurchasedPackage,setPurchasedPackage}=PurchasedPackageSlice.actions;
export default PurchasedPackageSlice.reducer;