// Reusable CountryCard Component
const CountryCard: React.FC<{ country: Country; isSelected: boolean; onSelect: () => void }> = ({
  country,
  isSelected,
  onSelect,
}) => (
  <Grid item xs={12} sm={6} md={4} lg={3}>
    <Typography
      role="button"
      aria-label={country.name}
      sx={{
        position: "relative",
        ...testReadyStyles.card2,
        height: { xs: "48px", md: "60px" },
        width: { xs: "200px", sm: "220px", md: "250px", lg: "250px" },
        minWidth: { xs: "200px", sm: "220px", md: "250px", lg: "250px" },
        maxWidth: { xs: "200px", sm: "220px", md: "250px", lg: "250px" },
        borderLeftColor: country.bgcolor,
        boxShadow: `0px 4px 12px rgba(0, 0, 0, 0.2)`,
        background: isSelected ? `linear-gradient(145deg, ${country.bgcolor}, #ffffff)` : "transparent",
        transition: "0.4s ease-in-out",
        cursor: "pointer",
        "&:hover": {
          boxShadow: `0px 8px 18px ${country.bgcolor}`,
        },
        p: { xs: 1, sm: 2 },
        mx: "auto",
        display: "flex",
        justifyContent: "center"
      }}
      onClick={onSelect}
    >
      <CardContent
        sx={{
          display: "flex",
          flexDirection: "row",
          alignItems: "center",
          gap: { xs: 0.5, sm: 2 },
          p: { xs: "4px !important", sm: "16px !important" },
          width: "100%",
          minWidth: 0
        }}
      >
        {/* Country Flag */}
        <Box sx={{ 
          width: { xs: "20px", sm: "28px", md: "30px" }, 
          height: { xs: "20px", sm: "28px", md: "30px" }, 
          borderRadius: "50%", 
          overflow: "hidden",
          flexShrink: 0,
          boxShadow: "0 2px 8px rgba(44, 47, 92, 0.18)"
        }}>
          <Box
            component="img"
            src={country.flag}
            alt={country.name}
            sx={{ width: "100%", height: "100%", objectFit: "cover" }}
          />
        </Box>

        {/* Country Name */}
        <Typography 
          variant="body1" 
          sx={{ 
            fontSize: { xs: "11px", sm: "14px", md: "16px" }, 
            color: "black",
            textAlign: "left",
            overflow: "hidden",
            textOverflow: "ellipsis",
            whiteSpace: "nowrap",
            flex: 1,
            minWidth: 0
          }}
        >
          {country.name}
        </Typography>
      </CardContent>
    </Typography>
  </Grid>
);

const DestinationSelection: React.FC = () => {
  const [selectedCountries, setSelectedCountries] = useState<Country[]>([]);
  const navigate = useNavigate();

  const setDestination = (collectedData: { countries: string[] }) => {
    const currentValue = localStorage.getItem("user-profile");
    const currentValueObj = currentValue ? JSON.parse(currentValue) : {};
  
    const updatedProfile = {
      ...currentValueObj,
      preference: {
        ...(currentValueObj.preference || {}),
        country: collectedData.countries,
      },
    };
  
    localStorage.setItem("user-profile", JSON.stringify(updatedProfile));
  };
  
  useEffect(() => {
    const savedProfile = localStorage.getItem("user-profile");
    if (savedProfile) {
      const parsed = JSON.parse(savedProfile);
      const savedCountries: string[] = parsed?.preference?.country || [];
  
      const preselected = countries.filter((country) =>
        savedCountries.includes(country.name)
      );
  
      setSelectedCountries(preselected);
    }
  }, []);
  
  


  // Handle selection
  const handleSelect = (country: Country): void => {
    const updatedSelection = selectedCountries.some((item) => item.id === country.id)
      ? selectedCountries.filter((item) => item.id !== country.id)
      : [...selectedCountries, country];
  
    setSelectedCountries(updatedSelection);
    setDestination({ countries: updatedSelection.map((c) => c.name) });
  };
  

  // Handle Continue
  const handleContinue = (): void => {
    if (selectedCountries.length > 0) {
      navigate("/academicsstatus");
    }
  };

  return (
    <Box sx={{ 
      ...testReadyStyles.container1, 
      px: { xs: 2, sm: 3, md: 4, lg: 8 }, 
      py: { xs: 3, sm: 4, md: 5 },
      minHeight: "100vh",
      display: "flex",
      flexDirection: "column"
    }}>
      {/* Title */}
      <Typography
        variant="h4"
        fontWeight="bold"
        mb={{ xs: 2, sm: 3, md: 4 }}
        sx={{ 
          fontSize: { xs: "1.25rem", sm: "1.5rem", md: "2rem", lg: "2.5rem" }, 
          textAlign: "center",
          px: { xs: 1, sm: 2 },
          color:"#495052"
        }}
      >
        Which countries would you like to <span style={{ color: "#F48438" }}>Study</span> in?
      </Typography>

      {/* Countries Grid */}
      <Box sx={{
        width: "100%",
        maxWidth: "1200px",
        mx: "auto",
        px: { xs: 1, sm: 2, md: 3, lg: 4 },
        overflowY: "auto",
        maxHeight: { xs: 'calc(100vh - 120px)', sm: 'calc(100vh - 140px)', md: 'calc(100vh - 140px)', lg: 'calc(100vh - 140px)' },
        pb: 16,
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        "&::-webkit-scrollbar": {
          width: "8px",
        },
        "&::-webkit-scrollbar-track": {
          background: "#f1f1f1",
        },
        "&::-webkit-scrollbar-thumb": {
          background: "#888",
          borderRadius: "4px",
        },
      }}>
        <Grid container rowSpacing={3} columnSpacing={2} justifyContent="center" alignItems="center" sx={{ width: '100%' }}>
          {countries.map((country) => (
            <CountryCard
              key={country.id}
              country={country}
              isSelected={selectedCountries.some((item) => item.id === country.id)}
              onSelect={() => handleSelect(country)}
            />
          ))}
        </Grid>
      </Box>

      <Box sx={{ 
              position: "fixed", 
              bottom: 0, 
              left: 0, 
              right: 0,
              borderTop: "1px solid #eee",
              py: 3,
              display: "flex", 
              justifyContent: "center", 
              gap: 2,
              zIndex: 1000
            }}>
              <Button variant="text" sx={{ color: "#888" }} onClick={() => navigate(-1)}>
                ← Back
              </Button>
              <Button
          variant="contained"
          sx={{ 
            px: { xs: 2, sm: 4 }, 
            py: { xs: 1, sm: 1.5 },
            borderRadius: "20px",
            background:"#F48438",color:"#FFFF",
            "&:hover": {
      backgroundColor: "#d96f2e",
    },
          }}
          disabled={selectedCountries.length === 0}
          onClick={handleContinue}
        >
          Continue
        </Button>
            </Box>

      {/* Navigation Buttons */}
      {/* <Box sx={{
        mt: 3,
        display: "flex",
        justifyContent: "center",
        gap: 0,
        width: "100%",
        maxWidth: "500px",
        mx: "auto"
      }}>
        <Button 
          variant="text" 
          sx={{ 
            color: "#888",
            width: "100%",
            py: { xs: 1, sm: 1.5 }
          }} 
          onClick={() => navigate(-1)}
        >
          ← Back
        </Button>
        <Button
          variant="contained"
          sx={{ 
            px: { xs: 2, sm: 4 }, 
            py: { xs: 1, sm: 1.5 },
            borderRadius: "20px",
            width: "100%"
          }}
          disabled={selectedCountries.length === 0}
          onClick={handleContinue}
        >
          Continue
        </Button>
      </Box> */}
    </Box>
  );
};

export default DestinationSelection;

