import { PayloadAction, createSlice } from "@reduxjs/toolkit";
import { ExtraCurriculum, StoreItem,} from "../../types/types";

let initialState:StoreItem<ExtraCurriculum[]>={
    requestStatus:"not_initiated",
    responseStatus:"not_recieved",
    haveAnIssue:false,
    issue:"",
    data:[]
}
export const ExtraCurriculumSlice=createSlice({
    name:'ExtraCurriculum',
    initialState:initialState,
    reducers:{
        initExtraCurriculum:(state,action:PayloadAction<StoreItem<ExtraCurriculum[]>>)=>({...action.payload}),
        addExtraCurriculum:(state,action:PayloadAction<ExtraCurriculum>)=>{state.data.push(action.payload)},
        // removeExtraCurriculum:(state,action:PayloadAction<string>)=>{state.data=state.data.filter((item)=>item?._id!==action?.payload)},
        setExtraCurriculum:(state,action:PayloadAction<ExtraCurriculum[]>)=>{state.data=action.payload},
        resetFamily:(state,action:PayloadAction)=>({...initialState})

    }
});

export const {initExtraCurriculum,setExtraCurriculum,resetFamily}=ExtraCurriculumSlice.actions;
export default ExtraCurriculumSlice.reducer;