import { Box, Button, Grid, TextField, Typography } from '@mui/material';
import React, { useState } from 'react';
import Images from 'src/assets';
import { useAppDispatch, useAppSelector } from 'src/assets/hooks';
import { secondaryButton } from 'src/components/styles/customStyles';
import { editProfile } from 'src/services';
import { closePopup } from 'src/store/Slices/popupSlice';
import { setSharedInfo } from 'src/store/Slices/sharedInfoSlice';

const Name = ({ setQaTab, missingFields, qaTab }: any) => {
    const profile = useAppSelector(store => store.sharedInfo)

    const [fname, setFname] = useState(profile?.data?.firstName);
    const [lname, setLname] = useState(profile.data?.lastName);
    const [loading, setLoading] = useState(false)
    const dispatch = useAppDispatch()
    const currentIndex = missingFields.indexOf(qaTab);

    const handleContinue = async () => {
        setLoading(true)
        const response = await editProfile({
            firstName: fname,
            lastName: lname
        });
        if (response.data.success) {
            let values = {
                ...profile.data,
                firstName: fname,
                lastName: lname
            };
            dispatch(
                setSharedInfo({
                    ...values,
                })
            );
            setLoading(false)
            if (currentIndex !== -1 && currentIndex < missingFields.length - 1) {
                setQaTab(missingFields[currentIndex + 1]);
            } else {
                // closePopup();
                dispatch(closePopup())
            }
        }
        else {
            setLoading(false)
        }

    };

    const handleBack = () => {
        if (currentIndex > 0) {
            setQaTab(missingFields[currentIndex - 1]);
        }
    };

    // const handleSkip = () => {
    //     if (currentIndex !== -1 && currentIndex < missingFields.length - 1) {
    //         setQaTab(missingFields[currentIndex + 1]);
    //     } else {
    //         // closePopup();
    //         dispatch(closePopup())
    //     }
    // }

    return (
        <div style={{ height: "100%" }}>
            <Grid container spacing={2} sx={{ height: "100%" }}>
                <Grid item xs={12} md={6} sx={{ background: "#F4F4FF", display: "flex", justifyContent: "center", alignItems: "center" }}>
                    <Typography sx={{ width: "80%" }}>
                    Please enter your first name and last name as they appear on official documents.
Providing accurate details ensures smooth processing and verification.
Ensure there are no spelling mistakes to avoid any discrepancies.
                    </Typography>
                </Grid>
                <Grid item xs={12} md={6} sx={{ display: "flex", justifyContent: "center", alignItems: "center", flexDirection: "column" }}>
                    <Box component="img" src={Images.oneWindow} alt="oneWindow" sx={{ width: { xs: "120px", lg: "180px" } }} />
                    <Typography color="#1C1F4099" sx={{ my: 2 }}>Let us know what name you'd like us to use for you!</Typography>
                    <TextField
                        label="First name"
                        variant="outlined"
                        value={fname}
                        size="small"
                        autoComplete="off"
                        onKeyDown={(e:any) => {
                            if (fname && fname?.length >= 50 && e.key !== 'Backspace' && e.key !== 'Delete') {
                              e.preventDefault();
                            }
                          }}
                        onChange={(e) => setFname(e.target.value)}
                        sx={{ mb: 2, width: '70%' }}
                    />
                    <TextField
                        label="Last name"
                        variant="outlined"
                        value={lname}
                        size="small"
                        autoComplete="off"
                        onChange={(e) => setLname(e.target.value)}
                        sx={{ mb: 2, width: '70%' }}
                        onKeyDown={(e:any) => {
                            if (lname && lname?.length >= 50 && e.key !== 'Backspace' && e.key !== 'Delete') {
                              e.preventDefault();
                            }
                          }}
                    />

                    <Box sx={{ display: 'flex', gap: 2 }}>
                        {currentIndex > 0 && (
                            <Button sx={secondaryButton} onClick={handleBack}>
                                Back
                            </Button>
                        )}
                        <Button sx={secondaryButton} onClick={handleContinue}>
                        {loading ? (
                                      <img
                                        src={Images.standardLoader}
                                        alt="load"
                                        style={{
                                          width: "20px",
                                          height: "20px",
                                          padding: "5px",
                                        }}
                                      />
                                    ) : (
                                      "Continue"
                                    )}
                        </Button>
                        {/* <Button sx={secondaryButton} onClick={handleSkip}>
                        {loading ? (
                                      <img
                                        src={Images.standardLoader}
                                        alt="load"
                                        style={{
                                          width: "20px",
                                          height: "20px",
                                          padding: "5px",
                                        }}
                                      />
                                    ) : (
                                      "Skip"
                                    )}
                        </Button> */}
                    </Box>
                </Grid>
            </Grid>
        </div>
    );
};

export default Name;
