import { PayloadAction, createSlice } from "@reduxjs/toolkit";
import { StoreItem} from "../../types/types";

let initialState: StoreItem<any[]> = {
  requestStatus: "not_initiated",
  responseStatus: "not_recieved",
  haveAnIssue: false,
  issue: "",
  data: [],
};
export const meetingsSlice = createSlice({
  name: "meetings",
  initialState: initialState,
  reducers: {
    initmeetings: (state, action: PayloadAction<StoreItem<any[]>>) => ({
      ...action.payload,
    }),
    addmeetings: (state, action: PayloadAction<any>) => {
      state.data.push(action.payload);
    },
    removemeetings: (state, action: PayloadAction<string>) => {
      state.data = state.data.filter((item) => item._id !== action.payload);
    },
    updatemeetings: (state, action: PayloadAction<any>) => {
      let index = state.data.findIndex(
        (item) => item._id === action.payload._id
      );
      state.data[index] = action.payload;
    },
    setmeetings: (state, action: PayloadAction<any[]>) => {
      state.data = action.payload;
    },
    resetMeetings:(state,action:PayloadAction)=>({...initialState})

  },
});

export const {
  initmeetings,
  addmeetings,
  removemeetings,
  updatemeetings,
  setmeetings,
  resetMeetings
} = meetingsSlice.actions;
export default meetingsSlice.reducer;
