import {
  Box,
  Button,
  Grid,
  // IconButton,
  TextField,
  Typography,
} from "@mui/material";
import { ErrorMessage, Form, Formik } from "formik";
import React, { useEffect, useMemo, useState } from "react";
import Images from "../../assets";
import { useAppDispatch } from "../../assets/hooks";
import { CustomButton } from "../../genericComponents/customButton";
import { authenticateLogin, googleCodeAuthentication, verifyUserOtp } from "../../services";
import * as Yup from "yup";
import { closePopup } from "../../store/Slices/popupSlice";
import { checkUser } from "../../assets/library";
import { GoogleOAuthProvider, GoogleLogin } from "@react-oauth/google";
import ReactPhoneInput from "react-phone-input-2";
import OTPInput from "./otpInput";
import { secondaryButton } from "../styles/customStyles";
import KeyboardBackspaceIcon from '@mui/icons-material/KeyboardBackspace';
import parsePhoneNumberFromString from "libphonenumber-js";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import { setProfile } from "src/store/Slices/profile";

const API_URL = "https://campusroot.com/api/v1/student/profile";

const Login = () => {
  const [loading, setLoading] = useState<boolean>(false);
  const dispatch = useAppDispatch();
  const [loginMethod, setLoginMethod] = useState<any>('initial');
  const [phone, setPhone] = useState({
    countryCode: "",
    phoneNumber: "",
  });
  const navigate=useNavigate()

  const handleSendToBackend = async () => {
    console.log("Auth",localStorage.getItem("_auth"));
    try {
      let profileData=localStorage.getItem("user-profile");
      let profileObj=profileData?JSON.parse(profileData):{};
      let res=await axios.put(API_URL, profileObj, {
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${localStorage.getItem("_auth")}`,
        },
      });
      console.log("✅ Profile updated successfully.");
      console.log("Profile Res",JSON.stringify(res.data))
      dispatch(setProfile(res.data.data))
    } catch (error) {
      console.error("❌ Error updating data:", error);
      alert("Failed to update profile data.");
    }
  }
  const [email, setEmail] = useState("");
  const initValues = {
    email: email,
  };
  const loginSchema = Yup.object().shape({
    email: Yup.string()
      .matches(
        /([a-z0-9]+)([{1}])?([a-zA-Z0-9]+)([a-zA-Z0-9]+)([a-z]+)/g,
        "Enter valid Email"
      )
      .required("Enter Email")
      .max(40, "Email must be atmost 40 characters"),
  });
  const validationSchema = Yup.object().shape({
    countryCode: Yup.string().required('Country code is required'),
    phoneNumber: Yup.string()
      .required("Phone number is required")
      .test("is-valid-phone", "Invalid phone number", function (value) {
        const { countryCode } = this.parent;
        if (!countryCode || !value) return false; // Ensure both countryCode and number are provided

        try {
          const phoneNumber = parsePhoneNumberFromString(`${countryCode}${value}`, countryCode);
          return phoneNumber?.isValid();
        } catch (error) {
          return false;
        }
      })
  });
  const otpSchema = Yup.object().shape({
    otp: Yup.string()
      .required("Please enter a valid OTP")
      .matches(/^[0-9]+$/, "Must be only digits")
      .min(6, "Must be exactly 6 digits")
      .max(6, "Must be exactly 6 digits"),
  });

  const [timer, setTimer] = useState<any>(60);
  const [canRetry, setCanRetry] = useState(false);

  const onSubmitForm = async (values: any) => {
    setLoading(true);
    try {
      const response = await authenticateLogin(values);
      if (response.data.success) {
        setLoginMethod("verify");
        setCanRetry(false);
        setLoading(false);
      }
    } catch (err) {
      console.log(err);
    }
  };

  useEffect(() => {
    if (timer > 0 && loginMethod === "verify") {
      const countdown = setInterval(() => {
        setTimer((prevTime: any) => prevTime - 1);
      }, 1000);
      return () => clearInterval(countdown);
    } else if (timer === 0) {
      setCanRetry(true);
    }
  }, [timer, loginMethod]);

  const formatTime = (seconds: number) => {
    const minutes = Math.floor(seconds / 60);
    const remainingSeconds = seconds % 60;
    return `${minutes}:${remainingSeconds < 10 ? '0' : ''}${remainingSeconds}`;
  };

  const handleRetry = () => {
    setTimer(180);
    setCanRetry(false);
    onSubmitForm(phone);
  };

  const verifyCodeSubmit = async (values: any) => {
    setLoading(true);
    try {
      const response = await verifyUserOtp(
        {
          otp: values.otp,
          countryCode: phone.countryCode,
          phoneNumber: phone.phoneNumber,
          type: "phone"
        }
      );
      if (response?.data?.success === true) {
        localStorage.setItem("_auth", response?.data?.AccessToken);
        localStorage.setItem("missingFields", JSON.stringify(response?.data?.data?.missingFields));
        console.log("User profile",localStorage.getItem("user-profile"));
        if(localStorage.getItem("user-profile")){
          await handleSendToBackend();
          localStorage.removeItem("user-profile");
          navigate('/profile/recommendedCourses/generate')
        }
        dispatch(closePopup())
        if (response?.data?.data?.missingFields?.length > 0) {
          // dispatch(
          //   setPopup({
          //     show: true,
          //     data: {
          //       container: {
          //         name: "qasection",
          //         dimensions: {
          //           width: "40%",
          //           height: "90%",
          //           show: "none",
          //           close: "none"
          //         },
          //       },
          //       type: "custom",
          //     },
          //   }))
        } else {
          dispatch(closePopup())
        }
        checkUser();
      } else {
      }
    } catch (error) {
    }
    setLoading(false);
  };

  const handlePhoneChange = (value: string, data: any) => {
    const dialCode = data?.dialCode || "";
    const enteredCountryCode = dialCode.trim();
    if (value.startsWith(enteredCountryCode)) {
      setPhone({
        countryCode: "+" + enteredCountryCode,
        phoneNumber: value.slice(enteredCountryCode.length).trim()
      });
    } else {
      const codeSplit = "+" + value.split(dialCode);
      const enteredPhoneNumber = codeSplit.length > 1 ? codeSplit[1].trim() : "";
      setPhone({
        countryCode: enteredCountryCode,
        phoneNumber: enteredPhoneNumber
      });
    }
  };

  const GoogleLoginComponent = () => {
    const login = async (credentialResponse: any) => {
      if (credentialResponse.credential) {
        const response = await googleCodeAuthentication({
          credential: credentialResponse.credential,
        });
        if (response) {
          localStorage.setItem("_auth", response?.data?.AccessToken);
          localStorage.setItem("missingFields", JSON.stringify(response?.data?.data?.missingFields));
          if(localStorage.getItem("user-profile")){
            await handleSendToBackend();
            localStorage.removeItem("user-profile");
            navigate('/profile/recommendedCourses/generate')
          }
          if (
            response?.data?.message === "Google Authentication Successful"
          ) {
            dispatch(closePopup())
            if (response?.data?.data?.missingFields?.length > 0) {
              // dispatch(
              //   setPopup({
              //     show: true,
              //     data: {
              //       container: {
              //         name: "qasection",
              //         dimensions: {
              //           width: "70%",
              //           height: "90%",
              //           show: "none",
              //           close: "none"
              //         },
              //       },
              //       type: "custom",
              //     },
              //   }))
            } else {
              dispatch(closePopup())

            }
          } else if (
            response?.data?.message === "Google Registration Successful"
          ) {
            localStorage.setItem("register", "registered");
            dispatch(closePopup())
            if (response?.data?.data?.missingFields?.length > 0) {
              // dispatch(
              //   setPopup({
              //     show: true,
              //     data: {
              //       container: {
              //         name: "qasection",
              //         dimensions: {
              //           width: "70%",
              //           height: "90%"
              //         },
              //       },
              //       type: "custom",
              //     },
              //   }))
            } else {
              dispatch(closePopup())

            }

            // dispatch(
            //   setPopup({
            //     show: true,
            //     data: {
            //       container: {
            //         name: "phonenumber",
            //         dimensions: {
            //           width: "400px",
            //           height: "35%",
            //           close: "none",
            //           show: "none"

            //         },
            //       },
            //       type: "custom",
            //     },
            //   })
            // );
          }
          checkUser();
        }
      }
    };

    return (
      <GoogleOAuthProvider clientId="982398000165-od316la08j0lb5ff53qs91agp4k9ug65.apps.googleusercontent.com">
        <GoogleLogin
          onSuccess={(credentialResponse) => {
            login(credentialResponse);
          }}
          onError={() => {
          }}
        />
      </GoogleOAuthProvider>
    );
  };
  // eslint-disable-next-line
  const MemoizedGoogleLoginComponent = useMemo(() => <GoogleLoginComponent />, []);

  return (
    <Box sx={{ height: "100%" }}>
      <Grid container sx={{ height: "100%" }}>
        <Grid item xs={0} sm={5.5} sx={{ height: { xs: "100%" }, background: "#FFF1DD", display: { sm: "flex", xs: "none" }, gap: "5px", justifyContent: "center", flexDirection: "column", alignItems: "center", position: "relative" }}>
          <img src={Images.loginImg} alt="loginImg" style={{ width: "200px" }} />
          <Typography fontSize="1.25rem" color="#495052" sx={{ mt: 1 }} fontWeight="600">We make studying abroad easier</Typography>
          <Typography color="#495052" fontSize="0.8rem" fontWeight="400">Over 8000+ Universities and 70000+ Courses</Typography>
          {/* <p style={{
            position: 'absolute',
            left: '10%',
            top: '12%', background: "#BEC0F0", width: "1rem", height: "1rem", margin: 0, borderBottomLeftRadius: "20px", transform: "rotate(-130deg"
          }}></p>
          <p style={{
            position: 'absolute',
            right: '0',
            top: '20%', background: "#E2E4FF", width: "1.2rem", height: "2rem", margin: 0, borderRadius: "100PX 0 0 100px"
          }}></p> */}
        </Grid>
        <Grid item xs={12} sm={6.5} sx={{ display: "flex", flexDirection: "column", justifyContent: "center", alignItems: "center" }}>
          <Box sx={{ px: { xs: 2, sm: 4 }, width: "80%", my: { sm: 3, md: 0 } }}>
            <Box sx={{ mb: 1.5, display: "flex", justifyContent: "center", position: "relative" }}>
              <Box component="img" src={Images.oneWindow} alt="logo" sx={{ width: { xs: "120px", md: "180px" } }} />
              <img src={Images.flightRight} alt="flight" style={{ width: "3.5rem", height: "3.5rem", position: "absolute", left: "-25px" }} />
              <Box component="img" src={Images.passport} alt="flight" sx={{ width: "35px", height: "35px", position: "absolute", right: "-35px", top: { xs: "-60px", sm: "-15px", md: "-60px" } }} />
            </Box>

            <Grid container >
              <Grid item xs={12} sx={{}}>
                <Typography sx={{ textAlign: "center", fontSize: "1.1rem", fontWeight: "500" }}>Sign up or Login</Typography>
              </Grid>
              <Grid item xs={12} sx={{ height: "250px" }}>

                {
                  loginMethod === "initial" ?
                    <>
                      <Box sx={{ mt: 4 }}>
                        <Formik
                          initialValues={phone}
                          validationSchema={validationSchema}
                          onSubmit={(values: any) => onSubmitForm(phone)}
                          enableReinitialize={true}
                        >
                          {({ errors, touched, handleChange, values, handleSubmit }) => (
                            <Form
                              onKeyDown={(e) => {
                                if (e.key === "Enter") {
                                  e.preventDefault(); 
                                  handleSubmit(); 
                                }
                              }}
                            >
                              <Grid
                                container
                                spacing={1.25}
                                sx={{
                                  display: "flex",
                                  flexDirection: "column",
                                  justifyContent: "center",
                                  alignItems: "center",
                                }}
                              >
                                <Grid item xs={12} sx={{ width: "75%" }}>
                                  <ReactPhoneInput
                                    value={`${phone.countryCode}${phone.phoneNumber}`}
                                    onChange={handlePhoneChange}
                                    country="in"
                                    inputProps={{
                                      name: "phone",
                                      required: true,
                                    }}
                                    inputStyle={{
                                      width: "100%",
                                      height: "40px",
                                      border: touched.phoneNumber && errors.phoneNumber
                                        ? "1px solid red"
                                        : "1px solid #ced4da",
                                      backgroundColor: "#fff",
                                    }}
                                  />
                                  {touched.countryCode && errors.countryCode && (
                                    <Typography variant="caption" color="rgb(211, 47, 47)">
                                      {errors.countryCode}
                                    </Typography>
                                  )}
                                  &nbsp;
                                  {touched.phoneNumber && errors.phoneNumber && (
                                    <Typography variant="caption" color="rgb(211, 47, 47)">
                                      {errors.phoneNumber}
                                    </Typography>
                                  )}
                                </Grid>
                                <Grid
                                  item
                                  xs={12}
                                  sx={{ display: "flex", justifyContent: "center", mt: 2 }}
                                >
                                  {phone.phoneNumber.length === 10 && (
                                    <Button
                                      type="submit"
                                      disabled={!phone.phoneNumber}
                                      sx={[secondaryButton, { width: "200px" }]}
                                    >
                                      {loading ? (
                                        <img
                                          src={Images.standardLoader}
                                          alt="load"
                                          style={{ width: "20px", height: "20px", padding: "5px" }}
                                        />
                                      ) : (
                                        "Continue"
                                      )}
                                    </Button>
                                  )}
                                </Grid>
                              </Grid>
                            </Form>
                          )}
                        </Formik>

                        <Box
                          sx={{
                            my: 3,
                            width: "100%",
                            display: "flex",
                            justifyContent: "center",
                          }}
                        >
                          {MemoizedGoogleLoginComponent}
                        </Box>
                      </Box>
                    </> : loginMethod === "verify" ?
                      <Box sx={{ mt: 4 }}>
                        <KeyboardBackspaceIcon sx={{ color: "grey", cursor: "pointer", mb: 1.5 }} onClick={() => {
                          setTimer(60)
                          setLoginMethod("initial")
                        }} />
                        <Typography
                          sx={{
                            fontSize: { xs: "20px" },
                            fontWeight: 600,
                          }}
                        >
                          OTP verification{" "}
                        </Typography>
                        <Typography sx={{ fontSize: "16px", fontWeight: "500" }}>
                          {`Please enter the otp we have sent to your ${phone?.countryCode === "+91" ? "Phone" : "Whatsapp"} ${phone?.phoneNumber}`}
                        </Typography>
                        <Formik
                          initialValues={{
                            otp: "",
                            phone,
                          }}
                          validationSchema={otpSchema}
                          onSubmit={verifyCodeSubmit}
                        >
                          {({ values, handleChange }) => {
                            return (
                              <Form
                                style={{
                                  marginTop: "1rem",
                                  display: "flex",
                                  flexDirection: "column",
                                  justifyContent: "center",
                                }}
                              >
                                <OTPInput
                                  length={6}
                                  style={{
                                    display: "flex",
                                    justifyContent: "space-evenly",
                                    marginBottom: "20px",
                                  }}
                                  name="otp"
                                  isNumberInput
                                  autoFocus
                                  inputClassName="otpinput"
                                  value={values.otp}
                                  onChangeOTP={(otp: any) => (values.otp = otp)}
                                />
                                <div style={{ color: "#e60c0c", fontSize: "12px", marginLeft: "20px" }}>
                                  <ErrorMessage
                                    name="otp"
                                    component="div"
                                    className="error"
                                  />
                                </div>
                                <div style={{ textAlign: 'center', margin: '10px 0' }}>
                                  {canRetry ? (
                                    <span onClick={handleRetry} style={{ color: "#03a9f4" }}>Retry</span>
                                  ) : (
                                    <span>Retry available in {formatTime(timer)} minutes.</span>
                                  )}
                                </div>
                                <Box sx={{ my: 1, display: "flex", justifyContent: "center" }}>
                                  <CustomButton
                                    handleSubmit={() => console.log("")}
                                    width="100px"
                                  >
                                    {loading ? (
                                      <img
                                        src={Images.standardLoader}
                                        alt="load"
                                        style={{ width: "20px", height: "20px", padding: "5px" }}
                                      />
                                    ) : (
                                      "Continue"
                                    )}
                                  </CustomButton>
                                </Box>
                              </Form>
                            );
                          }}
                        </Formik>
                      </Box> :
                      <Box sx={{ mt: 4 }}>
                        <KeyboardBackspaceIcon sx={{ color: "grey", cursor: "pointer", mb: 1.5 }} onClick={() => setLoginMethod("initial")} />
                        <Formik
                          initialValues={initValues}
                          validationSchema={loginSchema}
                          onSubmit={(values: any) => onSubmitForm(values)}
                          enableReinitialize={true}
                        >
                          {({ errors, touched, values, handleChange }) => (
                            <Form >
                              <Grid container spacing={1.25} >
                                <Grid item xs={12} sx={{}}>
                                  <TextField
                                    id="email"
                                    name="email"
                                    type="email"
                                    size="small"
                                    label="Email *"
                                    placeholder="Enter email"
                                    value={email}
                                    onChange={(e: any) => setEmail(e.target.value)}
                                    error={touched.email && Boolean(errors.email)}
                                    fullWidth
                                    sx={{
                                      "&::placeholder": {
                                        color: "#000 !important"
                                      },
                                      '& .MuiOutlinedInput-root .Mui-error': {
                                        '& fieldset': {
                                          borderColor: 'red',
                                        },
                                      },
                                    }}
                                  />
                                  <div style={{ color: "#e60c0c", fontSize: "12px" }}>
                                    <ErrorMessage name="email" component="div" />
                                  </div>
                                </Grid>
                                <Grid item xs={12} sx={{ display: "flex", justifyContent: "center", mt: 2 }}>
                                  <Button
                                    sx={[secondaryButton, { width: "200px" }]}
                                    type="submit">
                                    {loading ? (
                                      <img
                                        src={Images.standardLoader}
                                        alt="load"
                                        style={{
                                          width: "20px",
                                          height: "20px",
                                          padding: "5px",
                                        }}
                                      />
                                    ) : (
                                      "Continue"
                                    )}
                                  </Button>

                                </Grid>

                              </Grid>
                            </Form>
                          )}
                        </Formik>
                      </Box>

                }
              </Grid>


            </Grid>
          </Box>
        </Grid>
      </Grid>
    </Box>
  );
};

export default Login;
