import { Avatar, Box, Button, Grid, Typography } from '@mui/material'
import React, { useContext } from 'react'
import Razor from './razor';
import ArrowBackIcon from '@mui/icons-material/ArrowBack';
import { Event } from '../../../../types/types';
import Context from 'src/assets/constants/context';
import CalendarMonthIcon from '@mui/icons-material/CalendarMonth';
import TimerIcon from "@mui/icons-material/Timer";

const Payment = (props: any) => {
const {courses} = useContext(Context);
const {summary }= useContext(Context);

const products = courses.map((item:any) => ({
    category: item.category,
    courseId: item.course._id,
    intake: item.intake
  }));

  const mappedItems = summary?.items?.map((item: any) => {
    const course = courses.find(
      (course: any) =>
        course.course._id === item.details.courseId &&
        course.intake === item.details.intake
    );
    return {
      ...item,
      course: course || item,
    };
  });
  const formatDate = (dateString: string): string => {
    const date = new Date(dateString);
    const month = date.toLocaleString("default", { month: "short" });
    const year = date.getFullYear();
    return `${month} ${year}`;
  };
  // console.log(products)
  const eventHandler = async(event:Event) =>{
    switch (event.name) {
      case "checkout":
        props.setActiveTab("Products")
        break;
        default:
        break;
    }
  }
  return (
    <div>
      <Box sx={{ height: '520px', overflowY: 'scroll' }}>
        <Typography sx={{ fontSize: "1.5rem", color: "#3B3F7680", display: "flex", gap: "0.5rem", alignItems: "center", fontWeight: "600" }}>
          <p style={{ background: "#FEB853", width: "1rem", height: "1rem", margin: 0, borderRadius: "50%" }}></p>
          Order Summary</Typography>
        <Box
          sx={{
            overflowX: 'auto',
            // whiteSpace: 'nowrap',
            padding: '0 1rem',
            scrollbarWidth: 'none',
            '&::-webkit-scrollbar': {
              display: 'none',
            },
          
          }}
        >
          <Grid container spacing={3} sx={{
            flexWrap: 'nowrap',
            alignItems: 'center',
            width: "100%", p: 1,
            '&::-webkit-scrollbar': {
              width: '12px',
              backgroundColor: '#fff',
            },
            '&::-webkit-scrollbar-thumb': {
              backgroundColor: '#fff',
              borderRadius: '8px',
            },
            '&::-webkit-scrollbar-track': {
              backgroundColor: '#fff',
            },
            // height:"220px"
          }}>
            {mappedItems?.map((item: any, i: number) => (
              <Grid item xs={12} md={3} key={i}>
                <Box sx={{ background: "#fff", borderRadius: "15px", p: 2,boxShadow:2 }}>
                  <Box sx={{ display: "flex", gap: "1rem",flexDirection:"column",justifyContent:"center",alignItems:"center" }}>
                    {item?.course?.course?.university?.logoSrc ? <Avatar src={item?.course?.course?.university?.logoSrc} alt="logo" />:""}
                    <div style={{display:"flex",flexDirection:"column",gap:"0.5rem",justifyContent:"center",alignItems:"center"}}>
                    <Typography  textAlign="center" sx={{
                      fontSize: { xs: "12px", lg: "13px" },
                      fontWeight: 500,
                      textOverflow: "ellipsis ",
                      lineClamp: 1,
                      height: "2.3rem",
                      textTransform: "capitalize",
                      overflow: "hidden",
                      display: "-webkit-box",
                      WebkitLineClamp: "2",
                      WebkitBoxOrient: "vertical",
                    }}>{item?.course?.course?.name || item?.course?.details?.name} </Typography>
                    <Typography fontSize="14px" color="#A8A8A8">{item?.course?.course?.university?.name}</Typography>
                    <Typography
                      component="span"
                      fontSize="0.8rem"
                      fontWeight="500"
                      sx={{
                        display: "flex",
                        alignItems: "center",
                        whiteSpace: "nowrap",
                        mt: 1,
                      }}
                    >
                      <TimerIcon sx={{ fontSize: "1.25rem" }} />
                      &nbsp; Start date:{" "}
                      {item.intake ? formatDate(item.intake) : "N/A"}
                    </Typography>
                    <Typography fontSize="14px" >{item?.originalPrice >0?item?.currency?.symbol +" "+ item?.originalPrice.toLocaleString("en-US"):"Free"}</Typography>
                    </div>
                  </Box>
                </Box>
              </Grid>
            ))}

          </Grid>
            <Box  sx={{display:"flex",justifyContent:"center",flexDirection:"column",gap:"0.8rem",alignItems:"center",mt:3
        }}>
          <Box sx={{textAlign:"start",gap:"0.7rem",display:"flex",flexDirection:"column"}}>
          <Typography sx={{fontSize:"1rem",color:"#3b3f76"}}>Price Details</Typography>
          <Typography sx={{display:"flex",alignItems:"center"}}>Total Amount : {mappedItems[0]?.currency?.symbol +" "+ summary?.totalPrice.toLocaleString("en-US")}</Typography>
          <Typography sx={{fontSize:"12px",color:"#3b3f76",display:"flex",alignItems:"center",gap:"0.5rem",cursor:"pointer"}} onClick={() => window.open("/refundPolicy", "_blank")} ><CalendarMonthIcon sx={{fontSize:"14px"}}/> 7 days cancellation / refund policy</Typography>
            <Razor data={products} total={ summary?.totalPrice.toLocaleString("en-US")}/>
            </Box>
        </Box>
        </Box>
      </Box>
      <Button sx={{
        borderRadius: "50%", minWidth: 0,
        background: "#3b3f76",
        height: "2.5rem",
        width: "2.5rem",
        color: "#fff",
        "&:hover": {
          background: "#3b3f76",
          color: "#fff",
        }
      }} 
      onClick={() =>
        eventHandler({ name: "checkout"})
      }
      // onClick={() => props.setActiveTab("Payment")}
      >
        <ArrowBackIcon />
      </Button>
    </div>
  )
}

export default Payment