import React from 'react';
import { Box, Button, Typography } from '@mui/material';
import sessionManager from '../../assets/sessionManager';
import { useAppDispatch } from '../../assets/hooks';
import { closePopup } from '../../store/Slices/popupSlice';

interface SessionWarningModalProps {
  data?: any;
  link?: any;
  eventHandler?: any;
}

const SessionWarningModal: React.FC<SessionWarningModalProps> = ({ data, link, eventHandler }) => {
  const dispatch = useAppDispatch();

  const handleExtendSession = () => {
    sessionManager.handleExtendSession();
    dispatch(closePopup());
  };

  const handleLogout = () => {
    sessionManager.stopSession();
    dispatch(closePopup());
    // The logout will be handled by the session manager
  };

  return (
    <Box
      sx={{
        width: '100%',
        height: '100%',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        p: 4,
        textAlign: 'center',
      }}
    >
      <Box
        sx={{
          width: { xs: '90%', sm: 400 },
          bgcolor: 'background.paper',
          borderRadius: 2,
          boxShadow: 24,
          p: 4,
          textAlign: 'center',
        }}
      >
        <Typography variant="h6" component="h2" gutterBottom color="warning.main">
          Session Timeout Warning
        </Typography>
        
        <Typography variant="body1" sx={{ mb: 3 }}>
          Your session will expire in 5 minutes due to inactivity. 
          Would you like to extend your session?
        </Typography>
        
        <Box sx={{ display: 'flex', gap: 2, justifyContent: 'center' }}>
          <Button
            variant="outlined"
            onClick={handleLogout}
            sx={{ minWidth: 100 }}
          >
            Logout
          </Button>
          <Button
            variant="contained"
            onClick={handleExtendSession}
            sx={{ minWidth: 100 }}
          >
            Extend Session
          </Button>
        </Box>
      </Box>
    </Box>
  );
};

export default SessionWarningModal;
