import { Box, Button, Grid, TextField, Typography } from '@mui/material'
import React, { useEffect, useState } from 'react'
import Images from 'src/assets'
import { secondaryButton } from 'src/components/styles/customStyles'
import { Form, Formik, ErrorMessage } from "formik";
import * as Yup from "yup";
import { verifyEmailPhone, verifyEmailPhoneOtp } from 'src/services';
import { useAppDispatch } from 'src/assets/hooks';
import OTPInput from 'src/components/authentication/otpInput';
import KeyboardBackspaceIcon from '@mui/icons-material/KeyboardBackspace';
import { CustomButton } from 'src/genericComponents/customButton';
import { closePopup } from 'src/store/Slices/popupSlice';
import { setEmailVerificationStatus } from 'src/store/Slices/verificationSlice';
import {  setWordCase } from 'src/assets/library';

const Email = ({ setQaTab, missingFields, qaTab }: any) => {
    const [email, setEmail] = useState("");
    const [error, setError] = useState("");

    const dispatch = useAppDispatch();
    const currentIndex = missingFields.indexOf(qaTab);
    const [active, setActive] = useState<"email" | "verify">("email");
    const [loading, setLoading] = useState(false);
    const [timer, setTimer] = useState(60);
    const [canRetry, setCanRetry] = useState(false);


    const otpSchema = Yup.object().shape({
        otp: Yup.string().required("Required").matches(/^[0-9]+$/, "Must be only digits").min(6, "Must be exactly 6 digits").max(6, "Must be exactly 6 digits"),
    });

    useEffect(() => {
        if (timer > 0 && active === "verify") {
            const countdown = setInterval(() => setTimer((prevTime) => prevTime - 1), 1000);
            return () => clearInterval(countdown);
        } else if (timer === 0) setCanRetry(true);
    }, [timer, active]);

    const handleRetry = () => {
        setTimer(180);
        setCanRetry(false);
        onSubmitForm({ email: email });
    };

    const formatTime = (seconds: number) => {
        const minutes = Math.floor(seconds / 60);
        const remainingSeconds = seconds % 60;
        return `${minutes}:${remainingSeconds < 10 ? '0' : ''}${remainingSeconds}`;
    };

    const onSubmitForm = async (values: any) => {
        setLoading(true);
        try {
            const response = await verifyEmailPhone(values);
            if (response) {
                setActive("verify")
            } else {
                setLoading(false);
            }
            setLoading(false);
        } catch (err:any) {
            setLoading(false);
            setError(err.response.data.message)
        }
    };
    const [isEmailValid, setIsEmailValid] = useState(true);

    const validateEmail = (email: string) => {
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/; 
        return emailRegex.test(email);
    };

    const handleEmailChange = (e: any) => {
        const value = e.target.value;
        setEmail(value);
        setIsEmailValid(validateEmail(value));
    };
    const verifyCodeSubmit = async (values: any) => {
        setLoading(true);
        try {
            const response = await verifyEmailPhoneOtp({
                otp: values.otp,
                type: "email"
            });
            if (response?.data?.success) {
                dispatch(setEmailVerificationStatus(response.data?.data?.emailLoginOtp.verified))
                if (currentIndex !== -1 && currentIndex < missingFields.length - 1) {
                    setQaTab(missingFields[currentIndex + 1]);
                } else {
                    dispatch(closePopup());
                }

            }
        } catch (error) { }
        setLoading(false);
    };

    const handleBack = () => {
        if (currentIndex > 0) setQaTab(missingFields[currentIndex - 1]);
    };

    // const handleSkip = () => {
    //     if (currentIndex !== -1 && currentIndex < missingFields.length - 1) {
    //         setQaTab(missingFields[currentIndex + 1]);
    //     } else {
    //         // closePopup();
    //         dispatch(closePopup())
    //     }
    // }

    return (
        <div style={{ height: "100%" }}>
            <Grid container spacing={2} sx={{ height: "100%" }}>
                <Grid item xs={12} md={6} sx={{ background: "#F4F4FF", display: "flex", justifyContent: "center", alignItems: "center" }}>
                    <Typography sx={{ width: "80%" }}>
                        Please enter you mail ID to receive a
                        One-Time Password (OTP).This will be sent to your
                        mobile for verification purposes. Ensure the number
                        is correct to avoid any delays.
                    </Typography>

                </Grid>
                <Grid item xs={12} md={6} sx={{ display: "flex", justifyContent: "center", alignItems: "center", flexDirection: "column" }}>
                    <Box component="img" src={Images.oneWindow} alt="oneWindow" sx={{ width: { xs: "120px", lg: "180px" } }} />
                    {active === "email" ?
                        <Box sx={{ width: "80%",  mt: 3 }}>
                            <TextField
                                label="Email Address"
                                variant="outlined"
                                value={email}
                                size="small"
                                type="email"
                                required
                                autoComplete="off"
                                onChange={handleEmailChange}
                                error={!isEmailValid && email !== ''}
                                helperText={!isEmailValid && email !== '' ? 'Please enter a valid email address' : ''}
                                sx={{ mb: 1, width: '100%' }}
                            />
                            {error&& <Typography color="red" sx={{textAlign:"start !important"}}>{setWordCase(error)}</Typography>}
                            <Box sx={{ display: 'flex', gap: 2 ,flexDirection: "column", justifyContent: "center", alignItems: "center",mt:3}}>
                                {currentIndex > 0 && (
                                    <Button sx={secondaryButton} onClick={handleBack}>
                                        Back
                                    </Button>
                                )}
                                <Button sx={secondaryButton} onClick={() => onSubmitForm({ email: email })} disabled={!email || !isEmailValid || error !==""}>
                                    {loading ? (
                                        <img
                                            src={Images.standardLoader}
                                            alt="load"
                                            style={{
                                                width: "20px",
                                                height: "20px",
                                                padding: "5px",
                                            }}
                                        />
                                    ) : (
                                        "Continue"
                                    )}
                                </Button>
                                {/* <Button sx={secondaryButton} onClick={handleSkip}>
                        {loading ? (
                                      <img
                                        src={Images.standardLoader}
                                        alt="load"
                                        style={{
                                          width: "20px",
                                          height: "20px",
                                          padding: "5px",
                                        }}
                                      />
                                    ) : (
                                      "Skip"
                                    )}
                        </Button>  */}
                            </Box>
                        </Box> :
                        <Box sx={{ mt: 4 }}>
                            <KeyboardBackspaceIcon sx={{ color: "grey", cursor: "pointer", mb: 1.5 }} onClick={() => {
                                setTimer(60)
                                setActive("email")
                            }
                            } />
                            <Typography sx={{ fontSize: { xs: "20px" }, fontWeight: 600 }}>OTP verification</Typography>
                            <Typography sx={{ fontSize: "16px", fontWeight: 500 }}>{`Please enter the OTP sent to ${email}`}</Typography>
                            <Formik initialValues={{ otp: "", type: "email" }} validationSchema={otpSchema} onSubmit={verifyCodeSubmit}>
                                {({ values, handleChange }) => (
                                    <Form style={{ marginTop: "1rem", display: "flex", flexDirection: "column", justifyContent: "center" }}>
                                        <OTPInput
                                            length={6}
                                            style={{
                                                display: "flex",
                                                justifyContent: "space-evenly",
                                                marginBottom: "20px",
                                            }}
                                            name="otp"
                                            isNumberInput
                                            autoFocus
                                            inputClassName="otpinput"
                                            value={values.otp}
                                            onChangeOTP={(otp: any) => (values.otp = otp)}
                                        />
                                        <Typography variant="caption" color="error"><ErrorMessage name="otp" /></Typography>
                                        <Box sx={{ textAlign: "center", my: 2 }}>
                                            {canRetry ? <span onClick={handleRetry} style={{ color: "#03a9f4", cursor: "pointer" }}>Retry</span> : `Retry in ${formatTime(timer)} minutes.`}
                                        </Box>
                                        <Box sx={{ my: 1, display: "flex", justifyContent: "center" }}>
                                            <CustomButton handleSubmit={() => console.log("")} width="100px">{loading ? "Loading..." : "Verify"}</CustomButton>
                                        </Box>
                                    </Form>
                                )}
                            </Formik>
                        </Box>
                    }
                </Grid>

            </Grid>
        </div>
    )
}

export default Email;