// Session timeout configuration
export const SESSION_CONFIG = {
  // Token refresh interval (how often to refresh the token)
  REFRESH_INTERVAL: 10 * 60 * 1000, // 10 minutes
  
  // Activity timeout (how long before session expires due to inactivity)
  ACTIVITY_TIMEOUT: 30 * 60 * 1000, // 30 minutes
  
  // Warning timeout (when to show warning before session expires)
  WARNING_TIMEOUT: 25 * 60 * 1000, // 25 minutes (5 minutes before expiry)
  
  // API request timeout
  API_TIMEOUT: 30 * 1000, // 30 seconds
  
  // Token refresh endpoint
  REFRESH_ENDPOINT: '/api/v1/auth/refresh',
  
  // Local storage key for auth token
  AUTH_TOKEN_KEY: '_auth',
} as const;

// Environment-specific overrides
export const getSessionConfig = () => {
  const config = { ...SESSION_CONFIG };
  
  // Override with environment variables if available
  if (process.env.REACT_APP_SESSION_REFRESH_INTERVAL) {
    config.REFRESH_INTERVAL = parseInt(process.env.REACT_APP_SESSION_REFRESH_INTERVAL) * 60 * 1000;
  }
  
  if (process.env.REACT_APP_SESSION_ACTIVITY_TIMEOUT) {
    config.ACTIVITY_TIMEOUT = parseInt(process.env.REACT_APP_SESSION_ACTIVITY_TIMEOUT) * 60 * 1000;
  }
  
  if (process.env.REACT_APP_SESSION_WARNING_TIMEOUT) {
    config.WARNING_TIMEOUT = parseInt(process.env.REACT_APP_SESSION_WARNING_TIMEOUT) * 60 * 1000;
  }
  
  if (process.env.REACT_APP_API_TIMEOUT) {
    config.API_TIMEOUT = parseInt(process.env.REACT_APP_API_TIMEOUT) * 1000;
  }
  
  return config;
};
