import {
  Box,
  Button,
  Divider,
  Grid,
  Stack,
  Tooltip,
  Typography,
} from "@mui/material";
import React, { useRef, useState } from "react";
// import { Link } from "react-router-dom";
import Images from "../../../../assets";
import { useAppDispatch, useAppSelector } from "../../../../assets/hooks";
import { setWordCase } from "../../../../assets/library";
import { statusList } from "../../../../assets/menu";
import {
  CustomTimeline,
  CustomTimelineItem,
} from "../../../../genericComponents/timeline";
import {
  cancellationRequest,
  studentJustifyApply,
  studentJustifyRemove,
  uploadApplicationDocs,
} from "../../../../services";
import { Application, Event } from "../../../../types/types";
import InfoOutlinedIcon from "@mui/icons-material/InfoOutlined";
import FileUploadOutlinedIcon from "@mui/icons-material/FileUploadOutlined";
import { setDocuments } from "../../../../store/Slices/documentsSlice";
import { updateApplication } from "../../../../store/Slices/applicationsSlice";
import TimerIcon from '@mui/icons-material/Timer';

interface log {
  status: string;
  stages: {
    name: string;
    updatedAt: string;
    _id: string;
  }[];
  _id: string;
}
// interface checklistDoc{
//   _id?: any;
//   name?:string;
//   contentType?:string;
//   createdAt?: Date;
// }

const Logs = (props: { data: log[] }) => {
  return (
    <div>
      <Box style={{}}>
        <h4>Stages</h4>
        <CustomTimeline>
          {props.data?.map((item: any, index: any) =>
            statusList.map((status, i) => {
              const stage = item.stages.find((s: any) => s.name === status);
              const statusExists = !!stage;
              return (
                <CustomTimelineItem
                  key={i}
                  content={`Step ${i + 1}`}
                  style={{
                    color: statusExists ? "#3B3F76" : "#646262",
                  }}
                >
                  <Tooltip
                    slotProps={{
                      tooltip: {
                        sx: {
                          color: "#495052",
                          backgroundColor: "#fff",
                          boxShadow: 2,
                        },
                      },
                    }}
                    title={
                      statusExists
                        ? `Updated At: ${stage.updatedAt.slice(0, 10)}`
                        : ""
                    }
                  >
                    <p
                      style={{
                        marginLeft: "15px",
                        marginBottom: "5px",
                        fontSize: "14px",
                        fontWeight: statusExists ? "500" : "400",
                      }}
                    >
                      {status}
                    </p>
                  </Tooltip>
                </CustomTimelineItem>
              );
            })
          )}
        </CustomTimeline>
      </Box>
    </div>
  );
};

const Checklist = (props: { data: Application }) => {

  const dispatch = useAppDispatch();
  const [loading, setLoading] = useState(false);
  const inputFile = useRef<HTMLInputElement>(null);
  const handleSubmit = async (
    event: React.ChangeEvent<HTMLInputElement>,
    item: any
  ) => {
    const file = event.target.files && event.target.files[0];
    try{

    if (file !== null && file !== undefined) {
      setLoading(true)
      const formData = new FormData();
      formData.append("uploaded_file", file || null);
      formData.append("applicationId", props.data._id);
      formData.append("checklistItemId", item._id);
      const response = await uploadApplicationDocs(formData);
      if (response) {
        dispatch(setDocuments(response.data.data.docs));
        dispatch(
          updateApplication(response.data.data)
        );
      }
    } else {
    setLoading(false)
    }
  }catch(err){
    setLoading(false)

  }
  };

  const imageClick = () => {
    inputFile?.current?.click();
  };
  return (
    <div>
      <h4>Checklist by Process Coordinator</h4>
      {props.data?.docChecklist && props.data?.docChecklist.length > 0 ? (
        <>
          {props.data?.docChecklist.map((checklist:any) => (
            <Grid
            container
            sx={{
              p: 1,
              margin:"10px",
              width:"auto"
            }}
          >
            <Grid item xs={6}>
              <Typography fontWeight="500" fontSize="14px">
                {setWordCase(checklist.name)}
              </Typography>
            </Grid>
            <Grid
              item
              xs={6}
              sx={{
                display: "flex",
                height: "20px",
                justifyContent: "space-between",
              }}
            >
              {checklist?.doc ? (
                <Box
                  sx={{
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "space-between",
                  }}
                >
                    <h4
                      className="font-semibold"
                      style={{
                        color: "#000",
                        display: "flex",
                        alignItems: "center",
                        fontSize: "12px",
                        // width: "120px",
                        whiteSpace: "nowrap",
                        overflow: "hidden",
                        textOverflow: "ellipsis",
                      }}
                    >
                      {checklist?.doc?.data?.FileName}
                    </h4>
                  {/* </Link> */}
                </Box>
              ) : (
                <>
                  <input
                    style={{ display: "none" }}
                    type="file"
                    className=""
                    name="image"
                    onChange={(event) => handleSubmit(event, checklist)}
                    ref={inputFile}
                    accept=".pdf"
                  />
                  <Button
                    sx={{
                      color: "#000",
                      textTransform: "none",
                      p: 0.25,
                      fontSize: "0.7rem",
                      ml: 1,
                    }}
                    onClick={imageClick}
                  >
                    {loading ? (
                      <Box
                        component="img"
                        src={Images.standardLoader}
                        alt="standardLoader"
                        sx={{ width: "1rem", height: "1rem" }}
                      />
                    ) : (
                      <FileUploadOutlinedIcon />
                    )}
                  </Button>
                </>
              )}
              <Typography
                sx={{
                  fontSize: "11px",
                  margin: "2px 2px 0 0",
                  position: "relative",
                  cursor: "pointer",
                  "&:hover .cancel-icon": {
                    display: "block !important",
                  },
                }}
              >
                <InfoOutlinedIcon
                  sx={{ color: "#FF751A", fontSize: "1rem" }}
                />
                {checklist?.desc && (
                  <span
                    className="cancel-icon"
                    style={{
                      display: "none",
                      color: "#000",
                      position: "absolute",
                      padding: "2px",
                      maxWidth: "200px",
                      zIndex: 1,
                      textAlign: "center",
                      right: 0,
                      border: "1px solid #000",
                      borderRadius: "5px"
                    }}
                  >
                    {checklist.desc}
                  </span>
                )}
              </Typography>
            </Grid>
          </Grid>
          ))}
        </>
      ) : (
        <Box
          sx={{
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            height: "200px",
            flexDirection: "column",
          }}
        >
          <img
            src={Images.noData}
            alt="noData"
            style={{ width: "70px", height: "70px", marginBottom: "1rem" }}
          />
          <Typography>No Checklist </Typography>
        </Box>
      )}
    </div>
  );
};

const ApplicationPopup = (props: { data: string }) => {
  const applications = useAppSelector((state) => state.applications);
  const application: any = applications?.data?.find(
    (value: Application) => value._id === props.data
  );
  function date(date: Date) {
    const month = date.toLocaleString("default", { month: "short" });
    const year = date.getFullYear();
    return month + " " + year;
  }
  const eventHandler = async (event: Event) => {
    switch (event.name) {
      case "cancelApplication":
        try {
          const response = await cancellationRequest(event.data._id, {});
          console.log(response);
        } catch (error) {}
        break;
      case "forceApply":
        try {
          const response = await studentJustifyApply({
            applicationId: event.data?._id,
          });
          if (response) {
          }
        } catch (error) {}
        break;
      case "forceRemove":
        try {
          const response = await studentJustifyRemove({
            applicationId: event.data?._id,
          });
          if (response) {
          }
        } catch (error) {}
        break;
    }
  };
  return (                              
    <div style={{padding:"1rem",overflowY:"scroll"}}>
      <Box sx={{ margin: "0 9%",background:"#F4F4FF", p: 2, borderRadius: "10px",mb:1 }}>
        <Typography fontWeight="600" fontSize="16px">
          {application.course.name}{" "}
        </Typography>
        <Stack sx={{ my: 1 }} spacing={1}>
          <Typography fontSize="0.95rem" color="">
            <img
              src={application.course?.university.logoSrc}
              alt="logo"
              style={{ width: "1rem", marginRight: "5px" }}
            />
            {application.course?.university.name}
          </Typography>
          <Typography fontSize="0.9rem" sx={{paddingLeft:"22px"}}>
            {application.course?.university.location.city},
            {application.course?.university.location.country}
          </Typography>
        </Stack>
        <Typography sx={{display:"flex",justifyContent:"end",gap:"5px",fontSize:"14px"}}> <TimerIcon/> Start date : {application?.intake ? date(new Date(application?.intake)) : "Not available"}</Typography>
      </Box>
      <Grid container>
        <Grid item xs={12} md={5.5}>
          <Logs data={application.log} />
        </Grid>
        <Divider orientation="vertical" flexItem />
        <Grid item xs={12} md={6} sx={{ ml: 2 }}>
          <Checklist data={application} />
        </Grid>
      </Grid>
      <Box sx={{ display: "flex", justifyContent: "center", my: 2 }}>
        {application?.cancellationRequest ? (
          ""
        ) : (
          <Button
            sx={{
              border: "1px solid #3B3F76",
              color: "#3B3F76",
              textTransform: "none",
              borderRadius:"10px",
              "&:hover": {
                background: "#FFF",
                color: "#3B3F76",
              },
            }}
            onClick={() =>
              eventHandler({ name: "cancelApplication", data: application })
            }
          >
            Cancellation Request
          </Button>
        )}
      </Box>
    </div>
  );
};

export default ApplicationPopup;
