import React, { useEffect, useRef, useState } from "react";
import Button from "@mui/material/Button";
import Images from "../../assets/index";
import {
  Box,
  CircularProgress,
  Grid,
  InputAdornment,
  List,
  ListItemButton,
  ListItemText,
  Paper,
  Stack,
  TextField,
  Typography,
} from "@mui/material";
import SearchIcon from "@mui/icons-material/Search";
import { editProfile, getSearchUniversityDetails } from "../../services";
import CloseIcon from "@mui/icons-material/Close";
import { Event } from "../../types/types";
import { subDisciplines } from "../../assets/menu";
import { setpreferences } from "../../store/Slices/preferencesSlice";
import { useAppDispatch, useAppSelector } from "../../assets/hooks";
import { secondaryButton } from "src/components/styles/customStyles";
import { closePopup } from "src/store/Slices/popupSlice";

const CourseDetails = ({ setQaTab, missingFields, qaTab }: any) => {
  const currentIndex = missingFields.indexOf(qaTab);
  const coursePreference = useAppSelector(state => state.preferences);
  const [selectedAreaOfStudy, setSelectedAreaOfStudy] = useState<string[]>(coursePreference?.data?.courses || []);
  const [subdisciplines, setsubdisciplines] = useState<string[]>([]);
  const [searchValue, setSearchValue] = useState("");
  const listRef = useRef<HTMLUListElement | null>(null);
  const [error, setError] = useState("")
  const [loading, setLoading] = useState<boolean>(false);

  const handleBack = () => {
    if (currentIndex > 0) {
      setQaTab(missingFields[currentIndex - 1]);
    }
  };
  const dispatch = useAppDispatch();

  useEffect(() => {
    if (searchValue) {
      setLoading(true);
      getSearchUniversityDetails(searchValue,1,8, 0, 1, 1, 1,1)
        .then((response) => {
          setLoading(false);
          setsubdisciplines(response.data?.subDisciplines);
        })
        .catch((error) => {
          console.error("Error fetching institutions:", error);
          setLoading(false);
        });
    } else {
      setsubdisciplines([]);
    }
  }, [searchValue]);

  const eventHandler = (event: Event) => {
    switch (event.name) {
      case "inputChange":
        setSearchValue(event.data.target.value);
        break;
      case "clicksearch":
        setSearchValue(event.data.target.value);
        break;
      case "focus":
        if (searchValue) {
          // setMenuOpen(true);
        }
        break;
    }
  };

  const handleContinue = async () => {
    setLoading(true)

    let values = {
      ...coursePreference.data,
      courses: selectedAreaOfStudy,
    };
    const response = await editProfile({
      preference: values
    });
    if (response) {
      // console.log(response);
      dispatch(setpreferences(response.data.data.preference));
      if (currentIndex !== -1 && currentIndex < missingFields.length - 1) {
        setQaTab(missingFields[currentIndex + 1]);
    } else {
        // closePopup();
        dispatch(closePopup())
    }
    setLoading(false)

    } else {
    setLoading(false)

    }
  };

  const handleMouseLeave = (event?: MouseEvent) => {
    if (
      listRef?.current &&
      event &&
      !listRef?.current?.contains(event.target as Node)
    ) {
      setsubdisciplines([]);
    }
  };

  useEffect(() => {
    document.addEventListener("click", handleMouseLeave);
    return () => {
      document.removeEventListener("click", handleMouseLeave);
    };
  }, []);

  const handleSubDisciplineChange = (item: any) => {
    if (selectedAreaOfStudy.includes(item)) {
      setSelectedAreaOfStudy(selectedAreaOfStudy.filter((c: any) => c !== item));
    } else {
      setSelectedAreaOfStudy([...selectedAreaOfStudy, item]);
    }
    setSearchValue("");
    setsubdisciplines([]);
  };

  const toggleAreaOfStudySelection = (course: string) => {
    if (selectedAreaOfStudy.includes(course)) {
      setSelectedAreaOfStudy(selectedAreaOfStudy.filter((c: any) => c !== course));
    } else if (selectedAreaOfStudy.length < 5) {
      setSelectedAreaOfStudy([...selectedAreaOfStudy, course]);
    } else {
      setError("You can select up to 5 areas of study only.");
      setTimeout(() => {
        setError(""); // Clear the error after 3 seconds
      }, 3000);
    }
  };

  const handleSkip = () => {
    if (currentIndex !== -1 && currentIndex < missingFields.length - 1) {
        setQaTab(missingFields[currentIndex + 1]);
    } else {
        // closePopup();
        dispatch(closePopup())
    }
}
  return (
    <>
      <Typography
        sx={{
          color: "#3B3F76",
          textAlign: "center",
          fontFamily: "Inter",
          fontWeight: 700,
          fontSize: { xs: "20px", sm: "28px" },
          mb: 3,
          mt: 2
        }}
      >
        What are your{" "}
        <b style={{ color: "rgba(48, 51, 99, 0.5)" }}>preferred area of studyyyyyy?</b>
      </Typography>

      <Stack
        direction="row"
        spacing={3}
        sx={{
          display: { xs: "flex" },
          flexDirection: "row",
          justifyContent: "center",
          alignItems: "center",
          mb: 3,
        }}
      >
        <Box>
          <TextField
            placeholder="Search"
            variant="outlined"
            size="small"
            sx={{
              width: { xs: "300px", sm: "500px" },
              marginTop: "8px",
              position: "relative",
              "& .MuiOutlinedInput-root": {
                borderRadius: "0.5rem",
                // paddingLeft:"0"
              },
              "& .MuiOutlinedInput-notchedOutline": {
                borderColor: "#3B3F76",
              },
            }}
            autoComplete="off"
            onFocus={() => eventHandler({ name: "focus", data: "" })}
            onClick={(event) =>
              eventHandler({ name: "clicksearch", data: event })
            }
            InputProps={{
              startAdornment: (
                <InputAdornment position="start">
                  <SearchIcon />

                </InputAdornment>
              ),
              endAdornment: (
                <>
                  {loading && <CircularProgress color="inherit" size={20} />}
                </>
              ),
            }}
            onChange={(event) =>
              eventHandler({ name: "inputChange", data: event })
            }
          />
          {subdisciplines?.length > 0 && (
            <Paper sx={{}}>
              <List
                sx={{
                  maxHeight: 400,
                  overflow: "auto",
                  position: "absolute",
                  zIndex: 1,
                  background: "#fff",
                  width: "400px",
                  boxShadow: 12,
                }}
                ref={listRef}
              >
                <Grid container>
                  {subdisciplines.length > 0 && (
                    <Grid item xs={12}>
                      {subdisciplines.length > 0 ? (
                        <Typography
                          sx={{
                            pl: 1,
                            color: "gray",
                            fontSize: "14px",
                            fontWeight: "500",
                          }}
                        >
                          Sub disciplines
                        </Typography>
                      ) : (
                        ""
                      )}
                      {subdisciplines.map((option, index) => (
                        <ListItemButton
                          key={index}
                          onClick={() => {
                            handleSubDisciplineChange(option);
                          }}
                          sx={{ pt: 0, pb: 0.5 }}
                        >
                          <ListItemText
                            primary={option}
                            sx={{
                              "& .MuiTypography-root": {
                                fontSize: "14px !important",
                              },
                            }}
                          />
                        </ListItemButton>
                      ))}
                    </Grid>
                  )}
                </Grid>
              </List>
            </Paper>
          )}
        </Box>
      </Stack>
      <Box sx={{ minHeight: "70px", maxHeight: "100px" }}>
        {selectedAreaOfStudy?.length > 0 ? (
          <Stack
            direction="row"
            sx={{ mb: 1, background: "#F4F4FF", p: 1 }}
            spacing={2}
          >
            {selectedAreaOfStudy?.map((item, i) => (
              <Button
                key={i}
                sx={{
                  border: "1px solid #FEB853",
                  p: 0.8,
                  borderRadius: "15px",
                  textTransform: "capitalize",
                  color: "#000",
                  background: "#fff",
                  fontSize: "14px"
                }}
              >
                {item}
                <CloseIcon
                  // fontSize="1.5rem"
                  sx={{ marginLeft: 1, fontSize: "1.2rem" }}
                  onClick={() => toggleAreaOfStudySelection(item)}
                />
              </Button>
            ))}
          </Stack>
        ) : (
          ""
        )}
        {error ? <Typography color="error">{error}</Typography> : ""}
      </Box>
      <Grid
        container
        sx={{
          display: "flex",
          flexDirection: "row",
          flexWrap: "wrap",
          width: "80%",
          height: "50vh",
          overflow: "scroll",
        }}
        spacing={2}
      >
        {subDisciplines?.map((course: any, index) => {
          return (
            <>
              <Grid
                item
                md={4}
                sm={6}
                xs={12}
                key={index}
                onClick={() => toggleAreaOfStudySelection(course)}
              >
                <Box
                  sx={
                    selectedAreaOfStudy.includes(course)
                      ? {
                        cursor: "pointer",
                        display: "flex",
                        alignItems: "center",
                        border: "1px solid #3B3F76",
                        borderRadius: "10px",
                        p: 0.5,
                        background: "#F4F4FF",
                      }
                      : {
                        cursor: "pointer",
                        display: "flex",
                        alignItems: "center",
                        border: "1px solid #3B3F76",
                        borderRadius: "10px",
                        p: 0.5,
                        "&:hover": {
                          background: "#F4F4FF",
                          borderRadius: "10px",
                        },
                      }
                  }
                >
                  {selectedAreaOfStudy.includes(course) ? (
                    <img
                      style={{
                        cursor: "pointer",
                        width: "35px",
                        height: "35px",
                        marginRight: "15px",
                      }}
                      src={Images.selected}
                      alt="selected"
                      onClick={() => toggleAreaOfStudySelection(course)}
                    />
                  ) : (
                    <Box component="img"
                      sx={{
                        cursor: "pointer",
                        width: "35px",
                        height: "35px",
                        marginRight: "15px",
                        "&:hover": {
                        },
                      }}
                      src={Images.degreeIcon}
                      alt="loginImage"
                    />
                  )}

                  <p
                    style={{
                      fontFamily: "poppins",
                      fontSize: "16px",
                      fontWeight: "500", margin: 0
                    }}
                  >
                    {course}
                  </p>
                </Box>
              </Grid>
            </>
          );
        })}
      </Grid>

      <Stack
        direction="row"
        spacing={3}
        sx={{
          marginTop: "1%",
        }}
      >
        {currentIndex > 0 && (
          <Button sx={secondaryButton} onClick={handleBack}>
            Back
          </Button>
        )}
        <Button sx={secondaryButton} onClick={handleContinue}>
          {loading ? (
            <img
              src={Images.standardLoader}
              alt="load"
              style={{
                width: "20px",
                height: "20px",
                padding: "5px",
              }}
            />
          ) : (
            "Continue"
          )}
        </Button>
        {/* <Button sx={secondaryButton} onClick={handleSkip}>
                        {loading ? (
                                      <img
                                        src={Images.standardLoader}
                                        alt="load"
                                        style={{
                                          width: "20px",
                                          height: "20px",
                                          padding: "5px",
                                        }}
                                      />
                                    ) : (
                                      "Skip"
                                    )}
                        </Button> */}
      </Stack>
    </>
  );
};

export default CourseDetails;
