import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { Box, Button, Typography, Grid, CardContent,} from "@mui/material";
import { testReadyStyles } from "src/components/styles/customStyles";
import Images from "src/assets";

interface TestOption {
  id: number;
  text: string;
  icon: string;
  color: string;
  bgcolor: string;
}
interface EnglishTestProps {
  title: JSX.Element;
  name: string;
}
const testOptions: TestOption[] = [
  { id: 1, text: "Taken", icon:Images.CheckboxRightTeal, color: "#75ECE5", bgcolor: "#70A6B2" },
  { id: 2, text: "Planning to take", icon:Images.SuitcasePurple, color: "#D1D3F9", bgcolor: "#AAAEFE" },
  { id: 3, text: "Not planning to take", icon:Images.CheckboxWrongRed, color: "#FFA89C", bgcolor: "#FF9784" },
];

const EnglishTest: React.FC <EnglishTestProps> = ({ title }) => {
  const navigate = useNavigate();
  const [dynamicTitle, setDynamicTitle] = useState<JSX.Element>(title);
  const [selectedTest, setSelectedTest] = useState<TestOption | null>(null);

  const setAcademicTest = (collectedData: boolean) => {
    let currentValue = localStorage.getItem("user-profile");
    let currentValueObj = currentValue ? JSON.parse(currentValue) : {};
  
    localStorage.setItem(
      "user-profile",
      JSON.stringify({
        ...currentValueObj,
        isPlanningToTakeAcademicTest: collectedData, // ✅ Stores this without removing education
        education: {
          ...currentValueObj.education, // ✅ Preserves existing education data
        },
      })
    );
  };


  const handleSelect = (test: TestOption): void => {
    setSelectedTest(test);
    setAcademicTest(test.id===3?false:true);
    let path = test.id === 1 ? "/teststatus"  : test.id === 2 ? "/teststatus1" : "/englishtest2";
    let name = test.id === 1 
      ? "Enter score" 
      : test.id === 2 
      ? "Enter expected score"
      : "publicationData";
    navigate(path,{ 
      state: { name }  // Passing dynamic name & value
    });
    if(test.id===2){
      setDynamicTitle(<Typography sx={{color:"#495052"}}><>Select the test you are <span style={{ color: "#F48438" }}>Planning to take?</span> </></Typography>)
    }else{
      setDynamicTitle(title)
    }
   
  };
  

  return (
    <Box
      sx={{
        marginTop:{xs:12,lg:4},
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        height: "100vh",
        textAlign: "center",
        px: { xs: 2, md: 4 },
      }}
    >
      <Typography
        variant="h3"
        sx={{
          fontWeight: 500,
          textAlign: "center",
          maxWidth: "90%",
          fontSize: { xs: "1.5rem", lg: "2rem" },
          mb: { xs: 6, lg: 6 },
        }}
      >
        {selectedTest?.id === 1
          ? 'What was your score in the test?'
          : selectedTest?.id === 2
            ? 'When are you planning to take the test?'
            : title}
      </Typography>

      <Grid marginBottom={25} container spacing={2} justifyContent="center">
        {testOptions.map((test) => (
          <Grid item xs={12} sm={6} md={4} lg={3} sx={{ display: "flex", justifyContent: "center" }} key={test.id}>
            <Typography
              role="button"
              aria-label={test.text}
              sx={{
                position: "relative",
                ...testReadyStyles.card2,
                marginTop:{xs:3,lg:4},
                borderLeft: `10px solid ${test.bgcolor}`,
                width: { xs: "70%", sm: "300px", md: "350px",lg:"450px" },
                textAlign: "center",
                padding: "15px",
                cursor: "pointer",
                backgroundColor: "#fff",
                transition: "0.3s ease-in-out",
            "&:hover": { boxShadow: `0px 8px 15px ${test.color}` },
              }}
              onClick={() => handleSelect(test)}
            >
              <CardContent sx={{ display: "flex", flexDirection: { xs: "row", sm: "column",lg:'column' }, justifyContent: "center", alignItems: "center", gap: 1 }}>
               <Box>
               <img src={test.icon} alt="icon" style={{ width: 36, height: 36 }} />
               </Box>
                <Typography variant="body1" fontSize={18} color="black">
                  {test.text}
                </Typography>
              </CardContent>
            </Typography>
          </Grid>
        ))}
      </Grid>

      <Box
        sx={{
          position: "absolute",
          bottom: 30,
          width: "100%",
          display: "flex",
          justifyContent: "center",
          mt: -3,
        }}
      >
        <Button variant="text" sx={{ color: "#888", fontSize: { xs: "14px", sm: "16px" } }} onClick={() => navigate(-1)}>
          ← Back
        </Button>
      </Box>
    </Box>
  );
};

export default EnglishTest;
