import React, { useRef, useState } from "react";
import {
  Typography,
  TextField,
  Grid,
  Stack,
  Button,
  Box,
} from "@mui/material";
import { useAppSelector, useAppDispatch } from "../../../../assets/hooks";
import {
  deleteUploadProfile,
  editProfile,
  uploadProfile,
} from "../../../../services";
import { settestScores } from "../../../../store/Slices/testScoresSlice";
import { closePopup, setPopup } from "../../../../store/Slices/popupSlice";
import FileUploadOutlinedIcon from "@mui/icons-material/FileUploadOutlined";
import { setDocuments } from "../../../../store/Slices/documentsSlice";
import Images from "../../../../assets";
import { Delete } from "@mui/icons-material";
import VisibilityOutlinedIcon from "@mui/icons-material/VisibilityOutlined";
import DatePickerComponent from "src/genericComponents/datePicker";
import { testScores } from "src/assets/menu";
import { secondaryButton } from "src/components/styles/customStyles";

interface Score {
  description: string;
  count: any;
}

interface Test {
  name: string;
  scores: Score[];
  testDate: Date;
  docId: any;
}

const EditPopup = (props: any) => {
  const data = props.data.data;
  const dispatch = useAppDispatch();
  const [editedScores, setEditedScores] = useState<Score[]>(data?.scores);
  const testscoresData = useAppSelector((state) => state.testscores);
  const inputFile = useRef<HTMLInputElement>(null);
  const [doc, setdoc] = useState<any>(data?.docId);
  const [tookTest, setTookTest] = useState<string>(
    data?.testDate ? data?.testDate?.slice(0, 10) : ""
  );
  const [loading, setLoading] = useState(false);
  const [load, setLoad] = useState(false);
  const [errors, setErrors] = useState<Record<number, string>>({});

  const selectedTest = testScores.find((test) => test.name === data.name);

  const validateScore = (index: number, value: number) => {
    if (!selectedTest) return "";
    const scoreRange = selectedTest.scores[0][index]?.range.split("-") || [];
    const min = parseInt(scoreRange[0], 10);
    const max = parseInt(scoreRange[1], 10);

    if (value < min || value > max) {
      return `Score must be between ${min} and ${max}`;
    }
    return "";
  };

  
  const imageClick = () => {
    inputFile?.current?.click();
  };

  const documentUpload = async (
    event: React.ChangeEvent<HTMLInputElement>,
    fieldPath: string
  ) => {
    setLoading(true)
    const file = event.target.files && event.target.files[0];
    if (fieldPath && file !== null && file !== undefined) {
      const formData = new FormData();
      formData.append("uploaded_file", file);
      formData.append("fieldPath", fieldPath);
      formData.append("fileIdentifier", `test${file.name}`);

      const response = await uploadProfile(formData);
      if (response) {
        dispatch(setDocuments(response.data.data.docs));
        // console.log(response.data.data.docs);
        let lastDoc;
        if (fieldPath === `test.general`) {
          lastDoc =
            response.data.data.docs.test.general[
            response.data.data.docs.test.general.length - 1
            ]
        } else {
          lastDoc =
            response.data.data.docs.test.languageProf[
            response.data.data.docs.test.languageProf.length - 1
            ]
        }

        setdoc(lastDoc);
        setLoading(false)
      }
    } else {
      setLoading(false)
    }
  };

  const handleDelete = async (fieldPath: string, deleteId: string) => {
    const response = await deleteUploadProfile({
      fieldPath: fieldPath,
      documentId: deleteId,
    });
    if (response) {
      dispatch(setDocuments(response.data.data));
      setdoc(null)
    } else {
    }
  };

  const handleScoreEdit = (index: number, newValue: number) => {
    const updatedScores = [...editedScores];
    updatedScores[index] = { ...updatedScores[index], count: newValue };
    setEditedScores(updatedScores);
    const errorMessage = validateScore(index, newValue);
    setErrors((prevErrors) => ({
      ...prevErrors,
      [index]: errorMessage,
    }));
  };

  const calculateTotal = (scores: Score[], method: string, requiredFields: string[]): number => {
    const requiredScores = scores.filter((score:any) =>
      requiredFields.includes(score.description) && score.count !== ""
    );
  
    if (method === "add") {
      return requiredScores.reduce((sum, score:any) => sum + parseFloat(score.count), 0);
    } else if (method === "average") {
      const sum = requiredScores.reduce((sum, score:any) => sum + parseFloat(score.count), 0);
      return sum / requiredScores.length || 0; 
    }
  
    return 0; 
  };
  
  const submit = async () => {
    if (Object.values(errors).some((error) => error)) return;
    const totalScore = calculateTotal(editedScores, selectedTest?.method || "add", selectedTest?.requiredFields || []);
    const updatedScores = [...editedScores];
    const totalIndex = updatedScores.findIndex((score) => score.description === "Total");
    if (totalIndex !== -1) {
      updatedScores[totalIndex] = { ...updatedScores[totalIndex], count: totalScore.toString() };
    } else {
      updatedScores.push({ description: "Total", count: totalScore.toString() });
    }
  
    const updatedData: Test = {
      ...data,
      scores: updatedScores,
      docId: doc?._id,
      testDate: tookTest,
    };
  
    const updatedTestscoresData = testscoresData.data.map((test) =>
      test.name === updatedData.name ? updatedData : test
    );
  
    setLoad(true);
    const response = await editProfile({ tests: updatedTestscoresData });
    if (response) {
      dispatch(settestScores(response.data.data.tests));
      dispatch(closePopup());
      setLoad(false);
    } else {
      setLoad(false);
    }
  };
  
  

  return (
    <div style={{ padding: "1rem" }}>
      <Stack direction="row" justifyContent="space-between" sx={{ mt: 2 }}>
        <Typography fontWeight="500">{data.name}</Typography>
      </Stack>
      <Grid container spacing={2}>
      {editedScores
          .filter((score) => score.description !== "Total") 
          .map((score, index) => (
          <Grid item xs={6} sm={4} key={index}>
            <Typography sx={{ fontSize: { xs: "13px", sm: "16px" } }}>
              {score.description}
            </Typography>
            <TextField
              variant="outlined"
              size="small"
              sx={{ color: "#989A9B" }}
              value={score.count || ""}
              onChange={(e) =>
                handleScoreEdit(index, parseInt(e.target.value) || 0)
              }
              error={!!errors[index]}
              helperText={errors[index] || ""}
            />
          </Grid>
        ))}
        <Grid item xs={6} sm={4} sx={{ position: "relative" }}>
          <Typography sx={{ fontSize: { xs: "13px", sm: "16px" } }}>
            Took test on
          </Typography>
          <DatePickerComponent
            selectedDate={tookTest}
            onChange={(date) =>
              setTookTest(date ? date.toISOString().slice(0, 10) : "")
            }
            maxDate={new Date()}
            placeholderText="Took test on"
          />
        </Grid>
        <Grid item xs={6} sm={4}>
          <Typography sx={{ fontSize: { xs: "13px", sm: "16px" } }}>
            Uploaded file
          </Typography>
          {doc !== null && doc !== undefined ? (
            <Box sx={{ display: "flex",alignItems:"center",gap:"4px" }}>
             
              {doc?.data?.originalname}
              <VisibilityOutlinedIcon sx={{ fontSize: "large",pt:0.5,cursor:"pointer" }} onClick={() => {
                dispatch(
                  setPopup({
                    show: true,
                    data: {
                      container: {
                        name: "fileViewer",
                        data: doc?.data?.preview_url,
                        dimensions: {
                          width: "500px",
                        },
                      },
                      type: "custom",
                    },
                  })
                )
              }} />
              {/* </Link> */}
              <Delete
                sx={{ color: "#3b3f76", fontSize: "1.2rem", ml: 2 }}
                onClick={() => handleDelete(props.data.name, doc._id)}
              />
            </Box>
          ) : (
            <>
              <input
                style={{ display: "none" }}
                type="file"
                className=""
                name="docId"
                onChange={(event) => documentUpload(event, props.data.name)}
                ref={inputFile}
                accept=".pdf,.jpeg,.png"
              />
              <Button
                sx={{
                  color: "#000",
                  textTransform: "none",
                  // p: 0,
                  fontSize: "0.7rem",
                  marginLeft: "-10px",
                }}
                onClick={imageClick}

              >
                {loading ? <img src={Images.standardLoader} alt="loader" style={{ width: "1rem" }} /> :
                  <FileUploadOutlinedIcon />
                }
              </Button>
            </>
          )}
        </Grid>
      </Grid>
      <Button
        type="submit"
        sx={[secondaryButton, { mt: 2 }]}
        onClick={submit}
        disabled={Object.values(errors).some((error) => error)}
      >
        {load ? (
          <Box
            component="img"
            src={Images.standardLoader}
            alt="standardLoader"
            sx={{ width: "1.25rem", height: "1.25rem" }}
          />
        ) : (
          "Save"
        )}
      </Button>
    </div>
  );
};

export default EditPopup;
