import { Box, Button, Grid, Typography } from '@mui/material'
import React, { useContext } from 'react'
import ArrowForwardIcon from '@mui/icons-material/ArrowForward';
import { SuggestedPackage } from '../../../../types/types';
// import DeleteOutlineIcon from '@mui/icons-material/DeleteOutline';
import { useAppSelector } from '../../../../assets/hooks';
import { setWordCase } from '../../../../assets/library';
import { DestinationTypeEnum } from '../../../../assets/enums';
import Context from 'src/assets/constants/context';

const Packages = (props: any) => {
  const suggestedPackages = useAppSelector(store => store.suggestedPackages)
  const { selectedPackage, setSelectedPackage } = useContext(Context);
  const purchasedPackages = useAppSelector(store => store.purchasedPackages);
  const handlePackageClick = (packageId: string) => {
    const newSelectedPackage = selectedPackage === packageId ? undefined : packageId;
    setSelectedPackage(newSelectedPackage);
  };

  const fullToShort: Record<string, string> = Object.fromEntries(
    Object.entries(DestinationTypeEnum).map(([key, value]) => [value, key])
  );
  return (
    <div>
      <Box sx={{ mb: 2, overflowY: 'scroll' }}>
        <Typography sx={{ fontSize: "1.5rem", color: "#3B3F7680", display: "flex", gap: "0.5rem", alignItems: "center", fontWeight: "600" }}>
          <p style={{ background: "#3B3F76", width: "1rem", height: "1rem", margin: 0, borderRadius: "50%" }}></p>
          Packages</Typography>
        <Box
          sx={{
            overflowX: 'auto',
            whiteSpace: 'nowrap',
            padding: '0 1rem',
            scrollbarWidth: 'none',
            '&::-webkit-scrollbar': {
              display: 'none',
            },
          }}
        >
          <Grid container spacing={3} sx={{
            flexWrap: 'nowrap',
            alignItems: 'center',
            width: "100%",
            '&::-webkit-scrollbar': {
              width: '12px',
              backgroundColor: '#fff',
            },
            '&::-webkit-scrollbar-thumb': {
              backgroundColor: '#fff',
              borderRadius: '8px',
            },
            '&::-webkit-scrollbar-track': {
              backgroundColor: '#fff',
            },
            minHeight: "430px", maxHeight: "500px", overflowY: "scroll"
          }}>
            {suggestedPackages?.data?.length > 0 ? (
              suggestedPackages?.data
                .filter(
                  (item: SuggestedPackage) =>
                    !purchasedPackages.data.some(
                      (purchasedPackage: any) => purchasedPackage._id === item?._id
                    )
                )
                .map((item: SuggestedPackage, i: number) => (
                  <Grid
                    key={i}
                    item
                    xs={12}
                    sm={6}
                    md={4}
                    lg={3}
                    sx={{ textWrap: "wrap" }}
                  >
                    <Box
                      sx={{
                        background: selectedPackage === item._id ? "#1C1F40" : "#D1D3F933",
                        borderRadius: "15px",
                        p: 2,
                        position: "relative",
                      }}
                      onClick={() => handlePackageClick(item._id)}
                    >
                      <Typography
                        sx={{
                          position: "relative",
                          width: "1.5rem",
                          height: "1.5rem",
                          borderRadius: "50%",
                          background: "#9CFFF9",
                        }}
                      >
                        <Typography
                          sx={{
                            position: "absolute",
                            top: "-4px",
                            left: "14px",
                            width: "200px",
                            color: selectedPackage === item._id ? "#fff" : "#000",
                          }}
                          fontWeight="500"
                          fontSize="1rem"
                        >
                          {item?.name}
                        </Typography>
                      </Typography>
                      {item?.priceDetails?.totalPrice === 0 ? (
                        <Button
                          sx={{
                            width: "50px",
                            color: selectedPackage === item._id ? "#fff" : "#000",
                            background: "linear-gradient(90deg, #1976d2 0%, #b667c1 100%)",
                            fontWeight: "500",
                            fontSize: "11px",
                            textTransform: "none",
                            borderRadius: "15px",
                            padding: "0",
                            position: "absolute",
                            top: 0,
                            right: 0,
                          }}
                        >
                          Free
                        </Button>
                      ) : (
                        ""
                      )}
                      <ul
                        style={{
                          listStyleType: "disc",
                          color: selectedPackage === item._id ? "#fff" : "#000",
                          padding: "14px",
                          display: "flex",
                          flexDirection: "column",
                          gap: "0.5rem",
                          fontSize: "13px",
                          height: "120px",
                          marginTop: "1rem",
                        }}
                      >
                        <li>
                          {item?.country?.length} Countries (
                          {item?.country?.map((i) => fullToShort[i] + " / ")}{" "}
                          )
                        </li>
                        {item?.products?.map((product: any) => (
                          <li key={product?.category}>
                            {setWordCase(product?.category)} : {product?.quantity}
                          </li>
                        ))}
                      </ul>
                      <Typography
                        sx={{
                          color: selectedPackage === item._id ? "#fff" : "#000",
                        }}
                      >
                        Benefits
                      </Typography>
                      <ul
                        style={{
                          listStyleType: "disc",
                          color: selectedPackage === item._id ? "#fff" : "#000",
                          padding: "14px",
                          display: "flex",
                          flexDirection: "column",
                          gap: "0.5rem",
                          fontSize: "13px",
                          marginTop: "1rem",
                        }}
                      >
                        {item?.benefits?.map((benefit: any) => (
                          <li key={benefit}>{benefit}</li>
                        ))}
                      </ul>
                      {item?.requirements?.length > 0 && (
                        <>
                          <Typography
                            sx={{
                              color: selectedPackage === item._id ? "#fff" : "#000",
                            }}
                          >
                            Requirements
                          </Typography>
                          <ul
                            style={{
                              listStyleType: "disc",
                              color: selectedPackage === item._id ? "#fff" : "#000",
                              padding: "0 14px",
                              display: "flex",
                              flexDirection: "column",
                              gap: "0.5rem",
                              fontSize: "13px",
                              marginTop: "1rem",
                            }}
                          >
                            {item?.requirements?.map((requirement: any) => (
                              <li key={requirement}>{requirement}</li>
                            ))}
                          </ul>
                        </>
                      )}
                    </Box>
                  </Grid>
                ))
                .length === 0 ? (
                <Grid
                  item
                  xs={12}
                  sx={{
                    height: "300px",
                    display: "flex",
                    justifyContent: "center",
                    alignItems: "center",
                  }}
                >
                  <Box>No packages are available</Box>
                </Grid>
              ) : (
                ""
              )
            ) : (
              <Grid
                item
                xs={12}
                sx={{
                  height: "300px",
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                }}
              >
                <Box>No packages are available</Box>
              </Grid>
            )}


          </Grid>
        </Box>
        <Button sx={{
          float: "right", borderRadius: "50%", minWidth: 0,
          background: "#3b3f76",
          height: "2.5rem",
          width: "2.5rem",
          color: "#fff",
          "&:hover": {
            background: "#3b3f76",
            color: "#fff",
          }
        }}
          onClick={() => props.setActiveTab("Products")}

        >
          <ArrowForwardIcon />
        </Button>
      </Box>
    </div>
  )
}

export default Packages