const setDiscipline=(collectedData:{discipline:string[]})=>{
  let currentValue=localStorage.getItem("user-profile");
    let currentValueObj=currentValue?JSON.parse(currentValue):{}
    if(currentValueObj)
    {
      let updatedCourses=currentValueObj.preference?{...currentValueObj,preference:{...currentValueObj.preference,subCategory:collectedData.discipline}}:{...currentValueObj,preference:{subCategory:collectedData.discipline}}
      localStorage.setItem("user-profile",JSON.stringify(updatedCourses));	
    }
}

const allCourses: Course[] = [
  ...importantCoursesList,
  ...courseList.map((name, index) => ({
    id: importantCoursesList.length + index + 1,
    name,
    color: "#888",
    bgcolor: "#eee",
  })),
];

// Create a map for quick course lookup by name, prioritizing important courses
const courseMap = new Map<string, Course>();
// First add important courses (colorful ones)
importantCoursesList.forEach(course => {
  courseMap.set(course.name, course);
});
// Then add regular courses, but don't override important ones
allCourses.forEach(course => {
  if (!courseMap.has(course.name)) {
    courseMap.set(course.name, course);
  }
});

const CourseSelection: React.FC = () => {
  const [selectedCourses, setSelectedCourses] = useState<Course[]>([]);
  const [searchTerm, setSearchTerm] = useState<string>("");
  const navigate = useNavigate();

  
  const filteredCourses =
   searchTerm.trim() === ""
    ? importantCoursesList // Show only important courses when no search
    : allCourses.filter((course) =>
        course.name.toLowerCase().includes(searchTerm.toLowerCase())
      );

      useEffect(() => {
        const userProfile = localStorage.getItem("user-profile");
        if (userProfile) {
          const parsedProfile = JSON.parse(userProfile);
          const selectedCourseNames: string[] = parsedProfile?.preference?.subCategory || [];
      
          const matchedCourses = selectedCourseNames
            .map(name => courseMap.get(name))
            .filter((course): course is Course => course !== undefined);
      
          setSelectedCourses(matchedCourses);
        }
      }, [courseMap]);
      


  // Filter courses based on search input
  // const filteredCourses = importantCoursesList.filter((course) =>
  //   course.name.toLowerCase().includes(searchTerm.toLowerCase())
  // );

  // Handle selection
  const handleSelect = (course: Course) => {
    const isAlreadySelected = selectedCourses.some((c) => c.id === course.id);
    
    if (isAlreadySelected) {
      // Remove course if already selected
      const updatedSelectedCourses = selectedCourses.filter((c) => c.id !== course.id);
      setSelectedCourses(updatedSelectedCourses);
      setDiscipline({discipline: updatedSelectedCourses.map((item) => item.name)});
    } else {
      // Add new course
      const updatedSelectedCourses = [...selectedCourses, course];
      setSelectedCourses(updatedSelectedCourses);
      setDiscipline({discipline: updatedSelectedCourses.map((item) => item.name)});
    }
  };

  // Remove selected course
  const handleRemoveCourse = (courseId: number) => {
    const updatedSelectedCourses = selectedCourses.filter((c) => c.id !== courseId);
    setSelectedCourses(updatedSelectedCourses);
    setDiscipline({discipline: updatedSelectedCourses.map((item) => item.name)});
  };

  // Handle Continue
  const handleContinue = (): void => {
    navigate("/destination");
  };

  return (
    <Box sx={{ textAlign: "center", p: 3, marginTop: "80px", minHeight: "100vh", pb: 12 }}>
      <Typography variant="h4" fontWeight="bold" mb={3} sx={{ fontSize: { xs: "1.5rem", lg: "2rem",color:"#495052" } }}>
        Which subject or program are you <span style={{ color: "#F48438" }}>interested to study?</span>
      </Typography>

      {/* Search Field */}
      <TextField
        fullWidth
        placeholder="Search by course"
        variant="outlined"
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
        sx={{
          
          maxWidth: "400px",
          mb: 3,
          "& .MuiOutlinedInput-root": {
            borderRadius: "12px",
            "& fieldset": { borderLeft: "10px solid #70A6B2" },height:{xs:40,md:50,lg:60},
          },
        }}
        InputProps={{
          startAdornment: (
            <InputAdornment  position="start">
              <SearchIcon />
            </InputAdornment>
          ),
        }}
      />

      {/* Selected Courses Display */}
      <Box sx={{ display: "flex", gap: 1, flexWrap: "wrap", mb: 3 }}>
        {selectedCourses.map((course) => (
          <Chip
            key={course.id}
            label={course.name}
            onDelete={() => handleRemoveCourse(course.id)}
            sx={{ backgroundColor: course.color, color: "#fff", fontWeight: "bold" }}
          />
        ))}
      </Box>

      {/* Course List */}
      <Box sx={{
        maxHeight: { xs: 'calc(100vh - 80px)', sm: 'calc(100vh - 100px)' },
        overflowX: { xs: 'auto', lg: 'unset' },
        overflowY: 'auto',
        pb: 20
      }}>
        <Grid container spacing={2} justifyContent="center">
        {filteredCourses.map((course) => (
          <Grid item xs={12} sm={6} md={3} lg={3} key={course.id}>
            <Typography
              role="button"
              aria-label={course.name}
              sx={{
                position: "relative",
                ...testReadyStyles.card2,
                borderLeft: `10px solid ${course.bgcolor}`,
                height: "auto",
                width: "90%",
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
                // padding: "10px 15px",
                borderRadius: "12px",
                cursor: "pointer",
                backgroundColor: selectedCourses.some((c) => c.id === course.id) ? "#F4F4FF" : "#fff",
                "&:hover": { backgroundColor: "#F4F4FF" },
              }}
              onClick={() => handleSelect(course)}
            >
              <Box sx={{ width: "8px", height: "100%", borderRadius: "8px" }} />
              <Typography sx={{ flex: 1, ml: 2 }}>{course.name}</Typography>
            </Typography>
          </Grid>
        ))}
      </Grid>
      </Box>
      

      {/* Navigation Buttons */}
      <Box sx={{ 
        position: "fixed", 
        bottom: 0, 
        left: 0, 
        right: 0, 
        backgroundColor: "#fff", 
        borderTop: "1px solid #eee",
        py: 3,
        display: "flex", 
        justifyContent: "center", 
        gap: 2,
        zIndex: 1000
      }}>
        <Button variant="text" sx={{ color: "#888" }} onClick={() => navigate(-1)}>
          ← Back
        </Button>
        <Button variant="contained" disabled={selectedCourses.length === 0} sx={{ px: 4, py: 1.5, borderRadius: "20px",opacity: selectedCourses.length === 0 ? 0.6 : 1,background:"#F48438",color:"#FFFF", "&:hover": {
      backgroundColor: "#d96f2e",
    }, }} onClick={handleContinue}>
          Continue
        </Button>
      </Box>
    </Box>
  );
};

export default CourseSelection;
