import { Box, Button, MenuItem, Select, Typography } from "@mui/material";
import { Form, Formik } from "formik";
import * as Yup from "yup";
import React, { useRef, useState } from "react";
import ExpandMoreIcon from "@mui/icons-material/ExpandMore";
import { globalButton } from "src/components/styles/customStyles";
import FileUploadOutlinedIcon from "@mui/icons-material/FileUploadOutlined";
import { iehVerification } from "src/services";
import { useAppDispatch } from "src/assets/hooks";
import { setPopup } from "src/store/Slices/popupSlice";

// Validation schema
const validationSchema = Yup.object().shape({
    verificationDocName: Yup.string().required("Please select a document name"),
    uploaded_file: Yup.mixed().required("Please upload a document"),
});

const IEH = (data: any) => {
    const [file, setFile] = useState<File | any>();
    const inputFile = useRef<HTMLInputElement>(null);
const dispatch = useAppDispatch()
    const imageClick = () => {
        inputFile.current?.click();
    };

    const handleSubmit = async (values: any) => {
        const formData = new FormData();
        formData.append("uploaded_file", file);
        formData.append("verificationDocName", values.verificationDocName);
        formData.append("institutionId", values.institutionId);
        formData.append("fileIdentifier", values.verificationDocName);

        const response = await iehVerification(formData);
        if (response) {
            // console.log(response)
            data.data.setIEHStatus(response.data.data.IEH)
            dispatch(
                setPopup({
                  show: true,
                  data: {
                    container: {
                      name: "success",
                      data:response?.data?.data?.IEH?.verificationStatus,
                      dimensions: {
                        width: "40%",
                        height:"40%",
                        show:"none"

                      },
                    },
                    type: "custom",
                  },
                })
              )

        }
    }

    return (
        <div style={{padding:"2rem"}}>
            <Typography fontWeight="600" fontSize="1.1rem">
                Please fill the below fields for verification
            </Typography>
            <Formik
                initialValues={{
                    institutionId: data.data.id,
                    verificationDocName: "",
                    uploaded_file: null,
                }}
                validationSchema={validationSchema}
                enableReinitialize
                onSubmit={(values: any) => handleSubmit(values)}
            >
                {({ touched, errors, values, handleChange, setFieldValue }) => (
                    <Form style={{}}>
                        <Box sx={{ my: 2 }}>
                            <label
                                htmlFor="verificationDocName"
                                style={{
                                    marginRight: "0.8rem",
                                    fontWeight: "500",
                                }}
                            >
                                Select document
                            </label>
                            <Select
                                id="verificationDocName"
                                size="small"
                                name="verificationDocName"
                                displayEmpty
                                value={values.verificationDocName}
                                onChange={handleChange}
                                fullWidth
                                IconComponent={ExpandMoreIcon}
                                sx={{ mt: 1 }}
                                error={touched.verificationDocName && Boolean(errors.verificationDocName)}
                            >
                                <MenuItem disabled value="">
                                    Select
                                </MenuItem>
                                {["OD", "Marks sheet"].map((name) => (
                                    <MenuItem key={name} value={name}>
                                        {name}
                                    </MenuItem>
                                ))}
                            </Select>
                            {errors.verificationDocName && (
                                <Typography sx={{ color: "error.main", fontSize: "0.75rem", mt: 1 }}>
                                    {typeof errors.verificationDocName === 'string' ? errors.verificationDocName : ""}
                                </Typography>
                            )}
                        </Box>
                        <Box sx={{ display: "flex", flexDirection: "column", gap: "0.5rem" }}>
                            <label
                                htmlFor="uploaded_file"
                                style={{
                                    marginBottom: "0.3rem",
                                    marginRight: "0.8rem",
                                    fontWeight: "500",
                                }}
                            >
                                Upload document
                            </label>
                            <Box
                                sx={{ 
                                    display: "flex", 
                                    gap: "0.5rem", 
                                    cursor: "pointer", 
                                    border: "1px solid #3b3f76", 
                                    borderRadius: "20px", 
                                    width: "100px", 
                                    fontSize: "14px", 
                                    color: "#3b3f76", 
                                    alignItems: "center", 
                                    justifyContent: "center" 
                                }}
                                onClick={() => imageClick()}
                            >
                                Upload
                                <input
                                    style={{ display: "none" }}
                                    type="file"
                                    accept=".jpeg,.pdf,.png"
                                    name="uploaded_file"
                                    onChange={(e) => {
                                        const file = e.target.files?.[0];
                                        setFile(file);
                                        setFieldValue("uploaded_file", file); // Ensure Formik is aware of the uploaded file
                                    }}
                                    ref={inputFile}
                                />
                                <FileUploadOutlinedIcon
                                    sx={{ color: "#3b3f76" }}
                                />
                            </Box>

                            {file ? (
                                <Typography sx={{ my: 1 }}>
                                    File: <span style={{ color: "#C6C6C6" }}>{file?.name}</span>
                                </Typography>
                            ) : (
                                errors.uploaded_file && (
                                    <Typography sx={{ color: "error.main", fontSize: "0.75rem", mt: 1 }}>
                                        {typeof errors.uploaded_file === 'string' ? errors.uploaded_file : ""}
                                    </Typography>
                                )
                            )}
                        </Box>
                        <Box sx={{ display: "flex", justifyContent: "center", mt: 1 }}>
                            <Button type="submit" sx={[globalButton, { width: "100px" }]}>
                                Submit
                            </Button>
                        </Box>
                    </Form>
                )}
            </Formik>
        </div>
    );
};

export default IEH;
