import { Box, Button, TextField, Typography, FormHelperText } from "@mui/material";
import React, { useState } from "react";
import ReactPhoneInput from "react-phone-input-2";
import { Formik, Form, Field, ErrorMessage } from "formik";
import * as Yup from "yup";
import Images from "../../assets";
import { useAppSelector } from "../../assets/hooks";
import { callbackRSA } from "../../services";
import parsePhoneNumberFromString from "libphonenumber-js";

const CallBack: React.FC = () => {
  const sharedInfo = useAppSelector((state) => state.sharedInfo);
  const userStatus = useAppSelector((state) => state.userAuthStatus);
  const [loading, setLoading] = useState(false);
  const studentName = (sharedInfo?.data?.firstName
    ? sharedInfo?.data?.firstName
    : "User") +
    (sharedInfo?.data?.lastName
      ? " " + sharedInfo?.data?.lastName
      : "")
  const studentMail = sharedInfo?.data?.email;
  const initialPhone = {
    countryCode: userStatus.data.isAuthorized ? sharedInfo?.data?.phone?.countryCode : "",
    number: userStatus.data.isAuthorized ? sharedInfo?.data?.phone?.number : "",
  };

  const initialValues = {
    name: userStatus.data.isAuthorized ? studentName : "",
    email: userStatus.data.isAuthorized ? studentMail : "",
    phone: initialPhone,
  };

  const validationSchema = Yup.object({
    name: Yup.string().required("Name is required"),
    email: Yup.string().email("Invalid email format").required("Email is required"),
    phone: Yup.object({
      countryCode: Yup.string().required("Country code is required"),
      number: Yup.string()
        .required("Phone number is required")
        .test("is-valid-phone", "Invalid phone number", function (value) {
          const { countryCode } = this.parent;
          if (!countryCode || !value) return false; // Ensure both countryCode and number are provided

          try {
            const phoneNumber = parsePhoneNumberFromString(`${countryCode}${value}`, countryCode);
            return phoneNumber?.isValid();
          } catch (error) {
            return false;
          }
        }),
    }),
  });

  const handlePhoneChange = (value: string, data: any, setFieldValue: any) => {
    const code = value?.split(data?.dialCode);
    setFieldValue("phone", {
      countryCode: `+${data?.dialCode}`, 
      number: code[1] || "",
    });
  };

  const Submit = async (values: any, { setSubmitting }: any) => {
    const payload = {
      name: values.name,
      email: values.email,
      phone: values.phone,
      queryDescription: "scholarship",
      studentId: userStatus.data.isAuthorized ? sharedInfo.data?._id : "",
    };
    try {
      setLoading(true);
      // eslint-disable-next-line
      const response = await callbackRSA(payload);
      setLoading(false);
      setSubmitting(false);
    } catch (error) {
      setLoading(false);
      setSubmitting(false);
    }
  };

  return (
    <div style={{ padding: "1.5rem" }}>
      <Typography fontWeight="600" gutterBottom fontSize="18px">
        Enter your Contact details
      </Typography>
      <Typography gutterBottom fontSize="14px">
        Our Student Expert will get back to you as soon as possible.
      </Typography>

      <Formik
        initialValues={initialValues}
        validationSchema={validationSchema}
        onSubmit={Submit}
      >
        {({ setFieldValue, touched, errors }) => (
          <Form style={{ marginTop: "1rem" }}>
            <Box sx={{ mb: 2 }}>
              <Field
                as={TextField}
                variant="outlined"
                name="name"
                size="small"
                placeholder="Enter full name"
                fullWidth
                sx={{
                  backgroundColor: "#fff", "& .MuiFormHelperText-root.Mui-error": {
                    marginLeft: "0 !important"
                  }
                }}
                error={touched.name && Boolean(errors.name)}
                helperText={<ErrorMessage name="name" />}
              />
            </Box>

            <Box sx={{ mb: 2 }}>
              <Field
                as={TextField}
                variant="outlined"
                name="email"
                size="small"
                type="email"
                placeholder="Enter Email id"
                fullWidth
                sx={{
                  backgroundColor: "#fff", "& .MuiFormHelperText-root.Mui-error": {
                    marginLeft: "0 !important"
                  }
                }}
                error={touched.email && Boolean(errors.email)}
                helperText={<ErrorMessage name="email" component="span" />}
              />
            </Box>

            <Box sx={{ mb: 2 }}>
              <ReactPhoneInput
                value={`${initialPhone.countryCode}${initialPhone.number}`}
                onChange={(value, data) => handlePhoneChange(value, data, setFieldValue)}
                country="in"
                inputProps={{
                  name: "phone",
                  required: true,
                }}
                inputStyle={{
                  width: '100%',
                  height: '40px',
                  border: touched.phone?.number && errors.phone?.number
                    ? '1px solid red'
                    : '1px solid #ced4da',
                  backgroundColor: "#fff",
                }}
              />
              <FormHelperText error>
                <ErrorMessage name="phone.number" component="span" />
              </FormHelperText>
            </Box>

            <Box sx={{ mt: 3, display: "flex", justifyContent: "center" }}>
              <Button
                type="submit"
                sx={{
                  backgroundColor: "#3B3F76",
                  color: "#fff",
                  fontWeight: "500",
                  fontSize: "16px",
                  width: "150px",
                  textTransform: "none",
                  borderRadius: "5px",
                  padding: "3px",
                  "&:hover": {
                    backgroundColor: "#3B3F76",
                    color: "#fff",
                  },
                }}
              >
                {loading ? (
                  <Box
                    component="img"
                    src={Images.standardLoader}
                    alt="standardLoader"
                    sx={{ width: "1rem", height: "1rem" }}
                  />
                ) : (
                  "Continue"
                )}
              </Button>
            </Box>
          </Form>
        )}
      </Formik>
    </div>
  );
};

export default CallBack;
