import React, { useState, useEffect } from "react";
import CountryTab from "./country";
import CourseDetails from "./courseDetails";
import EnglishTest from "./englishTest";
import HighestLevelEduTab from "./highestLevelEdu";
import TestScores from "./testScores";
import Phone from "./phone";
import Email from "./email";
import Name from "./name";

const QASection = () => {

  const missingFieldsString: any = localStorage.getItem("missingFields")
  const missingFields = missingFieldsString ? JSON.parse(missingFieldsString) : [];
  const [qaTab, setQaTab] = useState(missingFields[0]);
  useEffect(() => {
    if (missingFields.length > 0 && !missingFields.includes(qaTab)) {
      setQaTab(missingFields[0]);
    }
    // eslint-disable-next-line
  }, [missingFields]);

  const renderTabContent = () => {
    switch (qaTab) {
      case "name":
        return <Name setQaTab={setQaTab} missingFields={missingFields} qaTab={qaTab} />;
      case "phone":
        return <Phone setQaTab={setQaTab} missingFields={missingFields} qaTab={qaTab} />;
      case "email":
        return <Email setQaTab={setQaTab} missingFields={missingFields} qaTab={qaTab} />;
      case "country":
        return <CountryTab setQaTab={setQaTab} missingFields={missingFields} qaTab={qaTab} />;
      case "coursePreference":
        return <CourseDetails setQaTab={setQaTab} missingFields={missingFields} qaTab={qaTab} />;
      case "education":
        return <HighestLevelEduTab setQaTab={setQaTab} missingFields={missingFields} qaTab={qaTab} />;
      case "tests":
        return <TestScores setQaTab={setQaTab} missingFields={missingFields} qaTab={qaTab} />;
      case "englishTest":
        return <EnglishTest setQaTab={setQaTab} missingFields={missingFields} qaTab={qaTab} />;

    }
  };

  return (
    <div style={{ height: "100%" }}>
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          height: "100%",
        }}
      >
        {renderTabContent()}
      </div>
    </div>
  );
};

export default QASection;
