import { PayloadAction, createSlice } from "@reduxjs/toolkit";
import { Otp, StoreItem } from "../../types/types";



let initialState: StoreItem<Otp> = {
  requestStatus: "not_initiated",
  responseStatus: "not_recieved",
  haveAnIssue: false,
  issue: "",
  data: {
    emailLoginOtp: {
      verified: false,
    },
    phoneLoginOtp: {
      verified: false,
    },
  },
};

export const VerificationsSlice = createSlice({
  name: "Verifications",
  initialState: initialState,
  reducers: {
    initVerification: (state, action: PayloadAction<StoreItem<Otp>>) => ({
      ...action.payload,
    }),
    setEmailVerificationStatus: (state, action: PayloadAction<boolean>) => {
      state.data.emailLoginOtp.verified = action.payload;
    },

    setPhoneVerificationStatus: (state, action: PayloadAction<{ verified: boolean; expiry: string }>) => {
      state.data.phoneLoginOtp.verified = action.payload.verified;
    },
    resetVerification: (state) => ({
      ...initialState,
    }),
  },
});

export const { initVerification, setEmailVerificationStatus, setPhoneVerificationStatus, resetVerification } = VerificationsSlice.actions;

export default VerificationsSlice.reducer;
