import React from "react";
import { useNavigate } from "react-router-dom";
import { Box, Button, Typography, Grid, CardContent } from "@mui/material";
import { testReadyStyles } from "src/components/styles/customStyles";
import Images from "src/assets";

// Define TypeScript interface for test objects
interface Test {
  id: number;
  text: string;
  icon: string;
  color: string;
  bgcolor: string;
  name:string
}

// Array of test options
const testOptions: Test[] = [
  { id: 1, text: "Taken", icon: Images.CheckboxRightTeal, color: "#75ECE5", bgcolor: "#70A6B2",name:'enter' },
  { id: 2, text: "Planning to take", icon: Images.SuitcasePurple, color: "#D1D3F9", bgcolor: "#AAAEFE",name:'enter expected' },
  { id: 3, text: "Not planning to take", icon:Images.CheckboxWrongRed, color:"#FFA89C", bgcolor: "#FF9784",name:'' },
];

// Define TypeScript interface for component props
interface TitleProps {
  title: React.ReactNode;
}

const navigationPaths: Record<number, string> = {
  1: "/teststatus3",
  2: "/teststatus4",
  3: "/publication",
};

const EnglishTest2: React.FC<TitleProps> = ({ title }) => {
  const navigate = useNavigate();

  const setLanguageTest = (collectedData: boolean) => {
    let currentValue = localStorage.getItem("user-profile");
    let currentValueObj = currentValue ? JSON.parse(currentValue) : {};
  
    localStorage.setItem(
      "user-profile",
      JSON.stringify({
        ...currentValueObj,
        isPlanningToTakeLanguageTest: collectedData, // ✅ Stores this without removing education
        education: {
          ...currentValueObj.education, // ✅ Preserves existing education data
        },
      })
    );
  };

  // Handle selection and navigation
  const handleSelect = (test: Test): void => {
    setLanguageTest(test.id===3?false:true);
    let name = test.id === 1 
    ? "Enter score" 
    : test.id === 2 
    ? "Enter expected score" 
    : "publicationData";
    
    navigate(navigationPaths[test.id], {
      state: { name,selectedTest: { id: test.id, text: test.text, color: test.color, bgcolor: test.bgcolor,name:test.name }},
    });
  };

  return (
    <Box
         sx={{
          marginTop:{xs:12,lg:4},
           display: "flex",
           flexDirection: "column",
           alignItems: "center",
           justifyContent: "center",
           height: "100vh",
           textAlign: "center",
           px: { xs: 2, md: 4 },
         }}
       >
         <Typography
           variant="h3"
           sx={{
             fontWeight: 500,
             textAlign: "center",
             maxWidth: "90%",
             fontSize: { xs: "1.5rem", lg: "2rem" },
             mb: { xs: 6, lg: 6 },
           }}
         >
          {title}
         </Typography>
   
         <Grid marginBottom={25} container spacing={2} justifyContent="center">
           {testOptions.map((test) => (
             <Grid item xs={12} sm={6} md={4} lg={3} sx={{ display: "flex", justifyContent: "center" }} key={test.id}>
               <Typography
                 role="button"
                 aria-label={test.text}
                 sx={{
                   position: "relative",
                   ...testReadyStyles.card2,
                   marginTop:{xs:3,lg:4},
                   borderLeft: `10px solid ${test.bgcolor}`,
                   width: { xs: "70%", sm: "300px", md: "350px" },
                   textAlign: "center",
                   padding: "15px",
                   cursor: "pointer",
                   backgroundColor: "#fff",
                   transition: "0.3s ease-in-out",
            "&:hover": { boxShadow: `0px 8px 15px ${test.color}` },
                 }}
                 onClick={() => handleSelect(test)}
               >
                 <CardContent sx={{ display: "flex", flexDirection: { xs: "row", sm: "column",lg:'column' }, alignItems: "center", gap: 1,textAlign:'center' }}>
                    <Box>
                    <img src={test.icon} alt="icon" style={{ width: 36, height: 36 }} />
                    </Box>
                   <Typography variant="body1" fontSize={18} color="black">
                     {test.text}
                   </Typography>
                 </CardContent>
               </Typography>
             </Grid>
           ))}
         </Grid>
   
         <Box
           sx={{
             position: "absolute",
             bottom: 30,
             width: "100%",
             display: "flex",
             justifyContent: "center",
             mt: -3,
           }}
         >
           <Button variant="text" sx={{ color: "#888", fontSize: { xs: "14px", sm: "16px" } }} onClick={() => navigate(-1)}>
             ← Back
           </Button>
         </Box>
       </Box>
  );
};

export default EnglishTest2;
