import { PayloadAction, createSlice } from "@reduxjs/toolkit";
import { Order, StoreItem } from "../../types/types";

let initialState:StoreItem<Order[]>={
    requestStatus:"not_initiated",
    responseStatus:"not_recieved",
    haveAnIssue:false,
    issue:"",
    data:[]
}

export const ordersSlice=createSlice({
    name:'shortlistedcourses',
    initialState:initialState,
    reducers:{
        initorders:(state,action:PayloadAction<StoreItem<Order[]>>)=>({...action.payload}),
        addorders:(state,action:PayloadAction<Order>)=>{state.data.push(action.payload)},
        updateorders:(state,action:PayloadAction<Order>)=>{
            let index=state.data.findIndex((item)=>item._id===action.payload._id);
            state.data[index]=action.payload;
        },
        setorders:(state,action:PayloadAction<Order[]>)=>{state.data=action.payload},
        removeorders:(state,action:PayloadAction<string>)=>{state.data=state.data.filter((item)=>item._id!==action.payload)},
        resetorders:(state,action:PayloadAction)=>({...initialState})

    }
})

export const {initorders,setorders,addorders,removeorders,updateorders,resetorders}=ordersSlice.actions;
export default ordersSlice.reducer;