import React, { lazy, Suspense, useState } from "react";
import { Routes, Route } from "react-router-dom";
import ProtectedRoute from "./protectedRoute";
import { useAppSelector } from "../assets/hooks";
import { FilterSelected } from "../types/types";
import Context from "../assets/constants/context";
import ScrollToTop from "../components/layouts/scrollToTop";
import Loader from "src/genericComponents/loader";
import { getComponent } from "src/assets/library";
import ExplorePop from "src/components/layouts/explorePop";
import ProfileLayout from "src/pages/profile/Profile";
import Footer from "src/components/layouts/footer";
import About from "src/pages/about/About";
import GetInTouch from "src/pages/about/getInTouch";
import UniversityMapPage from "src/pages/courses/UniversityMapPage";
import DestinationSelection from "../genericComponents/modalPopup/DestinationSelection";
import AcademicsStatus from "src/genericComponents/modalPopup/AcademicStatus";
import EnglishTest from "../genericComponents/modalPopup/EnglishTest";
import TestStatus from '../genericComponents/modalPopup/testStatus'
import Publication from "src/genericComponents/modalPopup/Publication";
import TestStatus2 from "src/genericComponents/modalPopup/testStatus2";
import TestSelection from "src/genericComponents/modalPopup/TestSelection";
import EnglishTest1 from "src/genericComponents/modalPopup/TestCondtion1";
import EnglishTest2 from "src/genericComponents/modalPopup/TestCondition2";
import TestCondtion1 from "src/genericComponents/modalPopup/TestCondtion1";
import TestCondtion2 from "src/genericComponents/modalPopup/TestCondition2";
import TestStatus3 from "src/genericComponents/modalPopup/TestStatus3";
import TestStatus4 from "src/genericComponents/modalPopup/TestStatus4";
import ResearchType from "src/genericComponents/modalPopup/ResearchType";
import ExperienceList from "src/genericComponents/modalPopup/WorkExperienceList";
import WorkExperienceList from "src/genericComponents/modalPopup/WorkExperienceList";
import StudyLevel from "src/genericComponents/modalPopup/StudyLevel";
import CourseSelection from "src/genericComponents/modalPopup/CourseSelection";
import WorkPlan from "src/genericComponents/modalPopup/WorkPlan";
import Budget from "src/genericComponents/modalPopup/Budget";
import Scholarship from "src/genericComponents/modalPopup/Scholarship";
import EducationLoan from "src/genericComponents/modalPopup/EducationLoan";
import Support from "src/genericComponents/modalPopup/Support";
import Personal from "src/genericComponents/modalPopup/Personal";
import Services from "src/genericComponents/modalPopup/Services";
import UniversityMatch from "src/genericComponents/modalPopup/Advertisement1";
import ExclusiveOffer from "src/genericComponents/modalPopup/Advertisement2";
import CareerSupport from "src/genericComponents/modalPopup/Advertisement3";
import FinancialAssistance from "src/genericComponents/modalPopup/Advertisement4";
import Congratulations from "src/genericComponents/modalPopup/Advertisement5";
import PrivacyPolicyCampusRoot from "../pages/policies/privacyPolicyCampusRoot";
import StudentAdvisorSupport from "src/genericComponents/modalPopup/StudentAdvisorSupport";


// import UniversityMapPage from "src/pages/courses/UniversityMapPage";

const Header = lazy(() => import("../components/layouts/header"));
const Chat = lazy(() => import("../pages/chats/chat"));
const Home = lazy(() => import("../pages/home/Home"));
const Recommendations = lazy(() => import("../pages/Recommendations"));
const CustomModal = lazy(() => import("../genericComponents/modalPopup/customModal"));
const PdfPreview = lazy(() => import("../pages/profile/section/documents/pdfView"));
const University = lazy(() => import("../pages/university"));
const NotFound = lazy(() => import("../components/layouts/notfound"));
const EmailVerification = lazy(() => import("../pages/emailVerification"));
const PrivacyPolicy = lazy(() => import("../pages/policies/privacyPolicy"));
const Disclaimer = lazy(() => import("../pages/policies/disclaimer"));
const TermsAndConditions = lazy(() => import("../pages/policies/termsConditions"));
const RefundPolicy = lazy(() => import("../pages/policies/refundPolicy"));
const Blog = lazy(() => import("../pages/blogs/Blog"));
const ViewBlog = lazy(() => import("../pages/blogs/ViewBlog"));
const Country = lazy(() => import("../pages/countries/Country"));
const AllCountries = lazy(() => import("../pages/countries/allCountries"));
const Explore = lazy(() => import("../pages/explore"));
const SingleCoursePage = lazy(() => import("../pages/explore/singleCoursePage"));
const SingleUniversityPage = lazy(() => import("../pages/explore/singleUniversityPage"));
const Destinations = lazy(() => import("../pages/explore/destinations"));
const CookiesPopup = lazy(() => import("./cookies"));
const Quiz = lazy(()=>import('../pages/profileinfo/Quiz'))
// const CareerGoals=lazy(()=>import('../genericComponents/modalPopup/CareerGoals'))
const CareerResult=lazy(()=>import('../genericComponents/modalPopup/DestinationSelection'))
const AcademicScore=lazy(()=>import('../genericComponents/modalPopup/AcademicScore'))
// const UniversityMapPage=lazy(()=>import('../pages/courses/UniversityMapPage'))

function Routing() {
  const [appliedFilter, setAppliedFilter] = useState<FilterSelected[]>([]);
  const [selectedUniversities, setSelectedUniversities] = useState([]);
  const [activeTab, setActiveTab] = useState("Packages");
  const [selectedPackage, setSelectedPackage] = useState<string | undefined>();
  const [summary, setSummary] = useState([]);
  const [explore, setExplore] = useState(true);
  const [courses, setCourses] = useState();

  const popup = useAppSelector((state) => state.popup);

  const PopupComponent: React.FC<{ data: any; link: any; eventHandler: any }> | null =
    popup.data.show && popup.data.data?.container?.name
      ? getComponent(popup?.data?.data?.container?.name)
      : null;

  return (
    <Suspense fallback={<Loader />}>
      <Context.Provider
        value={{
          selectedUniversities,
          setSelectedUniversities,
          activeTab,
          setActiveTab,
          selectedPackage,
          setSelectedPackage,
          courses,
          setCourses,
          summary,
          setSummary,
          explore,
          setExplore,
        }}
      >
        <ScrollToTop />
        <Header appliedFilter={appliedFilter} setAppliedFilter={setAppliedFilter} />
        {/* <UniversityMapPage/> */}
        {/* <Hello/> */}
        <Chat />
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/pop" element={<ExplorePop />} />

          <Route path="/pdfPreview" element={<PdfPreview />} />
          <Route path="/recommendations" element={<Recommendations />} />
          {/* <Route path="/careergoal" element={<CareerGoals/>}/> */}
          <Route path="/destination" element={<DestinationSelection/>}/>
          <Route path='/academicsstatus' element={<AcademicsStatus/>}/>
          <Route path='/academicscore' element={<AcademicScore/>}/>
          <Route path='/teststatus' element={<TestStatus/>}/>
          <Route path='/teststatus1' element={<TestStatus2/>}/>
          <Route path='/teststatus3' element={<TestStatus3/>}/>
          <Route path='/teststatus4' element={<TestStatus4/>}/>
          <Route path='/testcondition1' element={<TestCondtion1/>}/>
          <Route path='/testcondtion2' element={<TestCondtion2/>}/>
          <Route path='/englishtest2' element={<EnglishTest2/>}/>
         <Route path="/publication" element={<Publication/>}/>
         <Route path="/workexperience" element={<WorkExperienceList/>}/>
         <Route path="/researchtype" element={<ResearchType/>}/>
         <Route path="/studylevel" element={<StudyLevel/>}/>
         <Route path="/programselect" element={<CourseSelection/>}/>
         <Route path="/workplan" element={<WorkPlan/>}/>
         <Route path="/budget" element={<Budget/>}/>
         <Route path='/scholarship' element={<Scholarship/>}/>
         <Route path='/educationloan' element={<EducationLoan/>}/>
         <Route path='/support' element={<Support/>}/>
         <Route path='/personalDetails' element={<Personal/>}/>
         <Route path='/services' element={<Services/>}/>
         <Route path='/startpage' element={<UniversityMatch/>}/>
         <Route path='/offer' element={<ExclusiveOffer/>}/>
         <Route path='/careersupport' element={<CareerSupport/>}/>
         <Route path='/financialassistance' element={<FinancialAssistance/>}/>
         <Route path='/congratulations' element={<Congratulations/>}/>
         <Route path='/studentAdvisorSupport' element={<StudentAdvisorSupport/>}/>


          <Route
            path="/explore"
            element={<Explore appliedFilter={appliedFilter} setAppliedFilter={setAppliedFilter} />}
          />
          <Route path="/university/:name/:id" element={<University />} />
          <Route path="/singlecourse/:id" element={<SingleCoursePage />} />
          <Route path="/singleuniversity/:id" element={<SingleUniversityPage />} />
          <Route path="/destinations" element={<Destinations />} />
          <Route path="/blogs" element={<Blog />} />
          <Route path="/country/:id" element={<Country />} />
          <Route path="/countries" element={<AllCountries />} />
          <Route path="/blog/:id" element={<ViewBlog />} />
          <Route element={<ProtectedRoute link={"/"} />}>
            <Route path="/profile/*" element={<ProfileLayout />} />
          </Route>
          <Route path="*" element={<NotFound />} />
          <Route path="/privacyPolicy" element={<PrivacyPolicy />} />
          <Route path="/aboutus" element={<About />} />
          <Route path="/getInTouch" element={<GetInTouch />} />
          <Route path="/refundPolicy" element={<RefundPolicy />} />
          <Route path="/disclaimer" element={<Disclaimer />} />
          <Route path="/termsConditions" element={<TermsAndConditions />} />
          <Route path="/email-verification" element={<EmailVerification />} />
          <Route path="/privacy-policy" element={<PrivacyPolicyCampusRoot />} />
        </Routes>
        <Footer />
        <CustomModal
          open={popup.data.show}
          additionalData={{
            width: popup.data.data?.container?.dimensions?.width,
            height: popup.data.data?.container?.dimensions?.height,
            show: popup.data.data?.container?.dimensions?.show,
            close: popup.data.data?.container?.dimensions?.close,
          }}
        >
          {PopupComponent ? (
            <PopupComponent
              data={popup.data.data?.container?.data}
              link={popup.data.data?.container?.link}
              eventHandler={popup.data.data?.eventHandler}
            />
          ) : null}
        </CustomModal>
        <CookiesPopup />
      </Context.Provider>
    </Suspense>
  );
}

export default Routing;
