import { useEffect } from 'react';
import { useLocation } from 'react-router-dom';

function ScrollToTop() {
  const { pathname } = useLocation();

  useEffect(() => {
    // Check for stored scroll position with a delay to ensure it's available
    setTimeout(() => {
      const savedScrollPosition = localStorage.getItem('exploreScrollPosition');
      if (pathname === '/explore' && savedScrollPosition) {
        console.log('ScrollToTop: Skipping scroll to top on explore page due to stored scroll position:', savedScrollPosition);
        return;
      }
      
      console.log('ScrollToTop: Scrolling to top for pathname:', pathname);
      window.scrollTo(0, 0);
    }, 50);
  }, [pathname]);

  return null;
}

export default ScrollToTop;
