export const Universities = (props: any) => {
  const navigate = useNavigate();
  const preference = useAppSelector((state) => state.preferences);
  const currency = localStorage.getItem("currency");
  const [universityData, setuniversityData] = useState([]);
  const [loading, setLoading] = useState(true);

  const universities = async (activeTab: string) => {
    setLoading(true);
    const response = await getAlllistings("universities", {
      page: 1,
      currency: preference.data?.currency
        ? preference.data.currency
        : currency
        ? currency
        : "INR",
      filterData: [{ type: "country", data: [activeTab] }],
    });

    if (response) {
      setuniversityData(response.data.list);
    }
    setLoading(false);
  };

  useEffect(() => {
    universities(props.activeCountry);
    // eslint-disable-next-line
  }, [props.activeCountry]);

  return (
    <Box sx={{ position: 'relative', padding: { xl: "1rem 7rem 0 7rem", xs: "1rem" } }}>
      <Box sx={{ padding: '1rem' }}>
        <Typography
          color="#00000080"
          fontWeight="500"
          fontSize="1.2rem"
          sx={{ textAlign: 'center', mb: 3 }}
        >
          TOP UNIVERSITIES 
        </Typography>

        <Grid container spacing={2}>
          {loading ? (
            [...Array(9)].map((_, i) => (
              <Grid item xs={12} sm={6} md={4} key={i}>
                <Skeleton height={60} sx={{ mb: 2, bgcolor: '#f5f2f2' }} />
              </Grid>
            ))
          ) : (
            (universityData || []).slice(0, 9).map((item: any, i: number) => (
              <Grid item xs={12} sm={6} md={4} key={i}>
                <Box
                  sx={{
                    borderLeft: `10px solid ${item.bgcolor || '#3b3f76'}`,
                    border: '1px solid black',
                    borderRadius: '12px',
                    padding: '10px',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    gap: 1,
                    cursor: 'pointer',
                    backgroundColor: '#fff',
                    color: 'black',
                    "&:hover": { backgroundColor: "#F4F4FF" },
                    flexWrap: 'nowrap',
                    minHeight: '40px',
                    width: '200px',
                  }}
                >
                  <Box
                    sx={{
                      display: 'flex',
                      alignItems: 'center',
                      overflow: 'hidden',
                      flexGrow: 1,
                      gap: 1,
                      minWidth: 0,
                    }}
                  >
                    <Box
                      component="img"
                      src={item?.logoSrc}
                      alt={item.name}
                      sx={{ width: 24, height: 24, borderRadius: '50%' }}
                    />
                    <Typography
                      sx={{
                        fontSize: '14px',
                        whiteSpace: 'nowrap',
                        overflow: 'hidden',
                        textOverflow: 'ellipsis',
                      }}
                      title={item?.name}
                    >
                      {item?.name}
                    </Typography>
                  </Box>
                  <Box
                    component="img"
                    src={Images.arrow}
                    alt="arrow"
                    onClick={() => {
                      props.setopen(null);
                      navigate(`/singleuniversity/${item?._id}`);
                    }}
                    sx={{
                      width: 22,
                      height: 22,
                      flexShrink: 0,
                      ml: 1,
                    }}
                  />
                </Box>
              </Grid>
            ))
          )}
        </Grid>

        <Box sx={{ textAlign: "center", mt: 2 }}>
          <Button
            sx={[globalButton, { width: { md: "100px", xs: "80px" } }]}
            onClick={() => {
              props.setopen(null);
              const subDisUrl = `activeTab=${JSON.stringify("universities")}&FilterData=${JSON.stringify([
                {
                  type: "country",
                  data: [{ name: props.activeCountry, value: props.activeCountry }],
                },
              ])}&page=${JSON.stringify(1)}&search=${JSON.stringify("")}`;
              const subDisciUrl = window.btoa(subDisUrl);
              navigate(`/explore?${subDisciUrl}`);
            }}
          >
            View all
          </Button>
        </Box>

        <Box
          component="img"
          src={Images.flight}
          alt="flight"
          sx={{
            width: "50px",
            position: "absolute",
            top: 50,
            right: 5,
            display: { xs: "none", md: "block" },
          }}
        />
      </Box>
    </Box>
  );
};

export default Explorepopup
