import React, { useState } from "react";
import { Box, Typography, TextField, Button } from "@mui/material";
import StarOutlineIcon from "@mui/icons-material/StarOutline";
import Rating from "@mui/material/Rating";
import { postReview } from "../../services";
import Images from "../../assets";
import { Event } from "../../types/types";
import { addReviews } from "../../store/Slices/reviewSlice";
import { useAppDispatch } from "../../assets/hooks";
import { closePopup } from "src/store/Slices/popupSlice";

const RatingComponent = (props:any) => {
  // console.log(props)
  const dispatch = useAppDispatch();
  const [rating, setRating] = useState(0);
  const [comment, setComment] = useState("");
  const [loading, setLoading] = useState(false);
  // const [error, setError] = useState("");

  const eventHandler = async (event: Event) => {
    switch (event.name) {
      case "ratingChange":
        setRating(event.data);
        break;
      case "commentChange":
        setComment(event.data.target.value);
        break;
    }
  };

  const handleSubmit = async (event: any) => {
    event.preventDefault();
    setLoading(true);
    try{

    const response = await postReview({
      universityId: props?.data,
      comment: comment,
      rating: rating,
    });
    if (response) {
      dispatch(addReviews(response.data));
    }
    setLoading(false);
    if(props?.setTabComponent){
    props.setTabComponent("tabs")
  }else{
    dispatch(closePopup())
  }
  }catch(err){
    setLoading(false);

  }

  };
  const isSubmitDisabled = rating === 0 || comment === "";
  return (
    <Box component="form" onSubmit={handleSubmit} sx={{p:3}}>
      <Typography fontWeight="600">
        Take a movement to evaluate and tell us what you think about this
        University
      </Typography>
      <Typography fontWeight="600" sx={{ my: 1 }}>
        Rating
      </Typography>
      <Box sx={{ display: "flex" }}>
        <Rating
          name="half-rating"
          value={rating}
          onChange={(e, newValue) =>
            eventHandler({ name: "ratingChange", data: newValue })
          }
          precision={0.5}
          emptyIcon={<StarOutlineIcon sx={{ color: "gray" }} />}
        />
        {rating !== null && <Box sx={{ ml: 2 }}>{rating}</Box>}
      </Box>
      <Typography fontWeight="600" sx={{ my: 1 }}>
        Comment
      </Typography>
      <TextField
        variant="outlined"
        placeholder="Add comment"
        value={comment}
        onChange={(e) => eventHandler({ name: "commentChange", data: e })}
        multiline
        required
        rows={4}
        sx={{ width: "100%" }}
      />
      <Button
        type="submit"
        variant="contained"
        sx={{
          mt: 2,
          float: "right",
          backgroundColor: "#3B3F76",
          color: "#fff",
          borderRadius: "6px",
          "&:hover": {
            backgroundColor: "#3B3F76", // Set the same color as the default background color
          },
          "&.Mui-disabled": { color: "#fff", background: "#c8c2c2" },
          textTransform:"none"
        }}
        disabled={isSubmitDisabled}
      >
        {loading ? (
          <Box
            component="img"
            src={Images.standardLoader}
            alt="standardLoader"
            sx={{ width: "1rem", height: "1rem" }}
          />
        ) : (
          "Continue"
        )}
      </Button>
    </Box>
  );
};

export default RatingComponent;
