import { ArrowBack } from '@mui/icons-material'
import { Box } from '@mui/material'
import React, { useState } from 'react'
import CourseDetailed from './courseDetailed'
import UniversityDetailed from './universityDetailed'

const MainPopup = (props:any) => {
    const [initialState,setInitialState] = useState<"course"|"university">("course")
  return (
    <div >
        {
            initialState === "course"?
            <CourseDetailed data={{ 
              data:props.data._id, 
              setInitialState: setInitialState, 
              icon: false 
            }}  /> : 
                         <Box sx={{ position: 'relative' }}>
                 <Box
                   sx={{
                     position: 'absolute',
                     top: '20px',
                     left: '8px',
                     zIndex: 10,
                     cursor: 'pointer',
                     display: 'flex',
                     alignItems: 'center',
                     justifyContent: 'center',
                     width: '28px',
                     height: '28px',
                     borderRadius: '50%',
                     backgroundColor: 'rgba(255, 255, 255, 0.8)',
                     '&:hover': {
                       backgroundColor: 'rgba(255, 255, 255, 1)',
                     },
                     transition: 'background-color 0.2s ease',
                     marginRight: '10px',
                   }}
                   onClick={() => setInitialState("course")}
                 >
                   <ArrowBack sx={{ fontSize: '18px', color: '#495052' }} />
                 </Box>
                 <UniversityDetailed data={props.data.university._id}/>
             </Box>
        }

    </div>
  )
}

export default MainPopup