import { Box, Button,  Typography } from "@mui/material";
import React from "react";
import { useAppDispatch } from "src/assets/hooks";
import { closePopup } from "src/store/Slices/popupSlice";
// import EastIcon from "@mui/icons-material/East";
import {  secondaryButton } from "src/components/styles/customStyles";
import Images from "src/assets";

const Error = ({ data, link, errorDetails }: any) => {
  const capitalizedText = data?.charAt(0)?.toUpperCase() + data?.slice(1);
  const dispatch = useAppDispatch();
  const isNetworkError = typeof data === 'string' && data.includes('Network Error');
  const isDev = process.env.NODE_ENV === 'development';

  return (
<Box sx={{ position: "relative", minHeight: "100px", display: "flex", flexDirection: "column", justifyContent: "center",p:2,alignItems:"center" }}>
  <img src={Images.errorMsg} alt="error" style={{height:"6rem",marginTop:"10px"}}/>
  <Typography color="#2C2F5C" sx={{fontSize:"2rem"}}>Oops!</Typography>
  <Typography color="#2C2F5C80">{capitalizedText}</Typography>
  {isNetworkError && (
    <Typography color="#2C2F5C80" sx={{ mt: 1, fontSize: '1rem' }}>
      Please check your internet connection, refresh the page, or try again later.<br/>
      If the problem persists, the server may be temporarily unavailable.
    </Typography>
  )}
  {isDev && errorDetails && (
    <Box sx={{ mt: 2, background: '#f8f8f8', p: 1, borderRadius: 1, fontSize: '0.85rem', color: '#a00' }}>
      <pre style={{ margin: 0 }}>{JSON.stringify(errorDetails, null, 2)}</pre>
    </Box>
  )}
  <Box sx={{ display: "flex", alignItems: "center", mt: 3 }}>
    <Button
      sx={[secondaryButton, { width: "50px", p: 0,fontWeight:"400" }]}
      onClick={() => {
        dispatch(closePopup());
      }}
    >
      Okay
    </Button>
  </Box>
</Box>

  );
};

export default Error;
