import React, { useRef, useState } from "react";
import { useNavigate } from "react-router-dom";
import { Box, Button, Typography, Grid, CardContent, TextField } from "@mui/material";
import { testReadyStyles } from "src/components/styles/customStyles";
import Images from "src/assets";

interface ExperienceOption {
  id: number;
  text: string;
  icon: string;
  color: string;
  bgcolor: string;
}

// Experience options
const EXPERIENCE_OPTIONS: ExperienceOption[] = [
  { id: 1, text: "Yes", icon:Images.CheckboxRightTeal, color: "#70A6B2", bgcolor: "#70A6B2"  },
  { id: 2, text: "No", icon:Images.CheckboxWrongRed, color: "#FF9784", bgcolor: "#FF9784" },
];

// Reusable SelectionCard Component
const SelectionCard: React.FC<{ option: ExperienceOption; selected: boolean; onSelect: () => void }> = ({
  option,
  selected,
  onSelect,
}) => {
  return (
    <Grid item xs={12} sm={6} md={4} lg={3} sx={{ display: "flex", justifyContent: "center" }}>
      <Typography
        role="button"
        aria-label={option.text}
        sx={{
          position: "relative",
          ...testReadyStyles.card2,
          borderLeft: `10px solid ${option.bgcolor}`,
          width: { xs: "70%", sm: "300px", md: "350px" },
          textAlign: "center",
          padding: "15px",
          cursor: "pointer",
          background: selected ? `linear-gradient(145deg, ${option.bgcolor}, #ffffff)`
                   
          : "transparent",
        transition: "0.4s ease-in-out",
        "&:hover": {
          boxShadow: `0px 8px 18px ${option.bgcolor}`,
        },
        }}
        onClick={onSelect}
      >
        {/* {selected && (
          <Box
            component="img"
            src={Images.select}
            alt="Selected"
            sx={{ position: "absolute", top: 8, right: 8, width: 20, height: 20 }}
          />
        )} */}
        <CardContent sx={{ display: "flex", flexDirection:{xs:'row',md:'column',lg:'column'}, alignItems: "center", gap: 1 }}>
           <Box>
           <img src={option.icon} alt="icon" style={{ width: 36, height: 36 }} />
           </Box>
          <Typography variant="body1" fontSize={18} color="black">
            {option.text}
          </Typography>
        </CardContent>
      </Typography>
    </Grid>
  );
};

const WorkExperienceList: React.FC = () => {
  const [selectedOption, setSelectedOption] = useState<ExperienceOption | null>(null);
  const [showInput, setShowInput] = useState(false);
  const [inputValue, setInputValue] = useState("");
  const navigate = useNavigate();
  const inputRef = useRef<HTMLInputElement>(null);

  const updateLocalStorage = (selectedOption: ExperienceOption, experienceYears: number) => {
    let currentValue = localStorage.getItem("user-profile");
    let currentValueObj = currentValue ? JSON.parse(currentValue) : {};
  
    localStorage.setItem(
      "user-profile",
      JSON.stringify({
        ...currentValueObj,
        preference: {
          ...currentValueObj.preference,
          totalWorkExperience: selectedOption.id === 1 ? experienceYears : false, // ✅ Store number if ID is 1, otherwise false
        },
      })
    );
  };

  // Handle Selection
  const handleSelect = (option: ExperienceOption): void => {
   
    setSelectedOption(option);
    if (option.id === 1) {
      setShowInput(true);
      setTimeout(() => {
        inputRef.current?.focus();
      }, 100);
    } else {
      navigate("/careersupport");
    }
  };

  // Handle Continue
  const handleContinue = (): void => {
    if (selectedOption) {
      const experienceYears = selectedOption.id === 1 ? Number(inputValue) || 0 : 0; // Ensure it's a number
      updateLocalStorage(selectedOption, experienceYears);
    }
    navigate("/careersupport");
  };

  return (
    <Box
      sx={{
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        height: "100vh",
        textAlign: "center",
        position: "relative",
      }}
    >
      {/* Title */}
      <Typography
        variant="h3"
        sx={{
          fontWeight: 500,
          textAlign: "center",
          maxWidth: "90%",
          fontSize: { xs: "1.5rem", lg: "2rem" },
          mb: { xs: 15, lg: 6 },
          color:"#495052"
        }}
      >
        Do you have <span style={{ color: "#F48438" }}>Work Experience?</span>
      </Typography>

      {/* Experience Options Grid */}
      <Grid marginBottom={20} container spacing={3} justifyContent="center">
        {EXPERIENCE_OPTIONS.map((option) => (
          <SelectionCard key={option.id} option={option} selected={selectedOption?.id === option.id} onSelect={() => handleSelect(option)} />
        ))}
      </Grid>

      {/* Input Field for Experience Duration */}
      {showInput && (
        <Box sx={{ width: { xs: "70%", sm: "400px" }, display: "flex", flexDirection: "column", gap: 2, mt:{xs:-14,lg:-8} }}>
          <Typography variant="h6" >
            How many <span style={{ color: "#F87171" }}>months of experience</span> do you have?
          </Typography>
          <TextField
            fullWidth
            name="experience"
            label="Enter duration in months"
            variant="outlined"
            inputRef={inputRef}
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            sx={{
              "& .MuiOutlinedInput-root": {
                borderRadius: "12px",
                "& fieldset": { borderLeft: "10px solid #D1D3F9" },
              },
            }}
          />
        </Box>
      )}

      {/* Navigation Buttons */}
      <Box
        sx={{
          position: "absolute",
          bottom: 30,
          width: "100%",
          display: "flex",
          justifyContent: "center",
          mt: -3,
        }}
      >
        <Button variant="text" sx={{ color: "#888", fontSize: { xs: "14px", sm: "16px" } }} onClick={() => navigate(-1)}>
          ← Back
        </Button>
        {selectedOption && (
          <Button variant="contained" sx={{ px: 4, py: 1.5, borderRadius: "20px", ml: 3,background:"#F48438", "&:hover": {
      backgroundColor: "#d96f2e", // slightly darker shade for hover
    }, }} onClick={handleContinue}>
            Continue
          </Button>
        )}
      </Box>
    </Box>
  );
};

export default WorkExperienceList;
