import { useFormik } from 'formik';
import React, { useRef, useState } from 'react'
import { allowedFileTypes, testScores } from 'src/assets/menu';
import FileUploadOutlinedIcon from "@mui/icons-material/FileUploadOutlined";
import { editProfile, uploadProfile } from 'src/services';
import { useAppDispatch, useAppSelector } from 'src/assets/hooks';
import { settestScores } from 'src/store/Slices/testScoresSlice';
import { Box, Button, Grid, InputLabel, TextField, Tooltip, Typography } from '@mui/material';
import { Info } from '@mui/icons-material';
import { closePopup, setPopup } from 'src/store/Slices/popupSlice';
import { secondaryButton } from 'src/components/styles/customStyles';
import VisibilityOutlinedIcon from '@mui/icons-material/VisibilityOutlined';
import { setDocuments } from 'src/store/Slices/documentsSlice';
import Images from 'src/assets';
import DatePickerComponent from 'src/genericComponents/datePicker';

interface Score {
    description: string;
    count: string;
    range: string;
}

const TestScoreForm = (props: any) => {
    const selectedTest = props.data;
    const selectedTestScores = testScores?.find((test) => test.name === selectedTest);
    const testscoresData = useAppSelector((state) => state.testscores);
    const dispatch = useAppDispatch();
    const inputFile = useRef<HTMLInputElement>(null);
    const [tookTest, setTookTest] = useState<any>();
    const [loading, setLoading] = useState(false);
    const [doc, setDoc] = useState<any>("");

    const parseRange = (range: string) => {
        const [min, max] = range.split('-').map(Number);
        return { min, max };
    };

    const requiredFields = selectedTestScores?.requiredFields || [];

    const computeTotal = (scores: Score[]): number | string => {
        const totalField = scores.find((score) => score.description === "Total");
        if (!totalField) return ""; 

        const relevantScores = scores.filter((score) =>
            requiredFields.includes(score.description) && score.count !== ""
        );

        if (relevantScores.length === 0) return "Invalid Total"; 

        let total = 0;
        if (selectedTestScores?.method === "add") {
            total = relevantScores.reduce(
                (acc, score) => acc + (parseInt(score.count) || 0),
                0
            );
        } else if (selectedTestScores?.method === "average") {
            total = relevantScores.reduce(
                (acc, score) => acc + (parseInt(score.count) || 0),
                0
            );
            total = relevantScores.length > 0 ? total / relevantScores.length : 0;
        }

        const { min, max } = parseRange(totalField.range);
        return total >= min && total <= max ? total : "Invalid Total";
    };

    const formik = useFormik({
        initialValues: {
            name: selectedTest,
            scores: selectedTestScores ? selectedTestScores.scores : [],
            testDate: tookTest,
            docId: doc._id,
        },
        onSubmit: async (values) => {
            setLoading(true);
            const data = {
                name: values.name,
                scores: selectedTestScores ? values.scores[0] : [],
                testDate: values.testDate,
                docId: values.docId,
            };
            console.log("Final tests payload:", [...testscoresData?.data, data]);
            const response = await editProfile({
                tests: [...testscoresData?.data, data],
            });

            if (response) {
                dispatch(settestScores(response.data.data.tests));
                setDoc("");
                setTookTest("");
                setLoading(false);
                dispatch(closePopup());
            } else {
                setLoading(false);
                dispatch(closePopup());
            }
        },
        validate: (values) => {
            const errors: any = {};
            values.scores.forEach((scoreArray, scoreArrayIndex) => {
                scoreArray.forEach((score, scoreIndex) => {
                    if (score.description === "Total") return;

                    const { min, max } = parseRange(score.range);
                    const count = Number(score.count);

                    if (count < min || count > max) {
                        if (!errors.scores) errors.scores = [];
                        if (!errors.scores[scoreArrayIndex]) errors.scores[scoreArrayIndex] = [];
                        errors.scores[scoreArrayIndex][scoreIndex] = `Score must be between ${min} and ${max}`;
                    }
                });
            });
            return errors;
        },
    });

    const documentUpload = async (
        event: React.ChangeEvent<HTMLInputElement>,
        fieldPath: string
    ) => {
        const file = event.target.files && event.target.files[0];
        if (file && allowedFileTypes.includes(file.type)) {
            const formData = new FormData();
            formData.append("uploaded_file", file);
            formData.append("fieldPath", fieldPath);

            const response = await uploadProfile(formData);
            if (response) {
                dispatch(setDocuments(response.data.data.docs));
                const lastDoc = response.data.data.docs.test.general.slice(-1)[0];
                setDoc(lastDoc);
            }
        } else {
            dispatch(
                setPopup({
                    show: true,
                    data: {
                        container: {
                            name: "error",
                            data: "Only jpeg, png, pdf files are accepted",
                            dimensions: { width: "250px" },
                        },
                        type: "custom",
                    },
                })
            );
        }
    };

    return (
        <form onSubmit={formik.handleSubmit}>
            <Grid container spacing={3} sx={{ padding: "2rem" }}>
                <Grid item xs={12}>
                <Typography sx={{ position: "relative", width: "1rem", height: "1rem", borderRadius: "50%", background: "#FEA89B" }}>
                        <Typography sx={{ position: "absolute", top: "-4px", left: "8px", width: "500px", color: "#000", fontWeight: 500 }}>
                            {selectedTest}
                        </Typography>
                        </Typography>
                </Grid>
                {formik.values.scores.map((scoreArray, scoreArrayIndex) =>
                    scoreArray.map((score, scoreIndex) => {
                        if (score.description === "Total") return null;

                        return (
                            <Grid item xs={12} sm={4} key={`${scoreArrayIndex}-${scoreIndex}`}>
                                <div style={{ display: "flex", flexDirection: "column" }}>
                                    <InputLabel sx={{ fontWeight: 500, color: "#000" }}>
                                        {score.description}
                                    </InputLabel>
                                    <TextField
                                        type="number"
                                        name={`scores[${scoreArrayIndex}][${scoreIndex}].count`}
                                        value={score.count}
                                        onChange={(e) => {
                                            formik.handleChange(e);
                                            const updatedScores = [...formik.values.scores[scoreArrayIndex]];
                                            updatedScores[scoreIndex].count = e.target.value;

                                            const allFieldsFilled = updatedScores
                                                .filter((score) => score.description !== "Total")
                                                .every((score) => score.count !== "");

                                            if (allFieldsFilled) {
                                                const totalIndex = updatedScores.findIndex((s) => s.description === "Total");
                                                if (totalIndex !== -1) {
                                                    updatedScores[totalIndex].count = String(computeTotal(updatedScores));
                                                }
                                            }

                                            formik.setFieldValue(`scores[${scoreArrayIndex}]`, updatedScores);
                                        }}
                                        size="small"
                                        variant="outlined"
                                        placeholder={`${score.range}`}
                                    />
                                    {formik.errors.scores &&
                                        formik.errors.scores[scoreArrayIndex] &&
                                        formik.errors.scores[scoreArrayIndex][scoreIndex] && (
                                            <div style={{ color: "red", fontSize: "12px" }}>
                                                {String(formik.errors.scores[scoreArrayIndex][scoreIndex])}
                                            </div>
                                        )}
                                </div>
                            </Grid>
                        );
                    })
                )}
                <Grid item xs={6} sm={4}>
                    <Typography 
                    sx={{ fontSize: { xs: "13px", sm: "16px" },fontWeight:500 }}>
                    Took test on</Typography>
                    <DatePickerComponent
                        selectedDate={tookTest}
                        onChange={(date) => {
                            const formattedDate = date ? date.toISOString().slice(0, 10) : '';
                            setTookTest(formattedDate);
                            formik.setFieldValue('testDate', formattedDate);
                        }}
                        maxDate={new Date()}
                        placeholderText="Took test on"
                    />
                </Grid>
                <Grid item xs={12} sm={4}>
                <Typography fontWeight="500" sx={{ display: "flex", alignItems: "center", gap: "5px" }}>
                        Upload file
                        <Tooltip
                            slotProps={{
                                tooltip: {
                                    sx: {
                                        color: "#000",
                                        backgroundColor: "#fff",
                                        boxShadow: 1,
                                        fontSize: "14px",
                                        "&.MuiTooltip-tooltip": {
                                            marginTop: "0px !important",
                                        },
                                    },
                                },
                            }}
                            title="Only jpeg, png, pdf files are accepted"
                            placement="bottom"
                        >
                            <Info sx={{ color: "#7d7d7d", fontSize: "1rem" }} />
                        </Tooltip>
                    </Typography>
                    {doc ? (
                        <Box sx={{ display: "flex",alignItems:"center",gap:"4px" }}>
             
                        {doc?.data?.originalname}
                        <VisibilityOutlinedIcon sx={{ fontSize: "large",pt:0.5,cursor:"pointer" }} onClick={() => {
                          dispatch(
                            setPopup({
                              show: true,
                              data: {
                                container: {
                                  name: "fileViewer",
                                  data: doc?.data?.preview_url,
                                  dimensions: {
                                    width: "500px",
                                  },
                                },
                                type: "custom",
                              },
                            })
                          )
                        }} />
                       
                      </Box>
                    ) : (
                        <>
                            <input
                                style={{ display: "none" }}
                                type="file"
                                onChange={(event) => documentUpload(event, `test.general`)}
                                ref={inputFile}
                                accept=".pdf"
                            />
                            <Button onClick={() => inputFile?.current?.click()} sx={{color:"#3b3f76"}}>
                                <FileUploadOutlinedIcon fontSize="small" />
                            </Button>
                        </>
                    )}
                </Grid>
                <Grid xs={12} sx={{ display: "flex", justifyContent: "end" }}>
                    <Button type="submit" sx={[secondaryButton,{width:"100px"}]}>
                        {loading ? (
                            <Box component="img" src={Images.standardLoader} alt="standardLoader" sx={{ width: "1.25rem", height: "1.25rem" }} />
                        ) : (
                            "Submit"
                        )}
                    </Button>
                </Grid>
            </Grid>
        </form>
    );
};

export default TestScoreForm;

