import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { Box, Button, Typography, Grid, CardContent } from "@mui/material";
import { testReadyStyles } from "src/components/styles/customStyles";
import { hover } from "@testing-library/user-event/dist/hover";


interface StudyLevelOption {
  id: number;
  name: string;
  color: string;
  bgcolor: string;
}

// Study level options
const STUDY_LEVELS: StudyLevelOption[] = [
  { id: 1, name: "Masters", color: "#22D3EE", bgcolor: "#70A6B2" },
  { id: 2, name: "Bachelors", color: "#F87171", bgcolor: "#AAAEFE" },
  { id: 3, name: "PG Diploma", color: "#FBBF24", bgcolor: "#FF9784" },
  { id: 4, name: "Diploma", color: "#FBBF24", bgcolor: "#FF9784" },
  { id: 5, name: "Certificate", color: "#FBBF24", bgcolor: "#70A6B2" },
  { id: 6, name: "PhD", color: "#FBBF24", bgcolor: "#AAAEFE" },
];

// Reusable SelectionCard Component
const SelectionCard: React.FC<{ option: StudyLevelOption; selected: boolean; onSelect: () => void }> = ({
  option,
  selected,
  onSelect,
}) => {
  return (
    <Grid item xs={12} sm={6} md={4} lg={6} sx={{ display: "flex", justifyContent: "center" }}>
      <Typography
        role="button"
        aria-label={option.name}
        sx={{
          position: "relative",
          ...testReadyStyles.card2,
          height: { xs: "20px", lg: "70px" },
          width: { xs: "250px", sm: "300px", md: "320px" },
          borderLeft: `10px solid ${option.bgcolor}`,
          textAlign: "center",
          padding: "15px",
          cursor: "pointer",
          background: selected ? `linear-gradient(145deg, ${option.bgcolor}, #ffffff)`
                   
                    : "transparent",
                  transition: "0.4s ease-in-out",
                  "&:hover": {
                    boxShadow: `0px 8px 18px ${option.bgcolor}`,
                  },
        }}
        onClick={onSelect}
      >
        {/* {selected && (
          <Box
            component="img"
            src={Images.select}
            alt="Selected"
            sx={{ position: "absolute", top: 8, right: 8, width: 20, height: 20 }}
          />
        )} */}
        <CardContent sx={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 1 }}>
          <Typography variant="body1" sx={{ fontSize: "14px", color: "#495052" }}>
            {option.name}
          </Typography>
        </CardContent>
      </Typography>
    </Grid>
  );
};

const StudyLevel: React.FC = () => {
  const [selectedLevels, setSelectedLevels] = useState<StudyLevelOption|null>(null);
  const navigate = useNavigate();

  // Handle selection
  const handleSelect = (option: StudyLevelOption): void => {
    setSelectedLevels((prev) => (prev?.id === option.id ? null : option));
  };
  
  
  const setDegree=(collectedData:{degree:string})=>{
    let currentValue=localStorage.getItem("user-profile");
    let currentValueObj=currentValue?JSON.parse(currentValue):{}
    if(currentValueObj)
    {
      localStorage.setItem("user-profile",JSON.stringify({...currentValueObj,preference:currentValueObj.preference?{...currentValueObj.preference,
        degree:collectedData.degree
      }:{degree:collectedData.degree}}));	
    }
  }

  useEffect(() => {
    const currentValue = localStorage.getItem("user-profile");
    const currentValueObj = currentValue ? JSON.parse(currentValue) : null;
    const savedDegree = currentValueObj?.preference?.degree;
  
    if (savedDegree) {
      const matchedLevel = STUDY_LEVELS.find((level) => level.name === savedDegree);
      if (matchedLevel) {
        setSelectedLevels(matchedLevel);
      }
    }
  }, []);

  // Handle Continue
  const handleContinue = (): void => {
    if(selectedLevels){
      setDegree({degree:selectedLevels?.name})
    }
    navigate("/programselect");
  };

  return (
    <Box
      sx={{
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        height: "100vh",
        textAlign: "center",
        marginTop:{xs:6,lg:6}
      }}
    >
      {/* Title */}
      <Typography
        variant="h4"
        fontWeight="bold"
        mb={3}
        sx={{ fontSize: { xs: "1.5rem", lg: "2rem" }, maxWidth: "90%",color:"#495052" }}
      >
        Which <span style={{ color: "#F48438" }}>Level of Study</span> are you applying for?
      </Typography>

      {/* Study Level Selection Grid */}
      <Grid container spacing={3} justifyContent="center" sx={{ maxWidth: "900px", mx: "auto" }}>
        {STUDY_LEVELS.map((option) => (
          <SelectionCard
            key={option.id}
            option={option}
            selected={selectedLevels?.id === option.id}
            onSelect={() => handleSelect(option)}
          />
        ))}
      </Grid>

      {/* Navigation Buttons */}
      <Box sx={{ mt:{xs:4,lg:13}, display: "flex", justifyContent: "center", gap: 2 }}>
        <Button variant="text" sx={{ color: "#888" }} onClick={() => navigate(-1)}>
          ← Back
        </Button>
        {selectedLevels!=null && (
          <Button variant="contained" sx={{ px: 4, py: 1.5, borderRadius: "20px",background:"#F48438",color:"#FFFF", "&:hover": {
      backgroundColor: "#d96f2e",
    }, }} onClick={handleContinue}>
            Continue
          </Button>
        )}
      </Box>
    </Box>
  );
};

export default StudyLevel;
export { STUDY_LEVELS };
