import { PayloadAction, createSlice } from "@reduxjs/toolkit";
import { BlockedList, StoreItem } from "../../types/types";

let initialState:StoreItem<BlockedList[]>={
    requestStatus:"not_initiated",
    responseStatus:"not_recieved",
    haveAnIssue:false,
    issue:"",
    data:[]
}

export const BlockedListSlice=createSlice({
    name:'BlockedList',
    initialState:initialState,
    reducers:{
        initBlockedList:(state,action:PayloadAction<StoreItem<BlockedList[]>>)=>({...action.payload}),
        addBlockedList:(state,action:PayloadAction<BlockedList>)=>{state.data.push(action.payload)},
        updateBlockedList:(state,action:PayloadAction<BlockedList>)=>{
            let index=state.data.findIndex((item)=>item._id===action.payload._id);
            state.data[index]=action.payload;
        },
        setBlockedList:(state,action:PayloadAction<BlockedList[]>)=>{state.data=action.payload},
        removeBlockedList:(state,action:PayloadAction<string>)=>{state.data=state.data.filter((item)=>item._id!==action.payload)},
        resetBlockedList:(state,action:PayloadAction)=>({...initialState})

    }
})

export const {initBlockedList,setBlockedList,addBlockedList,removeBlockedList,updateBlockedList,resetBlockedList}=BlockedListSlice.actions;
export default BlockedListSlice.reducer;