import React, { useState } from "react";
import Grid from "@mui/material/Grid";
import Images from "../../assets/index";
import Button from "@mui/material/Button";
import { Box, Stack, Typography } from "@mui/material";
// import { editProfile } from "../../services";
import { editProfile } from "../../services";
import { useAppDispatch, useAppSelector } from "../../assets/hooks";
import { setpreferences } from "../../store/Slices/preferencesSlice";
import { secondaryButton } from "src/components/styles/customStyles";
import { closePopup } from "src/store/Slices/popupSlice";
const Country = ({ setQaTab, missingFields, qaTab }: any) => {
  const countryPreference = useAppSelector(state =>state.preferences);
  const [selectedCountries, setSelectedCountries] = useState<string[]>((countryPreference.data && countryPreference?.data?.country) || []);
  const dispatch = useAppDispatch();
  const [loading, setLoading] = useState(false)

  const CountryImages = [
    {
      name: "Australia",
      src: `${Images.Australia}`,
    },
    {
      name: "Canada",
      src: `${Images.Canada}`,
    },
    {
      name: "United Kingdom",
      src: `${Images.UnitedKingdom}`,
    },
    {
      name: "New Zealand",
      src: `${Images.NewZealand}`,
    },
    {
      name: "Ireland",
      src: `${Images.Ireland}`,
    },
    {
      name: "United States of America",
      src: `${Images.UnitedStates}`,
    },
  ];
  const currentIndex = missingFields.indexOf(qaTab);
  
//   const handleContinue = () => {
//     handleSubmit()
//     if (currentIndex !== -1 && currentIndex < missingFields.length - 1) {
//         setQaTab(missingFields[currentIndex + 1]); 
//     } else {
//         // closePopup();
//     }
// };

const handleBack = () => {
    if (currentIndex > 0) {
        setQaTab(missingFields[currentIndex - 1]); 
    }
};

  const toggleCountrySelection = (country: any) => {
    if (selectedCountries.includes(country.name)) {
      setSelectedCountries(selectedCountries.filter((c) => c !== country.name));
    } else {
      setSelectedCountries([...selectedCountries, country.name]);
    }
  };

  const handleContinue = async () => {
    setLoading(true)
    const values = {
      ...countryPreference.data,
      country:selectedCountries,
    };
    const response = await editProfile({
      preference: values
    });
    if (response) {
      dispatch(setpreferences(response.data.data.preference));
      setLoading(false)
            if (currentIndex !== -1 && currentIndex < missingFields.length - 1) {
                setQaTab(missingFields[currentIndex + 1]);
            } else {
                // closePopup();
                dispatch(closePopup())
            }
        }
        else {
            setLoading(false)
        }
  };
//   const handleSkip = () => {
//     if (currentIndex !== -1 && currentIndex < missingFields.length - 1) {
//         setQaTab(missingFields[currentIndex + 1]);
//     } else {
//         // closePopup();
//         dispatch(closePopup())
//     }
// }
  return (
    <>
      <Typography
        sx={{
          color: "#3B3F76",
          textAlign: "center",
          fontFamily: "Inter",
          fontWeight: 700,
          fontSize: { xs: "20px", sm: "28px" },
          mt:3
        }}
      >
        Which <b style={{ color: "rgba(48, 51, 99, 0.5)" }}>country</b> you wish to pursue
        your studies?
      </Typography>

      <Grid container sx={{ width: {xs:"90%",md:"80%",lg:"70%"} , marginTop: "1rem" }} spacing={3}>
        {CountryImages.map((item, index) => {
          return (
            <Grid item md={4} sm={6} xs={12}>
              <Box
                sx={{
                  display: "flex",
                  justifyContent: "center",
                  flexDirection: "column",
                  alignItems: "center",
                  background: "#F8F8FC",
                  padding: "14px",
                  borderRadius: "6px",
                  boxShadow: 1,
                }}
              >
                <Box sx={{ position: "relative" }}>
                  <Box
                    component="img"
                    sx={
                      selectedCountries.includes(item.name)
                        ? {
                            cursor: "pointer",
                            webkitFilter: "grayscale(100%)",
                            filter: "grayscale(40%)",
                          }
                        : {
                            cursor: "pointer",
                            "&:hover": {
                              // border:"3px solid rgb(240, 166, 166)",
                              borderRadius: "6px",
                              boxShadow:
                                "0px 0px 0px 0px #FEB853,0px 0px 0px 0px #FEB853,0px 2px 3px 3px  #FEB853",
                            },
                          }
                    }
                    src={item.src}
                    alt="loginImage"
                    onClick={() => toggleCountrySelection(item)}
                  />
                  <Box
                    sx={{
                      position: "absolute",
                      display: "flex",
                      justifyContent: "center",
                      alignItems: "center",
                      top: "50%",
                      bottom: "50%",
                      left: "50%",
                      right: "50%",
                    }}
                  >
                    {selectedCountries.includes(item.name) ? (
                      <img
                        style={{
                          width: "40px",
                          height: "40px",
                          cursor: "pointer",
                        }}
                        src={Images.selected}
                        alt="selected"
                        onClick={() => toggleCountrySelection(item)}
                      />
                    ) : (
                      ""
                    )}
                  </Box>
                </Box>
                <p style={{ fontSize: "16px", fontWeight: "500" ,margin:"5px"}}>
                  {item.name}
                </p>
              </Box>
            </Grid>
          );
        })}
      </Grid>
      <Stack
        direction="row"
        spacing={3}
        sx={{
          marginTop: "10%",
        }}
      >
        {/* <Button
          type="submit"
          onClick={handleSubmit}
          variant="contained"
          sx={{
            border: "1px solid #3B3F76",
            color: "#3b3f76",
            background:"#fff",
            textTransform: "none",
            borderRadius: "10px",
            "&:hover": {
              border: "1px solid #3B3F76", 
              background:"#fff"
            },
          }}
        >
          Continue
        </Button> */}
        <Box sx={{ display: 'flex', gap: 2 }}>
                        {currentIndex > 0 && (
                            <Button sx={secondaryButton} onClick={handleBack}>
                                Back
                            </Button>
                        )}
                        <Button sx={secondaryButton} onClick={handleContinue}>
                        {loading ? (
                                      <img
                                        src={Images.standardLoader}
                                        alt="load"
                                        style={{
                                          width: "20px",
                                          height: "20px",
                                          padding: "5px",
                                        }}
                                      />
                                    ) : (
                                      "Continue"
                                    )}
                        </Button>
                        {/* <Button sx={secondaryButton} onClick={handleSkip}>
                        {loading ? (
                                      <img
                                        src={Images.standardLoader}
                                        alt="load"
                                        style={{
                                          width: "20px",
                                          height: "20px",
                                          padding: "5px",
                                        }}
                                      />
                                    ) : (
                                      "Skip"
                                    )}
                        </Button> */}
                    </Box>
      </Stack>
    </>
  );
};

export default Country;
