import { Avatar, Box, Button, Grid, Typography } from '@mui/material';
import React, { useContext, useState } from 'react';
import ArrowForwardIcon from '@mui/icons-material/ArrowForward';
import DeleteOutlineIcon from '@mui/icons-material/DeleteOutline';
import ArrowBackIcon from '@mui/icons-material/ArrowBack';
import ErrorIcon from '@mui/icons-material/Error';
import Context from 'src/assets/constants/context';
import { summaryRoute } from 'src/services';
import { useAppSelector } from 'src/assets/hooks';
import TimerIcon from "@mui/icons-material/Timer";

interface Course {
  category: string;
  course: {
    _id: string;
    name: string;
    university: {
      logoSrc: string;
      name: string;
    };
  };
  intake: string;
}

interface Product {
  category: string;
  courseId: string;
  intake: string;
}

// interface Package {
//   products: {
//     _id: string;
//     category: string;
//     quantity: number;
//   }[];
// }

const Products = (props: any) => {
  const { courses, setCourses } = useContext(Context);
  const { selectedPackage } = useContext(Context);
  const { setSummary } = useContext(Context);
  const suggestedPackages = useAppSelector(store => store.suggestedPackages)
  // const [validationErrors, setValidationErrors] = useState<string[]>([]);
  const [invalidCourses, setInvalidCourses] = useState<Record<string, string>>({});

  const packageData = suggestedPackages?.data?.find((pkg: any) => pkg._id === selectedPackage);

  const products: Product[] = courses.map((item: Course) => ({
    category: item.category,
    courseId: item.course._id,
    intake: item.intake,
  }));

  const validateProducts = (selectedCourses: Product[], packageProducts: { category: string }[]) => {
    const errors: Record<string, string> = {};
    const isValid = selectedCourses.every(course => {
      const match = packageProducts.some(pkgProduct => pkgProduct.category === course.category);
      if (!match) {
        errors[course.courseId] = `Category '${course.category}' does not fit in the selected package.`;
      }
      return match;
    });
    setInvalidCourses(errors);
    return isValid;
  };

  const eventHandler = async (event: { name: string; data?: any }) => {
    switch (event.name) {
      case 'checkout':
        try {
          if (packageData) {
            const packageProducts = packageData && packageData?.products?.map((product: any) => ({
              category: product.category
            }));
            // console.log(products,packageProducts)

            const isProductsValid = validateProducts(products, packageProducts);

            if (isProductsValid) {
              const response = await summaryRoute({
                packageId: selectedPackage ? packageData._id : null,
                products: selectedPackage ? [] : products
              });
              setSummary(response.data.data);
              props.setActiveTab('Payment');
            } else {
            }
          } else {
            const response = await summaryRoute({
              packageId: '', // No package ID
              products: products
            });
            setSummary(response.data.data);
            props.setActiveTab('Payment');
          }
        } catch (err) {
          console.error(err);
        }
        break;

      case 'delete':
        const items = courses.filter((item: any) => item.course._id !== event.data.course._id);
        setCourses(items);
        break;

      default:
        break;
    }
  };
  const formatDate = (dateString: string): string => {
    const date = new Date(dateString);
    const month = date.toLocaleString("default", { month: "short" });
    const year = date.getFullYear();
    return `${month} ${year}`;
  };
  return (
    <div>
      <Box sx={{ height: '500px', overflowY: 'scroll' }}>
        <Typography sx={{ fontSize: '1.5rem', color: '#3B3F7680', display: 'flex', gap: '0.5rem', alignItems: 'center', fontWeight: '600' }}>
          <p style={{ background: '#FEB853', width: '1rem', height: '1rem', margin: 0, borderRadius: '50%' }}></p>
          Products
        </Typography>
        <Box
          sx={{
            overflowX: 'auto',
            padding: '0 1rem',
            scrollbarWidth: 'none',
            '&::-webkit-scrollbar': {
              display: 'none',
            },
          }}
        >
          <Grid container spacing={3} sx={{
            alignItems: 'center',
            width: '100%',
            p: 1,
            '&::-webkit-scrollbar': {
              width: '12px',
              backgroundColor: '#fff',
            },
            '&::-webkit-scrollbar-thumb': {
              backgroundColor: '#fff',
              borderRadius: '8px',
            },
            '&::-webkit-scrollbar-track': {
              backgroundColor: '#fff',
            },
          }}>
            {courses.length > 0 ? courses.map((item: Course, i: number) => (
              <Grid item xs={12} sm={6} md={4} lg={3} key={i}>
                <Box sx={{ background: '#fff', borderRadius: '15px', p: 2, boxShadow: 2, position: 'relative' }}>
                  <DeleteOutlineIcon fontSize="small" sx={{ color: '#3b3f76', float: 'right', cursor: 'pointer' }} onClick={() => eventHandler({ name: 'delete', data: item })} />
                  {invalidCourses[item.course._id] && (
                    <Box sx={{ position: 'absolute', top: '10px', right: '35px', display: 'flex', alignItems: 'center' }}>
                      <ErrorIcon sx={{ color: 'red', fontSize: '1.5rem' }} />
                    </Box>
                  )}
                  <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: '0.8rem' }}>
                    <Typography color="#3b3f76" fontWeight="600">Course</Typography>
                    <Avatar src={item.course.university.logoSrc} alt="logo" />
                    <Typography  textAlign="center" sx={{
                      fontSize: { xs: "12px", lg: "13px" },
                      fontWeight: 500,
                      textOverflow: "ellipsis ",
                      lineClamp: 1,
                      height: "2.3rem",
                      textTransform: "capitalize",
                      overflow: "hidden",
                      display: "-webkit-box",
                      WebkitLineClamp: "2",
                      WebkitBoxOrient: "vertical",
                    }}>{item.course.name}</Typography>
                    <Typography fontSize="14px" color="#A8A8A8">{item.course.university.name}</Typography>
                    <Typography
                      component="span"
                      fontSize="0.8rem"
                      fontWeight="500"
                      sx={{
                        display: "flex",
                        alignItems: "center",
                        whiteSpace: "nowrap",
                        mt: 1,
                      }}
                    >
                      <TimerIcon sx={{ fontSize: "1.25rem" }} />
                      &nbsp; Start date:{" "}
                      {item.intake ? formatDate(item.intake) : "N/A"}
                    </Typography>
                    {invalidCourses[item.course._id] && (
                      <Typography sx={{ color: 'red', fontSize: '12px', textAlign: 'center' }}>
                        {invalidCourses[item.course._id]}
                      </Typography>
                    )}
                  </Box>
                </Box>
              </Grid>
            )) : (
              <Grid item xs={12} sx={{ textAlign: 'center' }}>
                <Typography sx={{ textAlign: 'center' }}>No products to checkout</Typography>
              </Grid>
            )}
          </Grid>
        </Box>
      </Box>
      <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
        <Button
          sx={{
            float: 'right',
            borderRadius: '50%',
            minWidth: 0,
            background: '#3b3f76',
            height: '2.5rem',
            width: '2.5rem',
            color: '#fff',
            '&:hover': {
              background: '#3b3f76',
              color: '#fff',
            },
          }}
          onClick={() => props.setActiveTab('Packages')}
        >
          <ArrowBackIcon />
        </Button>
        {courses.length > 0 && (
          <Button
            sx={{
              float: 'right',
              borderRadius: '50%',
              minWidth: 0,
              background: '#3b3f76',
              height: '2.5rem',
              width: '2.5rem',
              color: '#fff',
              '&:hover': {
                background: '#3b3f76',
                color: '#fff',
              },
            }}
            onClick={() => eventHandler({ name: 'checkout' })}
          >
            <ArrowForwardIcon />
          </Button>
        )}
      </Box>
    </div>
  );
};

export default Products;
