import React from "react";
import { TextField } from "@mui/material";
import { Field } from "formik";

interface FieldProps {
  id: string;
  name: string;
  placeholder?: string;
  value: any;
  fullWidth: boolean;
  type: string;
  onChange: (event: React.ChangeEvent<HTMLInputElement>) => void;
  error?:any;
  disabled?:boolean;
  helperText?:any;
  onBlur?:any;
  maxLength?:number;
  onkeydown?:any
}

const CustomField: React.FC<FieldProps> = ({
  id,
  name,
  type ,
  placeholder,
  value,
  onChange,
  onBlur,
  helperText,
  error,
  maxLength,
  onkeydown,
  ...rest
}) => {
  return (
    <Field
      id={id}
      name={name}
      size="small"
      type={type}
      placeholder={placeholder}
      value={value}
      onChange={onChange}
      autoComplete="off"
      error={error}
      onBlur={onBlur}
      helperText={helperText}
      maxLength={maxLength}
      onKeyDown={onkeydown}
      InputProps={{
        inputProps: { min: 0 },
        sx: {
          'input[type=number]': {
            '-moz-appearance': 'textfield', 
            '-webkit-appearance': 'none', 
            'margin': 0, 
          },
          'input[type=number]::-webkit-outer-spin-button, input[type=number]::-webkit-inner-spin-button': {
            '-webkit-appearance': 'none',
            
          },
          "& .MuiOutlinedInput-notchedOutline":{
            borderColor:"rgb(0 0 0 / 15%) !important"
          }
        },
      }}
      sx={{
        "&::placeholder": {
          color: "#000 !important"
        },
        '& .MuiOutlinedInput-root .Mui-error': {
          '& fieldset': {
            borderColor: 'red',
          },
        },
      }}
      // fullWidth={fullWidth}
      as={TextField}
      // sx={{width:"90%"}}
      {...rest}
    />
  );
};

export default CustomField;
