import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { Box, Button, Typography, Grid, CardContent } from "@mui/material";
import { testReadyStyles } from "src/components/styles/customStyles";
import Images from "src/assets";

// Define TypeScript interface for publication objects
interface PublicationOption {
  id: number;
  text: string;
  icon: string;
  color: string;
  bgcolor: string;
}

// Array of publication options
const PUBLICATION_OPTIONS: PublicationOption[] = [
  { id: 1, text: "Yes", icon: Images.CheckboxRightTeal, color: "#70A6B2", bgcolor:"#70A6B2"},
  { id: 2, text: "No", icon: Images.CheckboxWrongRed, color: "#FF9784", bgcolor:"#FF9784" },
];


// Reusable SelectionCard Component
const SelectionCard: React.FC<{ option: PublicationOption; selected: boolean; onSelect: () => void }> = ({
  option,
  selected,
  onSelect,
}) => {
  return (
    <Grid item xs={12} sm={6} md={4} lg={3} sx={{ display: "flex",justifyContent:'center', flexDirection: {xs:'row',md:'column',lg:'column'}, alignItems: "center", gap: 1 }}>
      <Typography
        role="button"
        aria-label={option.text}
        sx={{
          position: "relative",
          ...testReadyStyles.card2,
          borderLeft: `10px solid ${option.bgcolor}`,
          width: { xs: "70%", sm: "260px", md: "280px",lg:'310px' },
          textAlign: "center",
          padding: "15px",
          cursor: "pointer",
          backgroundColor: selected ? "#F4F4FF" : "#fff",
          transition: "0.3s ease-in-out",
            "&:hover": { boxShadow: `0px 8px 15px ${option.color}` },
        }}
        onClick={onSelect}
      >
        {selected && (
          <Box
            component="img"
            src={Images.select}
            alt="Selected"
            sx={{ position: "absolute", top: 8, right: 8, width: 20, height: 20 }}
          />
        )}
        <CardContent sx={{ display: "flex", flexDirection:{xs:'row',md:'column',lg:'column'}, alignItems: "center", gap: 1 }}>
          <Box>
            <img src={option.icon} alt="icon" style={{ width: 36, height: 36 }} />
          </Box>
          <Typography variant="body1" fontSize={18} color="black">
            {option.text}
          </Typography>
        </CardContent>
      </Typography>
    </Grid>
  );
};

const Publication: React.FC = () => {
  const [selectedOption, setSelectedOption] = useState<PublicationOption | null>(null);
  const [isOptionSelected, setIsOptionSelected] = useState<boolean>(false);
  const navigate = useNavigate();

 
  useEffect(() => {
    if (selectedOption) {
      const isPublished = selectedOption.text === "Yes";
      // Update localStorage
      let currentValue = localStorage.getItem('user-profile');
      let currentValueObj = currentValue ? JSON.parse(currentValue) : {};
      if (currentValueObj) {
        localStorage.setItem('user-profile', JSON.stringify({ ...currentValueObj, isPublicationLevel: isPublished }));
      }

      // Navigate to the appropriate path based on selection after Continue is clicked
      if (isOptionSelected) {
        const nextPath = selectedOption.id === 1 ? "/researchtype" : "/workexperience";
        navigate(nextPath);
      }
    }
  }, [selectedOption, navigate, isOptionSelected]);

  const handleSelect = (option: PublicationOption): void => {
    setSelectedOption(option);
    updateLocalStorage(option.text==='Yes')

    const nextPath = option.id === 1 ? "/researchtype" : "/workexperience";
    navigate(nextPath);
    setIsOptionSelected(true);
  };

const updateLocalStorage=(isPublished:Boolean)=>{
  let currentValue=localStorage.getItem('user-profile')
  let currentValueObj=currentValue?JSON.parse(currentValue):{}

  if(currentValueObj){
    localStorage.setItem('user-profile',JSON.stringify({...currentValueObj,isPublicationLevel:isPublished}))
  }
}

  return (
    <Box
      sx={{
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        height: "100vh",
        textAlign: "center",
        position: "relative",
      }}
    >
      {/* Title */}
      <Typography
        variant="h3"
        sx={{
          fontWeight: 500,
          textAlign: "center",
          maxWidth: "90%",
          fontSize: { xs: "1.5rem", lg: "2rem" },
          mb: { xs: 13, lg: 6 },
          color:"#495052"
        }}
      >
        Have you published any <span style={{ color: "#F48438" }}>research papers?</span>
      </Typography>

      {/* Publication Options Grid */}
      <Grid marginBottom={20} container spacing={3} justifyContent="center">
        {PUBLICATION_OPTIONS.map((option) => (
          <SelectionCard  key={option.id} option={option} selected={selectedOption?.id === option.id} onSelect={() => handleSelect(option)} />
        ))}
      </Grid>

      {/* Back Button - Fixed at Bottom */}
      <Box
        sx={{
          position: "absolute",
          bottom: 30,
          width: "100%",
          display: "flex",
          justifyContent: "center",
          mt: -3,
        }}
      >
        <Button variant="text" sx={{ color: "#495052", fontSize: { xs: "14px", sm: "16px" } }} onClick={() => navigate(-1)}>
          ← Back
        </Button>
      </Box>
    </Box>
  );
};

export default Publication;
