let token = localStorage.getItem("_auth");
const getHeaders = () => {
  token = localStorage.getItem("_auth");
  const headers = {
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${token}`,
    },
  };
  return headers;
};
let headers = getHeaders();

const handleApiError = (error: any): string => {
  let errorMessage = error.message;
  const statusCode = error.response?.status;

  if (error instanceof AxiosError) {
    const errorResponse = error.response?.data;

    if (error.message === "Network Error") {
      errorMessage = "Network Error. Please check your internet connection.";
    } else if (errorResponse?.message === "login again" ||
      errorResponse?.message === "Token Verification Failed" ||
      errorResponse?.message === "jwt malformed" ||
      errorResponse?.message === "Unauthorised entry" ||
      errorResponse?.message === "Invalid token"
    ) {
      errorMessage = "Session expired";
      logout();
      dispatch(
        setUserAuthStatus({
          isAuthorized: false,
          isRegistered: false,
          role: "guest",
        })
      );
      dispatch(
        setPopup({
          show: true,
          data: {
            container: {
              name: "logoutpop",
              data: errorMessage,
              dimensions: { width: "30%", height: "40%", show: "none",close:"none" },
            },
            type: "custom",
          },
        })
      );
      return errorMessage; // Exit early as 401 has a specific behavior
    } else if (statusCode === 500) {
      errorMessage =
        "We’re having trouble completing your request. Please bear with us as we fix this.";
    } else {
      errorMessage = errorResponse?.message || errorMessage;
    }
  } else if (errorMessage === "Otp not sent") {
    errorMessage = "Phone number is not valid";
  } else if (error instanceof Error) {
    errorMessage = error.message || errorMessage;
  }

  // For non-401 errors, dispatch the generic error popup
  dispatch(
    setPopup({
      show: true,
      data: {
        container: {
          name: "error",
          data: errorMessage,
          dimensions: { width: "30%", height: "40%", show: "none" },
        },
        type: "custom",
      },
    })
  );

  return errorMessage;
};


