import { Box, ListItemIcon, Typography, Divider } from '@mui/material';
import React, { useContext, useEffect} from 'react';
import Products from './products';
import Payment from './payment';
import Packages from './packages';
import Context from 'src/assets/constants/context';

const Checkout = (props: any) => {
  const {activeTab, setActiveTab} = useContext(Context);
  const { setCourses} = useContext(Context);

  useEffect(()=>{
    setCourses(props.data)
    setActiveTab("Packages")
    // eslint-disable-next-line
  },[props.data])

  const tabs = [
    {
      title: "Packages",
      component: (

        <div>
          <Packages
            setActiveTab={setActiveTab}
          />
        </div>
      ),
      image: 1,
    },
    {
      title: "Products",
      component: (
        <div>
          <Products
            setActiveTab={setActiveTab}
          />
        </div>
      ),
      image: 2,
    },
    {
      title: "Payment",
      component: (
        <div>
          <Payment setActiveTab={setActiveTab}
             />
        </div>
      ),
      image: 3,
    },
  ];

  return (
    <div style={{padding:"1rem"}}>
      <Box
        sx={{
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          width: '100%',
          
        }}
      >
        <Box sx={{ display: 'flex', alignItems: 'center', width: { xs: "100%", sm: "50%", md: '30%' },mt:2 }}>
          {tabs.map((item, index) => {
            const isActive = activeTab === item.title || (activeTab === "Payment" && index <= tabs.findIndex(tab => tab.title === activeTab));
            return (
              <React.Fragment key={item.title}>
                <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
                  <Box
                    sx={{
                      backgroundColor: "#fff",
                      border: `2px solid ${isActive ? "#3b3f76" : "#3B3F7666"}`,
                      position: 'relative',
                      transition: 'background-color 0.3s',
                      display: 'flex',
                      flexDirection: 'column',
                      alignItems: 'center',
                      justifyContent: 'center',
                      borderRadius: '50%',
                      width: '25px',
                      height: '25px',
                      zIndex: 1,
                    }}
                  >
                    <ListItemIcon sx={{ display: 'flex', justifyContent: 'center', color: isActive ? "#3b3f76" : "#3B3F7666", fontWeight: 500 }}>
                      {item.image}
                    </ListItemIcon>
                  </Box>
                  <Typography sx={{ color: isActive ? "#3b3f76" : "#3B3F7666", fontSize: "13px", fontWeight: 600, mt: 0.5 }}>
                    {item.title}
                  </Typography>
                </Box>
                {index < tabs.length - 1 && (
                  <Divider
                    orientation="horizontal"
                    sx={{
                      borderColor: "#3b3f76",
                      height: '2px',
                      flexGrow: 1,
                      mb: 2,
                    }}
                  />
                )}
              </React.Fragment>
            );
          })}
        </Box>
      </Box>
      <Box>
        {tabs.find(tab => tab.title === activeTab)?.component}
      </Box>
    </div>
  );
};

export default Checkout;
