import React, { useState, useContext, useEffect } from "react";
import Images from "../../assets/index";
import { Formik, Form, useFormik } from "formik";
import { editProfile } from "../../services";
import { Box, Button, Grid, InputLabel, Stack, TextField, Typography, FormControl, RadioGroup, FormControlLabel, Radio, Select, MenuItem, Dialog, DialogTitle, DialogContent, DialogActions } from "@mui/material";
import { Link, useNavigate } from "react-router-dom";
import ArrowForwardIcon from "@mui/icons-material/ArrowForward";
import ArrowBackIcon from "@mui/icons-material/ArrowBack";
import { settestScores } from "../../store/Slices/testScoresSlice";
import { useAppDispatch, useAppSelector } from "../../assets/hooks";
import { testScores } from "src/assets/menu";
import { CustomButton } from "src/genericComponents/customButton";
import { closePopup } from "src/store/Slices/popupSlice";
import { secondaryButton } from "src/components/styles/customStyles";
import { setSharedInfo } from "src/store/Slices/sharedInfoSlice";
import { RootState } from "../../store/store";
import { Sharedinfo, Test } from "../../types/types";
import CloseIcon from "@mui/icons-material/Close";
import IconButton from "@mui/material/IconButton";
import ArrowUpwardIcon from "@mui/icons-material/ArrowUpward";

const testNameMap: Record<string, string> = {
  'GRE': 'Graduate Record Examination',
  'GMAT': 'Graduate Management Admission Test',
  'IELTS': 'International English Language Testing System',
  'TOEFL': 'Test of English as a Foreign Language',
  'PTE': 'Pearson Test of English',
  'DET': 'Duolingo English Test',
  'SAT': 'Scholastic Assessment Test',
  'ACT': 'American College Testing',
};

const TestScores = (props: any) => {
  const { setQaTab, qaTab } = props;
  const safeMissingFields = Array.isArray(props.missingFields) ? props.missingFields : [];
  const currentIndex = safeMissingFields.indexOf(qaTab);

  const navigate = useNavigate();
  const [error, setError] = useState<string | undefined>();
  const dispatch = useAppDispatch();
  // const { profileDetails, setProfileDetails } = useContext(Context);
  const [loading, setLoading] = useState(false);
  const testscoresData = useAppSelector((state: RootState) => state.testscores);
  const sharedInfo = useAppSelector((state: RootState) => state.sharedInfo);

  //   function date(date) {
  //     const month = date.toLocaleString("default", { month: "short" });
  //     const year = date.getFullYear();
  //     return month + " " + year;
  //   }

  const handleBack = () => {
    if (currentIndex > 0) {
      setQaTab(safeMissingFields[currentIndex - 1]);
    }
  };
  const handleSkip = () => {
    if (currentIndex !== -1 && currentIndex < safeMissingFields.length - 1) {
      setQaTab(safeMissingFields[currentIndex + 1]);
    } else {
      dispatch(closePopup());
    }
  }
  const [fieldName, setFieldName] = useState("");
  // let tests = profileDetails?.tests;

  const handleSubmit = (field: string) => {
    // Map the field name to the full name if needed
    setFieldName(testNameMap[field] || field);
  };
  const submit = async () => {
    if (fieldName === "Not planning to take") {
      setQaTab("englishTest")
    } else {
      // Map the fieldName to the full name for the payload
      const backendTestName = testNameMap[fieldName] || fieldName;
      const selectedTestScores = testScores.find(
        (test) => test.name === backendTestName
      );

      if (!selectedTestScores) {
        console.error("Selected test not found.");
        return;
      }
      const payload = {
        name: backendTestName,
        scores: selectedTestScores.scores[0].map((score) => ({
          description: score.description,
          count: scoreCounts[score.description] || "",
        })),
        testDate: "",
        docId: null,
      };
      // Remove any existing test with the same backend name
      const filteredTests = (testscoresData?.data || []).filter(
        (test: any) => test.name !== backendTestName
      );
      const response = await editProfile({
        tests: [...filteredTests, payload],
      });
      if (response) {
        dispatch(settestScores(response.data.data.tests));
        setScoreCounts({});
        if (currentIndex !== -1 && currentIndex < safeMissingFields.length - 1) {
          setQaTab(safeMissingFields[currentIndex + 1]);
        } else {
          // closePopup();
        }
      }
    }
  };
  const [scoreCounts, setScoreCounts] = useState<{
    [description: string]: string;
  }>({});

  const handleCountChange = (description: string, value: string) => {
    setScoreCounts((prevCounts) => ({
      ...prevCounts,
      [description]: value,
    }));
  };
  interface Score {
    description: string;
    count: string;
    range: string;
  }

  interface TestScore {
    name: string;
    scores: Score[][];
    tookTest: string;
  }


  const parseRange = (range: string) => {
    const [min, max] = range.split('-').map(Number);
    return { min, max };
  };

  const validateScore = (count: number, range: string): string | undefined => {
    const { min, max } = parseRange(range);
    const numberValue = Number(count);

    if (numberValue < min || numberValue > max) {
      return `Score must be between ${min} and ${max}`;
    }

    return undefined;
  };

  interface TestScoreFormProps {
    selectedTest: string;
    validateScore: (count: number, range: string) => string | undefined;
  }

  const TestScoreForm: React.FC<TestScoreFormProps> = ({ selectedTest, validateScore }) => {
    const selectedTestScores = testScores?.find((test) => test.name === selectedTest);
    const sharedInfo = useAppSelector((state: RootState) => state.sharedInfo);

    const parseRange = (range: string) => {
      const [min, max] = range.split('-').map(Number);
      return { min, max };
    };

    const requiredFields = selectedTestScores?.requiredFields || [];

    const computeTotal = (scores: Score[]): string => {
      const totalField = scores.find((score) => score.description === "Total");
      if (!totalField) return "";

      const relevantScores = scores.filter((score) =>
        requiredFields.includes(score.description) && score.count !== ""
      );

      if (relevantScores.length === 0) return "Invalid Total";

      let total = 0;
      if (selectedTestScores?.method === "add") {
        total = relevantScores.reduce(
          (acc, score) => acc + (parseInt(score.count) || 0),
          0
        );
      } else if (selectedTestScores?.method === "average") {
        total = relevantScores.reduce(
          (acc, score) => acc + (parseInt(score.count) || 0),
          0
        );
        total = relevantScores.length > 0 ? total / relevantScores.length : 0;
      }

      const { min, max } = parseRange(totalField.range);
      return total >= min && total <= max ? total.toString() : "Invalid Total";
    };

    const formik = useFormik({
      initialValues: {
        name: selectedTest,
        scores: selectedTestScores ? selectedTestScores.scores : [],
        testDate: "",
        docId: null,
      },
      onSubmit: async (values) => {
        let data = {
          name: values.name,
          scores: selectedTestScores ? values.scores[0] : [],
          testDate: values.testDate,
          docId: values.docId,
        }

        if (selectedTest === "Not planning to take" || selectedTest === "") {
          // setQaTab("englishTest")
            try {
              const response = await editProfile({ isPlanningToTakeAcademicTest:"No" });
              dispatch(
                setSharedInfo({
                  ...sharedInfo.data,
                  isPlanningToTakeAcademicTest: response.data.data.isPlanningToTakeAcademicTest,
                })
              );
              setQaTab("englishTest")
            } catch (error) {
              console.error("Error in API Call:", error);
            }

        } else {
          const response = await editProfile({
            tests: [...testscoresData?.data, data],
          });
          if (response) {
            dispatch(settestScores(response.data.data.tests));
            setScoreCounts({});
            if (currentIndex !== -1 && currentIndex < safeMissingFields.length - 1) {
              setQaTab(safeMissingFields[currentIndex + 1]);
            } else {
              dispatch(closePopup())
            }
            setQaTab("englishTest")
          }
        }

      },
      validate: (values) => {
        const errors: any = {};
        values.scores.forEach((scoreArray, scoreArrayIndex) => {
          scoreArray.forEach((score, scoreIndex) => {
            if (score.description === "Total") return;

            const { min, max } = parseRange(score.range);
            const count = Number(score.count);

            if (count < min || count > max) {
              if (!errors.scores) errors.scores = [];
              if (!errors.scores[scoreArrayIndex]) errors.scores[scoreArrayIndex] = [];
              errors.scores[scoreArrayIndex][scoreIndex] = `Score must be between ${min} and ${max}`;
            }
          });
        });
        return errors;
      },
    });

    return (
      <form onSubmit={formik.handleSubmit}>
        <Box sx={{ height: "350px" }}>
          <Grid container spacing={3} >
            {formik.values.scores.map((scoreArray, scoreArrayIndex) =>
              scoreArray.map((score, scoreIndex) => {
                if (score.description === "Total") return null;

                return (
                  <Grid item xs={12} sm={4} key={`${scoreArrayIndex}-${scoreIndex}`}>
                    <div style={{ display: "flex", flexDirection: "column" }}>
                      <InputLabel sx={{ fontWeight: 500, color: "#000" }}>
                        {score.description}
                      </InputLabel>
                      <TextField
                        type="number"
                        name={`scores[${scoreArrayIndex}][${scoreIndex}].count`}
                        value={score.count}
                        onChange={(e) => {
                          formik.handleChange(e);
                          const updatedScores = [...formik.values.scores[scoreArrayIndex]];
                          updatedScores[scoreIndex].count = e.target.value;

                          const allFieldsFilled = updatedScores
                            .filter((score) => score.description !== "Total")
                            .every((score) => score.count !== "");

                          if (allFieldsFilled) {
                            const totalIndex = updatedScores.findIndex((s) => s.description === "Total");
                            if (totalIndex !== -1) {
                              updatedScores[totalIndex].count = String(computeTotal(updatedScores));
                            }
                          }

                          formik.setFieldValue(`scores[${scoreArrayIndex}]`, updatedScores);
                        }}
                        size="small"
                        variant="outlined"
                        placeholder={`${score.range}`}
                      />
                      {formik.errors.scores &&
                        formik.errors.scores[scoreArrayIndex] &&
                        formik.errors.scores[scoreArrayIndex][scoreIndex] && (
                          <div style={{ color: "red", fontSize: "12px" }}>
                            {String(formik.errors.scores[scoreArrayIndex][scoreIndex])}
                          </div>
                        )}
                    </div>
                  </Grid>
                );
              })
            )}
          </Grid>
        </Box>
        <Stack
          direction="row"
          spacing={3}
          sx={{
            justifyContent: "center", alignItems: "center"
          }}
        >
          {currentIndex > 0 && (
            <Button sx={secondaryButton} onClick={handleBack}>
              Back
            </Button>
          )}
          <Button
            type="submit"
            // variant="contained"
            sx={secondaryButton}
          >
            Continue
          </Button>
          <Button sx={secondaryButton} onClick={handleSkip}>
            {loading ? (
              <img
                src={Images.standardLoader}
                alt="load"
                style={{
                  width: "20px",
                  height: "20px",
                  padding: "5px",
                }}
              />
            ) : (
              "Skip"
            )}
          </Button>
        </Stack>
      </form>
    );
  };
  const testOptions = [
    { label: "GRE", value: "Graduate Record Examination" },
    { label: "GMAT", value: "Graduate Management Admission Test" },
    { label: "Not planning to take ", value: "Not planning to take" },
  ];

  // Helper to get test by name
  const getTestByName = (name: string) =>
    testscoresData?.data?.find((test: any) => test.name?.toLowerCase().includes(name.toLowerCase()));

  // English Proficiency Test
  const englishTest = getTestByName("toefl") || getTestByName("ielts") || getTestByName("pte") || getTestByName("duolingo");

  // GRE/GMAT Test
  const greTest = getTestByName("gre");
  const gmatTest = getTestByName("gmat");

  const [editMode, setEditMode] = useState(false);
  const [greEditMode, setGreEditMode] = useState(false);
  // Placeholder demo state for edit UI
  const [isGRESelected, setIsGRESelected] = useState("yes");
  const [selectedGRETest, setSelectedGRETest] = useState("");
  const academicTests: any[] = [];
  const academicTestNames: any[] = [];
  const AcademicTestNamesEnum = {};
  const eventHandler = ({ name, data }: { name: string; data: any }) => {
    if (name === "academicTestSelection") setIsGRESelected(data);
    if (name === "academicTest") setSelectedGRETest(data);
  };

  // Add separate state/handlers for English test edit section
  const [isEnglishSelected, setIsEnglishSelected] = useState("");
  const [selectedEnglishTest, setSelectedEnglishTest] = useState("");
  const englishTests: any[] = [];
  const englishTestNames: any[] = [];
  const englishEventHandler = ({ name, data }: { name: string; data: any }) => {
    if (name === "englishTestSelection") setIsEnglishSelected(data);
    if (name === "englishTest") setSelectedEnglishTest(data);
  };

  // Example static data for demonstration (replace with your dynamic data as needed)
  type TestScoreData = {
    name: string;
    scores: { label: string; value: string }[];
    testDate?: string;
    document?: { name: string; icon: string };
  };

  const initialEnglishTestData: TestScoreData | null = null; // or an object if data exists
  const initialGreTestData: TestScoreData | null = {
    name: 'GRE',
    scores: [
      { label: 'Verbal Reasoning', value: '130–170' },
      { label: 'Quantitative Reasoning', value: '130–170' },
      { label: 'Analytical Writing Assessment', value: '1–6' },
    ],
    testDate: '06-03-2024',
    document: { name: 'GRE.pdf', icon: Images.pdfIcon },
  };

  const [englishEditMode, setEnglishEditMode] = useState(false);
  const [greTestData, setGreTestData] = useState<TestScoreData | null>(initialGreTestData);
  const [englishTestData, setEnglishTestData] = useState<TestScoreData | null>(initialEnglishTestData);
  const [englishForm, setEnglishForm] = useState<TestScoreData | null>(null);
  const [greForm, setGreForm] = useState<TestScoreData | null>(null);

  const [showEnglishTestForm, setShowEnglishTestForm] = useState(false);
  const [showGRETestForm, setShowGRETestForm] = useState(false);

  const [isAddingEnglishTest, setIsAddingEnglishTest] = useState(false);
  const [isAddingGRETest, setIsAddingGRETest] = useState(false);

  // Helper to map long test names to short forms
  const getShortTestName = (name: string) => {
    if (!name) return '';
    const map: Record<string, string> = {
      'International English Language Testing System': 'IELTS',
      'Test of English as a Foreign Language': 'TOEFL',
      'Pearson Test of English': 'PTE',
      'Duolingo English Test': 'Duolingo',
      'Graduate Record Examination': 'GRE',
      'Graduate Management Admission Test': 'GMAT',
    };
    return map[name] || name;
  };

  let greTotalScoreBox = null;
  if (
    greTest &&
    Array.isArray(greTest.scores) &&
    greTest.scores.length > 0
  ) {
    let totalScore = null;
    if (Array.isArray(greTest.scores[0])) {
      totalScore = greTest.scores[0].find((s) => s.description?.toLowerCase() === 'total');
    } else {
      totalScore = greTest.scores.find((s) => s.description?.toLowerCase() === 'total');
    }
    if (totalScore) {
      greTotalScoreBox = (
        <Box>
          <Typography fontWeight={600} sx={{ mb: 1 }}>{greTest.name}</Typography>
          <Box sx={{ display: 'flex', gap: 3 }}>
            <Box sx={{ minWidth: 90 }}>
              <Typography fontWeight={700} color="#1C1F40">{totalScore.count}</Typography>
              <Typography color="#888" fontSize={14}>{totalScore.description}</Typography>
            </Box>
          </Box>
        </Box>
      );
    }
  }

  return (
    <>
      {/* English Proficiency Test Card */}
      <Box
        sx={{
          background: "#fff",
          borderRadius: "20px",
          boxShadow: 1,
          p: 3,
          mb: 3,
          display: "flex",
          flexDirection: "column",
          minWidth: 0,
        }}
      >
        <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <Typography  variant="h6" fontWeight={700}>
            English Proficiency Test
          </Typography>
          <Box sx={{ display: "flex", gap: 1 }}>
            <Button variant="outlined" size="small" sx={{ minWidth: 64, borderRadius: "20px" }} onClick={() => {
              setEnglishEditMode(true);
            }}>Edit</Button>
            <Button variant="outlined" size="small" sx={{ borderRadius: "50%", minWidth: 36, width: 36, height: 36 }} onClick={() => {
              setIsAddingEnglishTest(true);
              setShowEnglishTestForm(true);
              setEnglishForm({
                name: '',
                scores: [
                  { label: 'Reading', value: '' },
                  { label: 'Writing', value: '' },
                  { label: 'Speaking', value: '' },
                  { label: 'Listening', value: '' },
                ],
                testDate: '',
                document: { name: '', icon: Images.pdfIcon }
              });
            }}>+</Button>
          </Box>
        </Box>
        <Box sx={{ mt: 2, background: "#F4F4FF", borderRadius: "10px", p: 1 }}>
          <Dialog
            open={englishEditMode}
            onClose={() => setEnglishEditMode(false)}
            maxWidth="md"
            fullWidth
            PaperProps={{
              sx: {
                borderRadius: '16px',
                background: '#f4f4ff',
                boxShadow: 4,
                p: 0,
              }
            }}
          >
            <Box sx={{ position: 'relative', p: 3 }}>
              {/* Custom close button */}
              <IconButton
                onClick={() => setEnglishEditMode(false)}
                sx={{
                  position: 'absolute',
                  top: 12,
                  right: 12,
                  width: 32,
                  height: 32,
                  borderRadius: '50%',
                  color: '#e74c3c',
                  background: 'transparent',
                  '&:hover': { background: '#f4f4f4' }
                }}
              >
                <CloseIcon />
              </IconButton>
              {/* Question and radio group */}
              <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                <Box sx={{
                  width: 12, height: 12, borderRadius: '50%',
                  background: '#FF9685', mr: 1
                }} />
                <Typography fontWeight={700} sx={{ mr: 2,color:"#495053" }}>
                  Have you taken English Proficiency Test?
                </Typography>
                <Box sx={{ flexGrow: 1 }} />
                <Select
                  value={selectedEnglishTest}
                  onChange={e => {
                    setSelectedEnglishTest(e.target.value);
                    setShowEnglishTestForm(true);
                  }}
                  disabled={isEnglishSelected !== 'yes'}
                  displayEmpty
                  sx={{
                    borderRadius: '20px',
                    background: '#fff',
                    minWidth: 180,
                    fontWeight: 600,
                    fontSize: 16,
                    '.MuiOutlinedInput-notchedOutline': { borderColor: '#bdbdbd' },
                    '&.Mui-disabled': {
                      background: '#f5f5f5',
                      color: '#9e9e9e'
                    }
                  }}
                >
                  <MenuItem value="" disabled>Select a test</MenuItem>
                  <MenuItem value="toefl">TOEFL</MenuItem>
                  <MenuItem value="ielts">IELTS</MenuItem>
                  <MenuItem value="pte">PTE</MenuItem>
                  <MenuItem value="duolingo">Duolingo</MenuItem>
                </Select>
              </Box>
              <RadioGroup
                row
                value={isEnglishSelected}
                onChange={e => {
                  setIsEnglishSelected(e.target.value);
                  if (e.target.value !== 'yes') {
                    setSelectedEnglishTest('');
                  }
                }}
                sx={{ mb: 2 }}
              >
                <FormControlLabel value="yes" control={<Radio />} label="Yes" />
                <FormControlLabel value="planning" control={<Radio />} label="Planning to take" />
                <FormControlLabel value="not" control={<Radio />} label="Not planning to take" />
              </RadioGroup>
            </Box>
          </Dialog>
          {!englishEditMode && (englishTestData !== null ? (
            (() => {
              const data: TestScoreData = englishTestData;
              return (
                <>
                  <Typography sx={{ fontWeight: 600, background: "#f6f7ff", p: 1, borderRadius: 1, mb: 2 }}>
                    {getShortTestName(data.name)}
                  </Typography>
                  <Grid container spacing={2}>
                    {data.scores.map((score: { label: string; value: string }, idx: number) => (
                      <Grid item xs={12} sm={6} md={3} key={idx}>
                        <Typography color="text.secondary">{score.label === 'Total' ? 'Average' : score.label}</Typography>
                        <Typography fontWeight={700}>
                          {score.label === 'Total'
                            ? (() => {
                                // Compute average of the other scores
                                const values = data.scores.filter(s => s.label !== 'Total').map(s => parseFloat(s.value)).filter(v => !isNaN(v));
                                if (values.length === 0) return '';
                                return (values.reduce((a, b) => a + b, 0) / values.length).toFixed(2);
                              })()
                            : score.value}
                        </Typography>
                      </Grid>
                    ))}
                    {data.testDate && (
                      <Grid item xs={12} sm={6} md={3}>
                        <Typography color="text.secondary">Took Test on</Typography>
                        <Typography fontWeight={700}>{data.testDate}</Typography>
                      </Grid>
                    )}
                    {data.document && (
                      <Grid item xs={12} sm={6} md={3}>
                        <Typography color="text.secondary">Document</Typography>
                        <Stack direction="row" alignItems="center" spacing={1}>
                          <img src={data.document.icon} alt="pdf" style={{ width: 20, height: 20 }} />
                          <Typography>{data.document.name}</Typography>
                        </Stack>
                      </Grid>
                    )}
                  </Grid>
                </>
              );
            })()
          ) : (
            <>
              <Typography>Have you taken any English Proficiency test</Typography>
              <Typography fontWeight={700}>NA</Typography>
            </>
          ))}
        </Box>
      </Box>

      {/* GRE/GMAT Test Card */}
      <Box
        sx={{
          background: "#fff",
          borderRadius: "20px",
          boxShadow: 1,
          p: 3,
          mb: 3,
          display: "flex",
          flexDirection: "column",
          minWidth: 0,
        }}
      >
        <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <Typography sx={{color:"#3b3f76"}} variant="h6" fontWeight={700}>
            GRE/GMAT Test
          </Typography>
          <Box sx={{ display: "flex", gap: 1 }}>
            <Button variant="outlined" size="small" sx={{ minWidth: 64, borderRadius: "20px" }} onClick={() => {
              setGreEditMode(true);
              setGreForm(greTestData || {
                name: 'GRE',
                scores: [
                  { label: 'Verbal Reasoning', value: '' },
                  { label: 'Quantitative Reasoning', value: '' },
                  { label: 'Analytical Writing Assessment', value: '' },
                ],
                testDate: '',
                document: { name: '', icon: Images.pdfIcon }
              });
            }}>Edit</Button>
            <Button variant="outlined" size="small" sx={{ borderRadius: "50%", minWidth: 36, width: 36, height: 36 }} onClick={() => {
              setIsAddingGRETest(true);
              setShowGRETestForm(true);
              setGreForm({
                name: '',
                scores: [
                  { label: 'Verbal Reasoning', value: '' },
                  { label: 'Quantitative Reasoning', value: '' },
                  { label: 'Analytical Writing Assessment', value: '' },
                ],
                testDate: '',
                document: { name: '', icon: Images.pdfIcon }
              });
            }}>+</Button>
          </Box>
        </Box>
        <Box sx={{ mt: 2, background: "#F4F4FF", borderRadius: "10px", p: 1 }}>
          {greTestData !== null ? (
            (() => {
              const data = greTestData;
              return (
                <>
                  <Typography sx={{ fontWeight: 600, background: "#f6f7ff", p: 1, borderRadius: 1, mb: 2 }}>
                    {getShortTestName(data.name)}
                  </Typography>
                  <Grid container spacing={2}>
                    {data.scores.map((score, idx) => (
                      <Grid item xs={12} sm={6} md={3} key={idx}>
                        <Typography color="text.secondary">{score.label === 'Total' ? 'Average' : score.label}</Typography>
                        <Typography fontWeight={700}>
                          {score.label === 'Total'
                            ? (() => {
                                const values = data.scores.filter(s => s.label !== 'Total').map(s => parseFloat(s.value)).filter(v => !isNaN(v));
                                if (values.length === 0) return '';
                                return (values.reduce((a, b) => a + b, 0) / values.length).toFixed(2);
                              })()
                            : score.value}
                        </Typography>
                      </Grid>
                    ))}
                    {data.testDate && (
                      <Grid item xs={12} sm={6} md={3}>
                        <Typography color="text.secondary">Took Test on</Typography>
                        <Typography fontWeight={700}>{data.testDate}</Typography>
                      </Grid>
                    )}
                    {data.document && (
                      <Grid item xs={12} sm={6} md={3}>
                        <Typography color="text.secondary">Document</Typography>
                        <Stack direction="row" alignItems="center" spacing={1}>
                          <img src={data.document.icon} alt="pdf" style={{ width: 20, height: 20 }} />
                          <Typography>{data.document.name}</Typography>
                        </Stack>
                      </Grid>
                    )}
                  </Grid>
                </>
              );
            })()
          ) : (
            <>
              <Typography>Have you taken any GRE/GMAT test</Typography>
              <Typography fontWeight={700}>NA</Typography>
            </>
          )}
        </Box>
      </Box>

      {/* English Test Form Modal */}
      <Dialog
        open={showEnglishTestForm}
        onClose={() => {
          setShowEnglishTestForm(false);
          setIsAddingEnglishTest(false);
        }}
        maxWidth="md"
        fullWidth
        PaperProps={{
          sx: {
            borderRadius: '16px',
            background: '#fff',
            boxShadow: 4,
            p: 0,
          }
        }}
      >
        <Box sx={{ position: 'relative', p: 4 }}>
          <Typography variant="h6" fontWeight={700} sx={{ mb: 3 }}>
            <Box component="span" sx={{
              display: 'inline-block',
              width: 16,
              height: 16,
              borderRadius: '50%',
              background: '#FF9685',
              mr: 1,
              verticalAlign: 'middle'
            }} />
            {selectedEnglishTest ? `Test of English as a Foreign Language` : ''}
          </Typography>
          <form onSubmit={e => {
            e.preventDefault();
            if (isAddingEnglishTest) {
              // Add new test
              setEnglishTestData(englishForm);
            } else {
              // Edit existing test
              setEnglishTestData(englishForm);
            }
            setShowEnglishTestForm(false);
            setIsAddingEnglishTest(false);
          }}>
            <Grid container spacing={3}>
              <Grid item xs={12} sm={6} md={3}>
                <Typography fontWeight={600}>Reading</Typography>
                <TextField placeholder="1-30" fullWidth sx={{ mt: 1 }} value={englishForm?.scores[0]?.value || ''} onChange={e => setEnglishForm(f => f ? { ...f, scores: f.scores.map((s, i) => i === 0 ? { ...s, value: e.target.value } : s) } : null)} />
              </Grid>
              <Grid item xs={12} sm={6} md={3}>
                <Typography fontWeight={600}>Writing</Typography>
                <TextField placeholder="1-30" fullWidth sx={{ mt: 1 }} value={englishForm?.scores[1]?.value || ''} onChange={e => setEnglishForm(f => f ? { ...f, scores: f.scores.map((s, i) => i === 1 ? { ...s, value: e.target.value } : s) } : null)} />
              </Grid>
              <Grid item xs={12} sm={6} md={3}>
                <Typography fontWeight={600}>Speaking</Typography>
                <TextField placeholder="1-30" fullWidth sx={{ mt: 1 }} value={englishForm?.scores[2]?.value || ''} onChange={e => setEnglishForm(f => f ? { ...f, scores: f.scores.map((s, i) => i === 2 ? { ...s, value: e.target.value } : s) } : null)} />
              </Grid>
              <Grid item xs={12} sm={6} md={3}>
                <Typography fontWeight={600}>Listening</Typography>
                <TextField placeholder="1-30" fullWidth sx={{ mt: 1 }} value={englishForm?.scores[3]?.value || ''} onChange={e => setEnglishForm(f => f ? { ...f, scores: f.scores.map((s, i) => i === 3 ? { ...s, value: e.target.value } : s) } : null)} />
              </Grid>
              <Grid item xs={12} sm={6} md={3}>
                <Typography fontWeight={600}>Took test on</Typography>
                <TextField placeholder="Took test on" fullWidth sx={{ mt: 1 }} value={englishForm?.testDate || ''} onChange={e => setEnglishForm(f => f ? { ...f, testDate: e.target.value } : null)} />
              </Grid>
              <Grid item xs={12} md={12}>
                <Typography fontWeight={600}>
                  Upload file <span style={{ color: '#888', fontSize: 16 }}>ⓘ</span>
                </Typography>
                <Button
                  component="label"
                  sx={{
                    mt: 1,
                    border: '1px dashed #aaa',
                    borderRadius: 2,
                    minWidth: 40,
                    minHeight: 40,
                    color: '#3B3F76',
                    background: '#fafaff',
                    '&:hover': { background: '#f4f4ff' },
                  }}
                >
                  <ArrowUpwardIcon />
                  <input type="file" hidden />
                </Button>
              </Grid>
            </Grid>
            <Box sx={{ display: 'flex', justifyContent: 'flex-end', gap: 2, mt: 4 }}>
              <Button
                onClick={() => {
                  setShowEnglishTestForm(false);
                  setIsAddingEnglishTest(false);
                }}
                variant="outlined"
                sx={{
                  borderRadius: '20px',
                  px: 4,
                  py: 1,
                  fontWeight: 700,
                  fontSize: 18,
                  color: '#3B3F76',
                  borderColor: '#3B3F76',
                  background: '#f8f8ff',
                  '&:hover': { background: '#e6e6fa' },
                }}
              >
                Cancel
              </Button>
              <Button
                type="submit"
                variant="outlined"
                sx={{
                  borderRadius: '20px',
                  px: 4,
                  py: 1,
                  fontWeight: 700,
                  fontSize: 18,
                  color: '#3B3F76',
                  borderColor: '#3B3F76',
                  background: '#f8f8ff',
                  '&:hover': { background: '#e6e6fa' },
                }}
              >
                Submit
              </Button>
            </Box>
          </form>
        </Box>
      </Dialog>

      {/* GRE Test Form Modal */}
      <Dialog
        open={showGRETestForm}
        onClose={() => {
          setShowGRETestForm(false);
          setIsAddingGRETest(false);
        }}
        maxWidth="md"
        fullWidth
        PaperProps={{
          sx: {
            borderRadius: '16px',
            background: '#fff',
            boxShadow: 4,
            p: 0,
          }
        }}
      >
        <Box sx={{ position: 'relative', p: 4 }}>
          <Typography variant="h6" fontWeight={700} sx={{ mb: 3 }}>
            <Box component="span" sx={{
              display: 'inline-block',
              width: 16,
              height: 16,
              borderRadius: '50%',
              background: '#FF9685',
              mr: 1,
              verticalAlign: 'middle'
            }} />
            {selectedGRETest === 'gre' ? 'GRE' : selectedGRETest === 'gmat' ? 'GMAT' : ''}
          </Typography>
          <form onSubmit={e => {
            e.preventDefault();
            if (!greForm || !greForm.scores || greForm.scores.length < 3) {
              alert('Please fill all GRE fields.');
              return;
            }
            // Calculate Total
            const v = parseFloat(greForm.scores[0].value);
            const q = parseFloat(greForm.scores[1].value);
            const a = parseFloat(greForm.scores[2].value);
            let total = '';
            if (!isNaN(v) && !isNaN(q) && !isNaN(a)) {
              total = String(v + q + a);
            }
            // Build new scores array with Total
            const scoresWithTotal = [
              ...greForm.scores,
              { label: 'Total', value: total }
            ];
            const newGreData = {
              ...greForm,
              scores: scoresWithTotal,
            };
            setGreTestData(newGreData);
            setShowGRETestForm(false);
            setIsAddingGRETest(false);
          }}>
            <Grid container spacing={3}>
              <Grid item xs={12} sm={6} md={3}>
                <Typography fontWeight={600}>Verbal Reasoning</Typography>
                <TextField placeholder="130–170" fullWidth sx={{ mt: 1 }} value={greForm?.scores[0]?.value || ''} onChange={e => setGreForm(f => f ? { ...f, scores: f.scores.map((s, i) => i === 0 ? { ...s, value: e.target.value } : s) } : null)} />
              </Grid>
              <Grid item xs={12} sm={6} md={3}>
                <Typography fontWeight={600}>Quantitative Reasoning</Typography>
                <TextField placeholder="130–170" fullWidth sx={{ mt: 1 }} value={greForm?.scores[1]?.value || ''} onChange={e => setGreForm(f => f ? { ...f, scores: f.scores.map((s, i) => i === 1 ? { ...s, value: e.target.value } : s) } : null)} />
              </Grid>
              <Grid item xs={12} sm={6} md={3}>
                <Typography fontWeight={600}>
                  Analytical Writing<br />Assessment
                </Typography>
                <TextField placeholder="1–6" fullWidth sx={{ mt: 1 }} value={greForm?.scores[2]?.value || ''} onChange={e => setGreForm(f => f ? { ...f, scores: f.scores.map((s, i) => i === 2 ? { ...s, value: e.target.value } : s) } : null)} />
              </Grid>
              <Grid item xs={12} sm={6} md={3}>
                <Typography fontWeight={600}>Took test on</Typography>
                <TextField placeholder="Took test on" fullWidth sx={{ mt: 1 }} value={greForm?.testDate || ''} onChange={e => setGreForm(f => f ? { ...f, testDate: e.target.value } : null)} />
              </Grid>
              <Grid item xs={12} md={12}>
                <Typography fontWeight={600}>
                  Upload file <span style={{ color: '#888', fontSize: 16 }}>ⓘ</span>
                </Typography>
                <Button
                  component="label"
                  sx={{
                    mt: 1,
                    border: '1px dashed #aaa',
                    borderRadius: 2,
                    minWidth: 40,
                    minHeight: 40,
                    color: '#3B3F76',
                    background: '#fafaff',
                    '&:hover': { background: '#f4f4ff' },
                  }}
                >
                  <ArrowUpwardIcon />
                  <input type="file" hidden />
                </Button>
              </Grid>
            </Grid>
            <Box sx={{ display: 'flex', justifyContent: 'flex-end', gap: 2, mt: 4 }}>
              <Button
                onClick={() => {
                  setShowGRETestForm(false);
                  setIsAddingGRETest(false);
                }}
                variant="outlined"
                sx={{
                  borderRadius: '20px',
                  px: 4,
                  py: 1,
                  fontWeight: 700,
                  fontSize: 18,
                  color: '#3B3F76',
                  borderColor: '#3B3F76',
                  background: '#f8f8ff',
                  '&:hover': { background: '#e6e6fa' },
                }}
              >
                Cancel
              </Button>
              <Button
                type="submit"
                variant="outlined"
                sx={{
                  borderRadius: '20px',
                  px: 4,
                  py: 1,
                  fontWeight: 700,
                  fontSize: 18,
                  color: '#3B3F76',
                  borderColor: '#3B3F76',
                  background: '#f8f8ff',
                  '&:hover': { background: '#e6e6fa' },
                }}
              >
                Submit
              </Button>
            </Box>
          </form>
        </Box>
      </Dialog>
    </>
  );
};

export default TestScores;
