import { useDispatch, useSelector} from "react-redux"
import { useRef } from "react"
import { AppDispatch, RootState } from "../store/store"
import { closePopup } from "../store/Slices/popupSlice"
import { setUserAuthStatus } from "../store/Slices/userAuthSlice"

export const useAppDispatch = useDispatch.withTypes<AppDispatch>()
export const useAppSelector = useSelector.withTypes<RootState>()
//export const useAppStore = useStore.withTypes<AppStore>()

// Custom hook for closing popups with scroll position restoration
export const usePopupClose = () => {
  const dispatch = useAppDispatch();
  const scrollRestoreTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  
  const closePopupWithScrollRestore = () => {
    // Restore scroll position if it was stored (for explore section)
    const savedScrollPosition = localStorage.getItem('exploreScrollPosition');
    console.log('=== POPUP CLOSE DEBUG ===');
    console.log('Popup closing, saved scroll position:', savedScrollPosition);
    console.log('Current scroll position before restoration:', window.scrollY);
    
    if (savedScrollPosition) {
      // Clear any existing timeout
      if (scrollRestoreTimeoutRef.current) {
        clearTimeout(scrollRestoreTimeoutRef.current);
      }
      
      // Use multiple attempts to ensure scroll restoration works
      const scrollPosition = parseInt(savedScrollPosition);
      
      // Temporarily disable smooth scrolling
      const originalScrollBehavior = document.body.style.scrollBehavior;
      document.body.style.scrollBehavior = 'auto';
      
      // Immediate attempt
      console.log('Attempting immediate scroll restoration to:', scrollPosition);
      window.scrollTo(0, scrollPosition);
      
      // Delayed attempts to ensure it works
      scrollRestoreTimeoutRef.current = setTimeout(() => {
        console.log('Attempting scroll restoration after delay to:', scrollPosition);
        window.scrollTo(0, scrollPosition);
        document.documentElement.scrollTop = scrollPosition;
        document.body.scrollTop = scrollPosition;
        
        // Final attempt
        setTimeout(() => {
          console.log('Final scroll restoration attempt to:', scrollPosition);
          window.scrollTo(0, scrollPosition);
          console.log('Scroll position after final attempt:', window.scrollY);
          
          // Restore smooth scrolling
          document.body.style.scrollBehavior = originalScrollBehavior;
          
          // Remove scroll position after a longer delay to ensure ScrollToTop doesn't override
          setTimeout(() => {
            localStorage.removeItem('exploreScrollPosition');
            console.log('Removed stored scroll position after delay');
          }, 500);
        }, 50);
      }, 200);
    } else {
      console.log('No saved scroll position found');
    }
    dispatch(closePopup());
  };
  
  return closePopupWithScrollRestore;
};

// Custom hook for authentication state management
export const useAuth = () => {
  const userAuthStatus = useAppSelector((state) => state.userAuthStatus);
  const dispatch = useAppDispatch();
  
  const isAuthenticated = () => {
    const token = localStorage.getItem("_auth");
    const hasToken = token && token.trim() !== "";
    const isAuthorized = userAuthStatus.data?.isAuthorized;
    
    // If there's a token but Redux state says not authorized, update Redux state
    if (hasToken && !isAuthorized) {
      dispatch(
        setUserAuthStatus({
          isAuthorized: true,
          isRegistered: true,
          role: "student",
        })
      );
      return true;
    }
    
    // If no token but Redux state says authorized, clear Redux state
    if (!hasToken && isAuthorized) {
      dispatch(
        setUserAuthStatus({
          isAuthorized: false,
          isRegistered: false,
          role: "guest",
        })
      );
      return false;
    }
    
    return hasToken && isAuthorized;
  };
  
  return {
    isAuthenticated: isAuthenticated(),
    userAuthStatus: userAuthStatus.data,
  };
};