// Function to filter ranking data by year (show only previous year's data)
const filterRankingByYear = (rankingData: any) => {
  if (!rankingData || typeof rankingData !== 'object') {
    return {};
  }

  const currentYear = new Date().getFullYear();
  const previousYear = currentYear - 1;
  
  const filteredRanking: any = {};
  
  Object.entries(rankingData).forEach(([key, value]) => {
    // Check if the key contains the previous year
    if (key.includes(previousYear.toString())) {
      filteredRanking[key] = value;
    }
  });
  
  return filteredRanking;
};

