interface DeadlineInfo {
  deadline: string;
  infoType: string;
}

interface StartDateTab {
  label: string;
  deadlines: DeadlineInfo[];
}

const formatCourseDates = (startDateList: any[], currentDate = new Date()) => {
  console.log('Raw startDateList:', startDateList);
  
  return startDateList.map((item) => {
    console.log('Processing item:', item);
    
    // Handle different possible data structures
    let courseStarting, deadlines;
    
    if (item.courseStarting) {
      // New structure with courseStarting and deadlines
      courseStarting = item.courseStarting;
      deadlines = item.deadlines;
    } else if (item.courseStartingMonth !== undefined) {
      // Old structure with courseStartingMonth
      const monthIdx = item.courseStartingMonth;
      const currentYear = new Date().getFullYear();
      courseStarting = new Date(currentYear, monthIdx, 1);
      deadlines = item.deadlines || [];
    } else {
      // Fallback
      console.log('Unknown data structure:', item);
      return {
        courseString: 'Starting Date TBD',
        deadlineString: 'Deadline TBD'
      };
    }

    if (!deadlines || deadlines.length === 0) {
      return {
        courseString: 'Starting Date TBD',
        deadlineString: 'Deadline TBD'
      };
    }

    const courseOriginal = new Date(courseStarting);
    const deadlineOriginal = new Date(deadlines[0].deadline);

    console.log('Original dates:', { courseOriginal, deadlineOriginal });

    const adjustedDeadline = new Date(deadlineOriginal);
    // Step 1: Make deadline in the future
    while (adjustedDeadline < currentDate) {
      adjustedDeadline.setFullYear(adjustedDeadline.getFullYear() + 1);
    }

    // Step 2: Adjust courseStarting to be after adjustedDeadline
    const adjustedStart = new Date(courseOriginal);
    while (adjustedStart <= adjustedDeadline) {
      adjustedStart.setFullYear(adjustedStart.getFullYear() + 1);
    }

    console.log('Adjusted dates:', { adjustedStart, adjustedDeadline });

    const courseString = ` ${adjustedStart.toLocaleString('default', { month: 'long' })} ${adjustedStart.getFullYear()}`;
    const deadlineString = `${adjustedDeadline.toLocaleString('default', { month: 'short' })} ${adjustedDeadline.getFullYear()}`;

    console.log('Formatted strings:', { courseString, deadlineString });

    return { courseString, deadlineString };
  });
};

const getStartDateTabs = (startDateArr: any[]): StartDateTab[] => {
  console.log('getStartDateTabs called with:', startDateArr);
  
  if (!Array.isArray(startDateArr)) {
    console.log('startDateArr is not an array, returning empty array');
    return [];
  }
  
  // Use the new date formatting logic
  const formattedDates = formatCourseDates(startDateArr);
  console.log('formattedDates:', formattedDates);
  
  const result = formattedDates.map((formattedItem, index) => {
    const originalItem = startDateArr[index];
    const label = formattedItem.courseString;
    // Create a single deadline entry instead of mapping over all deadlines
    const deadlines = (originalItem.deadlines && originalItem.deadlines.length > 0) ? [{
      deadline: formattedItem.deadlineString,
      infoType: originalItem.deadlines[0].deadlineType || originalItem.deadlines[0].deadlineLabel || "Deadline"
    }] : [];
    console.log('Created item:', { label, deadlines });
    return { label, deadlines };
  });
  
  console.log('Final result:', result);
  return result;
};

