export const UpcomingCall=(props:any)=>{
  const filteredEvents = Array.isArray(props.advisor.data) ? props.advisor.data?.filter(
    (event: Event) => event.member._id === props.advisor.data.info?._id
  ) : [];

  const upcomingEvents = Array.isArray(filteredEvents) ? filteredEvents?.filter((item: Event) => item.status === "upcoming") || [] : [];

  const isEmpty = upcomingEvents.length === 0;

  return(
    <Box
      sx={{
        // height: {md: "calc(100vh - 200px)"},
        overflowY: "auto",
        scrollbarWidth: "none",
        "&::-webkit-scrollbar": { display: "none" },
        px: 8,
        py: 2,
        display: isEmpty ? "flex" : "block",
        flexDirection: isEmpty ? "column" : undefined,
        alignItems: isEmpty ? "center" : undefined,
        justifyContent: isEmpty ? "center" : undefined,
        minHeight: isEmpty ? 200 : undefined,
      }}
    >
      {isEmpty ? (
        <Box
          display="flex"
          flexDirection="column"
          alignItems="center"
          justifyContent="center"
          sx={{ minHeight: 220 }}
        >
          <img
            src={Images.Dull}
            alt="No meeting"
            style={{ width: 100, marginBottom: 12, marginTop: 2,  }}
          />
          <Typography
            sx={{
              color: '#FF6B6B',
              fontWeight: 600,
              fontSize: 18,
              mb: 0.5,
              textAlign: 'center',
              fontFamily: 'Inter, sans-serif'
            }}
          >
            There is no meeting history
          </Typography>
          <Typography
            sx={{
              color: '#7B7B9D',
              fontSize: 15,
              textAlign: 'center',
              fontFamily: 'Inter, sans-serif'
            }}
          >
            Looks like you haven't booked any slots yet…..
          </Typography>
        </Box>
      ) : (
        upcomingEvents.map((event: Event, i: number) => (
          <Box
          sx={{
            display: "flex",
            // justifyContent: "center", // centers horizontally
            width: "100%",             // take full width of parent
            mt: 2,   
            mr:10              // optional top margin
          }}
        >
          <Box
            key={i}
            sx={{
              backgroundColor: "#F4F4FF",
              borderRadius: "16px",
              width: "400px",              // fixed width
              padding: "16px",
              boxSizing: "border-box",
              mb: 2,
              display: "flex",
              flexDirection: "column",
              
            }}
          >
            <Box sx={{ display: "flex", gap: "12px",mr:10 }}>
              <img
                src={Images.meeting}
                alt="meeting"
                style={{ width: "20px", height: "20px" }}
              />
              <Box>
                <Typography sx={{ fontWeight: 600, fontSize: "14px", color: "#000" }}>
                  {event?.data?.description
                    ? normalizeType(event?.data?.description)
                    : "N/A"}
                </Typography>
                <Typography sx={{ fontSize: "13px", color: "#5F5F5F", mt: 0.3 }}>
                  {new Date(event?.data?.start?.dateTime || '').toLocaleString("en-GB", {
                    day: "numeric",
                    month: "long",
                    year: "numeric",
                    hour: "numeric",
                    minute: "numeric",
                    hour12: true,
                  })}
                </Typography>
              </Box>
            </Box>
        
            {event.status !== "cancelled" && (
              <Box sx={{ mt: 2, display: "flex", justifyContent: "flex-end",position:'absolute' }}>
                <Button
                  sx={{
                    mt:3,
                    ml:{xs:16,lg:27},
                    backgroundColor: "white",
                    borderRadius:'15px',
                    color: "#000",
                    fontSize: "12px",
                    fontWeight: 500,
                    textTransform: "none",
                    boxShadow: "none",
                    
                  }}
                >
                  <span onClick={() => props.handlers.setRescheduleItem(event)}>Reschedule</span>
                  {" / "}
                  <span
                    onClick={() => props.handlers.setDeleteItem(event?._id)}
                    style={{ cursor: "pointer" }}
                  >
                    Cancel call
                  </span>
                </Button>
              </Box>
            )}
          </Box>
        </Box>
        
        

        ))
      )}
    </Box>
  )
}

export const RescheduleCall=(props:any)=>{
  const filteredEvents = Array.isArray(props.advisor.data) ? props.advisor.data?.filter(
    (event: Event) => event.member._id === props.advisor.data.info?._id
  ) : [];

  const handleReschedule = (item: Event) => {
    if (props.handlers && props.handlers.setRescheduleItem) {
      props.handlers.setRescheduleItem(item);
      props.handlers.setReschedule("rescheduled");
    }
  };

  const handleDeleteOpen = (item: any) => {
    if (props.handlers && props.handlers.setOpen) {
      props.handlers.setOpen(true);
      props.handlers.setDeleteItem(item);
    }
  };

  return(
    <Box
    sx={{
      height: {md:"calc(100vh - 200px)"}, 
      overflowY: "auto",
      scrollbarWidth: "none",
      "&::-webkit-scrollbar": {
        display: "none"
      },
      px: 8,
      py: 2
    }}
    >
    {filteredEvents?.length > 0 ? (
      filteredEvents?.filter((item: Event)=>item.status==="rescheduled").map((event: Event, i: number) => (
        <Box
          key={i}
          sx={{
            position: "relative",
            backgroundColor:"#F4F4FF",
            borderRadius:'20px',
            width:'400px',
            boxSizing:'border-box',
            padding:'10px',
            mb: 2
          }}
        >
          <Typography sx={{
            display: "flex",
            gap: "0.5rem",
            color: "#0000004D", 
            alignItems: "center", 
            fontSize: "12px"
          }}>
            <FiberManualRecordIcon sx={{ 
              color: event.status === "upcoming" ? "#8EFF93" : 
                     event.status === "rescheduled" ? "#ffa500b3" : "#ff0000b5", 
              fontSize: "0.8rem" 
            }} />
            {normalizeType(event.status)}
          </Typography>
          
          <Box sx={{
            display: "flex",
            gap: "1rem",
            alignItems: "center",
            mt: 1
          }}>
            <img src={Images.meeting} alt="meeting" style={{ width: "1.5rem", height: "1.5rem" }} />
            <Box sx={{width:'100%'}}>
              <Typography sx={{ 
                mt: 0.5, 
                fontSize: "14px",
                color: "#3B3F76",
                fontWeight: 500
              }}>
                {event?.data?.description ? normalizeType(event?.data?.description): "N/A"}
              </Typography>
              <Typography
                fontSize="13px"
                gutterBottom
                sx={{ color: 'grey' }}
              >
                {new Date(event?.data?.start?.dateTime || '').toLocaleString(
                  "en-GB",
                  {
                    month: "long",
                    year: "numeric",
                    day: "numeric",
                    hour: "numeric",
                    minute: "numeric",
                    hour12: true,
                  }
                )}
              </Typography>
              { event.status !== "cancelled" && 
              <Box sx={{
                display: "flex",
                justifyContent: "flex-end",
                mt: 1
              }}>
                <Typography sx={{
                  background: "#E0E0F0",
                  p: 1,
                  borderRadius: "20px",
                  fontSize: "12px",
                  color: "#3B3F76",
                  width: "fit-content",
                  fontWeight: 'bold',
                  display: "flex",
                  gap: 1,
                  alignItems: "center"
                }}>
                  <span
                    onClick={() => handleReschedule(event)}
                    style={{ cursor: "pointer" }}
                  >
                    Reschedule
                  </span>
                  <span style={{ color: "#3B3F76" }}>|</span>
                  <span
                    onClick={() => handleDeleteOpen(event?._id)}
                    style={{ cursor: "pointer" }}
                  >
                    Cancel
                  </span>
                </Typography>
              </Box>
              }
            </Box>
          </Box>
        </Box>
      ))
    ) : (
      <Typography textAlign="center" sx={{ mt: 3 }}>
        No sessions
      </Typography>
    )}
    </Box>
  )
}

